NVIDIA_UTILS_PACKAGE_RE = re.compile(r"^nvidia-utils-(\d+)$")


def is_debian_package_installed(package_name: str) -> bool:
    name = str(package_name or "").strip()
    if not name or not has_cmd("dpkg-query"):
        return False
    try:
        result = subprocess.run(
            ["dpkg-query", "-W", "-f=${Status}", name],
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=5,
            check=False,
        )
    except Exception:
        return False
    return result.returncode == 0 and "ok installed" in str(result.stdout or "")


def probe_nvidia_smi_package_candidates():
    if not has_cmd("apt-cache"):
        return {
            "installable": False,
            "preferred_package": "",
            "available_packages": [],
        }

    try:
        result = subprocess.run(
            ["apt-cache", "search", "^nvidia-utils-[0-9]+$"],
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=8,
            check=False,
        )
    except Exception:
        return {
            "installable": False,
            "preferred_package": "",
            "available_packages": [],
        }

    package_candidates = []
    for raw_line in str(result.stdout or "").splitlines():
        line = str(raw_line or "").strip()
        if not line:
            continue
        package_name = line.split(" - ", 1)[0].strip()
        match = NVIDIA_UTILS_PACKAGE_RE.match(package_name)
        if not match:
            continue
        package_candidates.append((int(match.group(1)), package_name))

    package_candidates.sort(key=lambda item: item[0], reverse=True)

    available_packages = []
    for _priority, package_name in package_candidates:
        try:
            policy = subprocess.run(
                ["apt-cache", "policy", package_name],
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
                text=True,
                timeout=8,
                check=False,
            )
        except Exception:
            continue
        candidate_value = ""
        for raw_line in str(policy.stdout or "").splitlines():
            line = str(raw_line or "").strip()
            if line.lower().startswith("candidate:"):
                candidate_value = line.split(":", 1)[1].strip()
                break
        if candidate_value and candidate_value.lower() != "(none)":
            available_packages.append(package_name)

    return {
        "installable": bool(available_packages),
        "preferred_package": available_packages[0] if available_packages else "",
        "available_packages": available_packages,
    }


def detect_nvidia_gpu_present():
    gpu_root = "/proc/driver/nvidia/gpus"
    try:
        if os.path.isdir(gpu_root) and bool(os.listdir(gpu_root)):
            return True
    except Exception:
        pass

    if not has_cmd("lspci"):
        return False

    try:
        result = subprocess.run(
            ["lspci"],
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=5,
            check=False,
        )
    except Exception:
        return False

    return "nvidia" in str(result.stdout or "").lower()


def find_code_the_classics_zip():
    candidates = [
        os.path.join(os.path.dirname(__file__), "features", "Code-the-Classics.zip"),
        CODE_THE_CLASSICS_ZIP_DEV,
        CODE_THE_CLASSICS_ZIP_SYSTEM,
    ]
    for path in candidates:
        if os.path.isfile(path):
            return path
    return ""


