XRANDR_CONNECTED_MONITOR_RE = re.compile(
    r"^(?P<name>\S+)\s+connected(?:\s+(?P<primary>primary))?\s+"
    r"(?P<width>\d+)x(?P<height>\d+)\+(?P<x>-?\d+)\+(?P<y>-?\d+)\b"
)


def _parse_xrandr_monitor_bounds(line: str):
    text = str(line or "").strip()
    if not text:
        return None
    match = XRANDR_CONNECTED_MONITOR_RE.match(text)
    if match is None:
        return None
    try:
        x = int(match.group("x"))
        y = int(match.group("y"))
        width = int(match.group("width"))
        height = int(match.group("height"))
    except Exception:
        return None
    if width <= 0 or height <= 0:
        return None
    return {
        "name": match.group("name"),
        "primary": bool(match.group("primary")),
        "x": x,
        "y": y,
        "width": width,
        "height": height,
    }


def _detect_primary_monitor_bounds():
    display = str(os.environ.get("DISPLAY", "") or "").strip()
    if not display or not has_cmd("xrandr"):
        return None
    try:
        result = subprocess.run(
            ["xrandr", "--query"],
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=3,
            check=False,
        )
    except Exception:
        return None

    monitors = []
    for raw_line in str(result.stdout or "").splitlines():
        parsed = _parse_xrandr_monitor_bounds(raw_line)
        if parsed is not None:
            monitors.append(parsed)
    if not monitors:
        return None

    primary = next((item for item in monitors if item["primary"]), None)
    selected = primary or monitors[0]
    return (
        int(selected["x"]),
        int(selected["y"]),
        int(selected["width"]),
        int(selected["height"]),
    )


def strip_ansi_codes(text: str) -> str:
    return ANSI_RE.sub("", text or "")


def normalize_hex_color(value: str) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if not text.startswith("#"):
        text = f"#{text}"
    if len(text) != 7:
        return ""
    try:
        int(text[1:], 16)
    except ValueError:
        return ""
    return text.lower()


def hex_to_rgb(value: str) -> tuple[int, int, int]:
    color = normalize_hex_color(value)
    if not color:
        raise ValueError(f"invalid color: {value!r}")
    return tuple(int(color[i : i + 2], 16) for i in (1, 3, 5))


def rgb_to_hex(rgb: tuple[int, int, int]) -> str:
    red, green, blue = (
        max(0, min(255, int(round(channel)))) for channel in tuple(rgb or (0, 0, 0))
    )
    return f"#{red:02x}{green:02x}{blue:02x}"


def blend_hex_colors(color_a: str, color_b: str, ratio: float) -> str:
    mix = max(0.0, min(1.0, float(ratio)))
    a_red, a_green, a_blue = hex_to_rgb(color_a)
    b_red, b_green, b_blue = hex_to_rgb(color_b)
    return rgb_to_hex(
        (
            a_red + ((b_red - a_red) * mix),
            a_green + ((b_green - a_green) * mix),
            a_blue + ((b_blue - a_blue) * mix),
        )
    )


def ideal_text_color(bg_color: str) -> str:
    red, green, blue = hex_to_rgb(bg_color)
    luminance = ((red * 299) + (green * 587) + (blue * 114)) / 1000
    return "#111111" if luminance >= 145 else "#ffffff"


def normalize_lynis_output(text: str) -> str:
    text = strip_ansi_codes(text)
    lines = []
    for line in text.splitlines():
        line = line.rstrip()
        if line:
            lines.append(line)
    return "\n".join(lines)


