def _desktop_bool(value):
    return (value or "").strip().lower() in ("1", "true", "yes")


def run_headless_snapshot():
    """Print a compact status snapshot without starting Tk."""
    print("NetMon Headless Snapshot")
    print("=" * 24)

    rc, out = run_cmd(["ip", "-4", "route", "show", "default"], timeout=5)
    default_route = out.splitlines()[0] if rc == 0 and out else "n/a"
    print(f"Default route: {default_route}")

    if has_cmd("wg"):
        rc, out = run_cmd(["wg", "show", "interfaces"], timeout=5)
        wg_ifaces = out.strip() if rc == 0 and out.strip() else "none"
        print(f"WireGuard ifaces: {wg_ifaces}")
    else:
        print("WireGuard ifaces: wg not installed")

    if has_cmd("ufw"):
        rc, out = run_cmd(["ufw", "status"], timeout=8)
        first_line = out.splitlines()[0] if out else "n/a"
        print(f"UFW: {first_line} (rc={rc})")
    else:
        print("UFW: not installed")

    rc, out = run_cmd(["curl", "-s", "--max-time", "3", "ifconfig.me"], timeout=5)
    pub_ip = out.strip() if rc == 0 and out.strip() else "n/a"
    print(f"Public IP: {pub_ip}")


class GuidedTourManager:
    def __init__(self, app):
        self.app = app
        self.steps = []
        self.title = ""
        self.tour_id = ""
        self.index = -1
        self.popup = None
        self.marker = []
        self.progress_var = tk.StringVar(value="")
        self.title_var = tk.StringVar(value="")
        self.body_var = tk.StringVar(value="")
        self.hint_var = tk.StringVar(value="")
        self.action_feedback_var = tk.StringVar(value="")
        self._render_after_id = None
        self._action_feedback_after_id = None
        self._step_retry_count = 0
        try:
            self.app.bind("<Configure>", self._on_app_configure, add="+")
        except Exception:
            pass

    def tr(self, key: str, default: str | None = None) -> str:
        return self.app.tr(key, default)

    def is_active(self):
        return bool(self.steps)

    def start(self, steps, *, title="NetMon Tour", tour_id=""):
        self.stop(log_message=False)
        self.steps = list(steps or [])
        self.title = str(title or "NetMon Tour").strip() or "NetMon Tour"
        self.tour_id = str(tour_id or "").strip().lower()
        if not self.steps:
            return False
        self.index = 0
        self._step_retry_count = 0
        self._ensure_popup()
        self._schedule_render()
        return True

    def stop(self, log_message=False):
        self.steps = []
        self.index = -1
        self.tour_id = ""
        self._step_retry_count = 0
        after_id = self._render_after_id
        self._render_after_id = None
        feedback_after_id = self._action_feedback_after_id
        self._action_feedback_after_id = None
        if after_id:
            try:
                self.app.after_cancel(after_id)
            except Exception:
                pass
        if feedback_after_id:
            try:
                self.app.after_cancel(feedback_after_id)
            except Exception:
                pass
        self.action_feedback_var.set("")
        self._destroy_marker()
        if self.popup is not None:
            try:
                self.popup.destroy()
            except Exception:
                pass
            self.popup = None
        if log_message:
            try:
                self.app.log_safe(
                    self.tr("guided_tour_log_stopped", "Geführte Tour beendet.")
                )
            except Exception:
                pass

    def previous_step(self):
        if not self.is_active() or self.index <= 0:
            return
        self.index -= 1
        self._step_retry_count = 0
        self._schedule_render()

    def next_step(self):
        if not self.is_active():
            return
        if self.index >= len(self.steps) - 1:
            try:
                callback = getattr(self.app, "on_guided_tour_completed", None)
                if callable(callback):
                    callback(self.tour_id)
            except Exception:
                pass
            self.stop(log_message=True)
            return
        self.index += 1
        self._step_retry_count = 0
        self._schedule_render()

    def run_step_action(self):
        if not self.is_active() or self.index < 0 or self.index >= len(self.steps):
            return False
        step = self.steps[self.index]
        action = step.get("action")
        if not callable(action):
            return False
        try:
            result = action()
            if result is False:
                self._set_action_feedback(
                    self._resolve_text(step.get("action_failure"))
                    or self.tr(
                        "guided_tour_action_not_completed",
                        "Aktion konnte nicht abgeschlossen werden.",
                    )
                )
                return False
            self._set_action_feedback(
                self._resolve_text(step.get("action_success"))
                or self.tr(
                    "guided_tour_action_triggered",
                    "Aktion wurde ausgelöst.",
                )
            )
            return True
        except Exception as exc:
            fallback = self._resolve_text(step.get("action_failure"))
            self._set_action_feedback(
                fallback
                or self.tr(
                    "guided_tour_action_failed",
                    "Aktion fehlgeschlagen: {error}",
                ).format(error=exc)
            )
            return False

    def _ensure_popup(self):
        if self.popup is not None:
            return
        theme = self._theme()
        popup = tk.Toplevel(self.app)
        popup.title(self.title or self.tr("guided_tour_title_default", "NetMon Tour"))
        popup.transient(self.app)
        popup.resizable(False, False)
        popup.configure(bg=theme["panel_bg"])
        try:
            popup.attributes("-topmost", True)
        except Exception:
            pass
        popup.protocol("WM_DELETE_WINDOW", lambda: self.stop(log_message=True))
        for sequence, handler in (
            ("<Escape>", lambda _e: self.stop(log_message=True)),
            ("<Left>", lambda _e: self.previous_step()),
            ("<Right>", lambda _e: self.next_step()),
            ("<Return>", lambda _e: self.next_step()),
            ("<space>", lambda _e: self.next_step()),
            ("<a>", lambda _e: self.run_step_action()),
        ):
            try:
                popup.bind(sequence, handler, add="+")
            except Exception:
                pass

        shell = tk.Frame(
            popup,
            bg=theme["panel_bg"],
            highlightthickness=1,
            highlightbackground=theme["border"],
            padx=12,
            pady=10,
        )
        shell.pack(fill="both", expand=True)

        tk.Label(
            shell,
            textvariable=self.progress_var,
            bg=theme["panel_bg"],
            fg=theme["muted_fg"],
            anchor="w",
            font=("TkDefaultFont", 9, "bold"),
        ).pack(fill="x")
        tk.Label(
            shell,
            textvariable=self.title_var,
            bg=theme["panel_bg"],
            fg=theme["fg"],
            anchor="w",
            justify="left",
            wraplength=360,
            font=("TkDefaultFont", 11, "bold"),
            pady=6,
        ).pack(fill="x")
        tk.Label(
            shell,
            textvariable=self.body_var,
            bg=theme["panel_bg"],
            fg=theme["fg"],
            anchor="w",
            justify="left",
            wraplength=360,
        ).pack(fill="x")
        tk.Label(
            shell,
            textvariable=self.hint_var,
            bg=theme["panel_bg"],
            fg=theme["muted_fg"],
            anchor="w",
            justify="left",
            wraplength=360,
            font=("TkDefaultFont", 8),
            pady=8,
        ).pack(fill="x")
        tk.Label(
            shell,
            textvariable=self.action_feedback_var,
            bg=theme["panel_bg"],
            fg=theme["accent"],
            anchor="w",
            justify="left",
            wraplength=360,
            font=("TkDefaultFont", 8, "bold"),
            pady=0,
        ).pack(fill="x", pady=4)

        buttons = tk.Frame(shell, bg=theme["panel_bg"])
        buttons.pack(fill="x", pady=(12, 0))
        self._tour_prev_button = ttk.Button(
            buttons,
            text=self.tr("guided_tour_btn_back", "Zurück"),
            command=self.previous_step,
        )
        self._tour_prev_button.pack(side="left")
        self._tour_action_button = ttk.Button(
            buttons,
            text=self.tr("guided_tour_btn_action", "Aktion"),
            command=self.run_step_action,
        )
        self._tour_action_button.pack(side="left", padx=(8, 0))
        self._tour_next_button = ttk.Button(
            buttons,
            text=self.tr("guided_tour_btn_next", "Weiter"),
            command=self.next_step,
        )
        self._tour_next_button.pack(side="right")
        ttk.Button(
            buttons,
            text=self.tr("btn_finish", "Beenden"),
            command=lambda: self.stop(log_message=True),
        ).pack(side="right", padx=(0, 8))
        self.popup = popup
        try:
            self._tour_next_button.focus_set()
        except Exception:
            pass

    def _schedule_render(self, delay_ms=90):
        after_id = self._render_after_id
        self._render_after_id = None
        if after_id:
            try:
                self.app.after_cancel(after_id)
            except Exception:
                pass
        self._render_after_id = self.app.after(
            max(30, int(delay_ms or 90)),
            self._render_current_step,
        )

    def _render_current_step(self):
        self._render_after_id = None
        if not self.is_active():
            return
        step = self.steps[self.index]
        prepare = step.get("prepare")
        if callable(prepare):
            try:
                prepare()
            except Exception:
                pass
        try:
            self.app.update_idletasks()
        except Exception:
            pass
        widget = self._resolve_target(step)
        target_missing = step.get("target") is not None and not self._target_ready(
            widget
        )
        if target_missing and self._step_retry_count < 8:
            self._ensure_popup()
            self._update_popup_content(step, waiting_for_target=True)
            self._position_windows(step, widget=None)
            self._step_retry_count += 1
            self._schedule_render(delay_ms=140)
            return
        self._ensure_popup()
        self._update_popup_content(step, target_missing=target_missing)
        self._position_windows(step, widget=widget)
        self._step_retry_count = 0

    def _update_popup_content(
        self, step, *, waiting_for_target=False, target_missing=False
    ):
        total = len(self.steps)
        current = self.index + 1
        self.progress_var.set(f"{self.title}  |  Schritt {current} von {total}")
        self.title_var.set(self._resolve_text(step.get("title")))
        self.body_var.set(self._resolve_text(step.get("body")))
        self.action_feedback_var.set("")
        self.hint_var.set(
            self._build_step_hint(
                step,
                waiting_for_target=waiting_for_target,
                target_missing=target_missing,
            )
        )
        if hasattr(self, "_tour_prev_button"):
            try:
                self._tour_prev_button.configure(
                    state=("disabled" if self.index <= 0 else "normal")
                )
            except Exception:
                pass
        if hasattr(self, "_tour_next_button"):
            try:
                self._tour_next_button.configure(
                    text=(
                        self.tr("guided_tour_btn_finish", "Abschließen")
                        if self.index >= total - 1
                        else self.tr("guided_tour_btn_next", "Weiter")
                    )
                )
            except Exception:
                pass
        if hasattr(self, "_tour_action_button"):
            action_label = self._resolve_text(step.get("action_label"))
            has_action = callable(step.get("action")) and bool(action_label)
            try:
                self._tour_action_button.configure(
                    text=(action_label or self.tr("guided_tour_btn_action", "Aktion")),
                    state=("normal" if has_action else "disabled"),
                )
            except Exception:
                pass

    def _build_step_hint(self, step, *, waiting_for_target=False, target_missing=False):
        step_hint = self._resolve_text(step.get("hint"))
        nav_hint = self.tr(
            "guided_tour_nav_hint",
            "Tastatur: Links/Rechts oder Enter/Leertaste. Esc beendet die Tour.",
        )
        if callable(step.get("action")) and self._resolve_text(
            step.get("action_label")
        ):
            nav_hint = self.tr(
                "guided_tour_nav_hint_with_action",
                "{base} A startet die Aktionsschaltfläche.",
            ).format(base=nav_hint)
        if waiting_for_target:
            if step_hint:
                return self.tr(
                    "guided_tour_hint_preparing_with_step",
                    "Bereich wird vorbereitet. {step_hint} {nav_hint}",
                ).format(step_hint=step_hint, nav_hint=nav_hint)
            return self.tr(
                "guided_tour_hint_preparing",
                "Bereich wird vorbereitet. {nav_hint}",
            ).format(nav_hint=nav_hint)
        if target_missing:
            if step_hint:
                return self.tr(
                    "guided_tour_hint_target_missing_with_step",
                    "Hinweis: Dieser Bereich ist gerade nicht sichtbar. {step_hint} {nav_hint}",
                ).format(step_hint=step_hint, nav_hint=nav_hint)
            return self.tr(
                "guided_tour_hint_target_missing",
                "Hinweis: Dieser Bereich ist gerade nicht sichtbar. {nav_hint}",
            ).format(nav_hint=nav_hint)
        if step_hint:
            return f"{step_hint} {nav_hint}"
        return nav_hint

    def _resolve_text(self, value):
        if callable(value):
            try:
                value = value()
            except Exception:
                value = ""
        return str(value or "").strip()

    def _set_action_feedback(self, message, *, duration_ms=4200):
        after_id = self._action_feedback_after_id
        self._action_feedback_after_id = None
        if after_id:
            try:
                self.app.after_cancel(after_id)
            except Exception:
                pass
        text = str(message or "").strip()
        self.action_feedback_var.set(text)
        if not text:
            return
        self._action_feedback_after_id = self.app.after(
            max(800, int(duration_ms or 4200)),
            self._clear_action_feedback,
        )

    def _clear_action_feedback(self):
        self._action_feedback_after_id = None
        try:
            self.action_feedback_var.set("")
        except Exception:
            pass

    def _position_windows(self, step, *, widget=None):
        if widget is None:
            widget = self._resolve_target(step)
        coords = self._widget_geometry(widget)
        self._position_marker(coords)
        self._position_popup(coords)

    def _resolve_target(self, step):
        target = step.get("target")
        if callable(target):
            try:
                return target()
            except Exception:
                return None
        if isinstance(target, str):
            return getattr(self.app, target, None)
        return None

    def _widget_geometry(self, widget):
        if widget is None:
            return None
        try:
            if not bool(widget.winfo_exists()):
                return None
            x = int(widget.winfo_rootx() or 0)
            y = int(widget.winfo_rooty() or 0)
            width = max(1, int(widget.winfo_width() or widget.winfo_reqwidth() or 1))
            height = max(
                1,
                int(widget.winfo_height() or widget.winfo_reqheight() or 1),
            )
            return (x, y, width, height)
        except Exception:
            return None

    def _target_ready(self, widget):
        if widget is None:
            return False
        try:
            if not bool(widget.winfo_exists()):
                return False
            if not bool(widget.winfo_ismapped()):
                return False
            width = int(widget.winfo_width() or widget.winfo_reqwidth() or 0)
            height = int(widget.winfo_height() or widget.winfo_reqheight() or 0)
            root_x = int(widget.winfo_rootx() or 0)
            root_y = int(widget.winfo_rooty() or 0)
            return width > 1 and height > 1 and root_x >= 0 and root_y >= 0
        except Exception:
            return False

    def _position_marker(self, coords):
        if coords is None:
            self._destroy_marker()
            return
        theme = self._theme()
        if not self.marker:
            self.marker = self._create_marker_segments(theme["accent"])
        x, y, width, height = coords
        pad = 7
        thickness = 4
        left = max(0, x - pad)
        top = max(0, y - pad)
        outer_width = width + pad * 2
        outer_height = height + pad * 2
        segments = [
            (left, top, outer_width, thickness),
            (left, top + outer_height - thickness, outer_width, thickness),
            (left, top, thickness, outer_height),
            (left + outer_width - thickness, top, thickness, outer_height),
        ]
        try:
            for marker, (seg_x, seg_y, seg_w, seg_h) in zip(self.marker, segments):
                marker.configure(bg=theme["accent"])
                marker.geometry(f"{seg_w}x{seg_h}+{seg_x}+{seg_y}")
                marker.deiconify()
                marker.lift()
        except Exception:
            pass

    def _create_marker_segments(self, color):
        segments = []
        for _ in range(4):
            marker = tk.Toplevel(self.app)
            marker.overrideredirect(True)
            marker.configure(bg=color)
            try:
                marker.attributes("-topmost", True)
            except Exception:
                pass
            segments.append(marker)
        return segments

    def _destroy_marker(self):
        markers = self.marker if isinstance(self.marker, list) else [self.marker]
        for marker in markers:
            if marker is None:
                continue
            try:
                marker.destroy()
            except Exception:
                pass
        self.marker = []

    def _position_popup(self, coords):
        if self.popup is None:
            return
        try:
            self.popup.update_idletasks()
        except Exception:
            pass
        popup_width = max(320, int(self.popup.winfo_reqwidth() or 320))
        popup_height = max(180, int(self.popup.winfo_reqheight() or 180))
        screen_width = max(int(self.app.winfo_screenwidth() or 1280), 1280)
        screen_height = max(int(self.app.winfo_screenheight() or 900), 900)
        if coords is None:
            x = max((screen_width - popup_width) // 2, 20)
            y = max((screen_height - popup_height) // 2, 20)
        else:
            target_x, target_y, target_width, _target_height = coords
            x = target_x + target_width + 18
            y = target_y
            if x + popup_width > screen_width - 20:
                x = max(target_x - popup_width - 18, 20)
            if y + popup_height > screen_height - 20:
                y = max(screen_height - popup_height - 20, 20)
        try:
            self.popup.geometry(f"{popup_width}x{popup_height}+{x}+{y}")
            self.popup.deiconify()
            self.popup.lift()
        except Exception:
            pass

    def _theme(self):
        get_theme = getattr(self.app, "_get_theme", None)
        theme_name = str(getattr(self.app, "_preferred_theme_name", "light") or "light")
        if callable(get_theme):
            try:
                return get_theme(theme_name)
            except Exception:
                pass
        return LIGHT_THEME

    def _on_app_configure(self, _event=None):
        if not self.is_active():
            return
        try:
            self._position_windows(self.steps[self.index])
        except Exception:
            pass


class App(TkBase):
    DONATION_POPUP_STARTUP_DELAY_MS = 60_000
    DONATION_POPUP_DISABLE_AFTER_SECONDS = 7 * 24 * 60 * 60

    def _apply_primary_monitor_start_geometry(self):
        bounds = _detect_primary_monitor_bounds()
        if bounds is not None:
            pos_x, pos_y, screen_width, screen_height = bounds
        else:
            pos_x = 0
            pos_y = 0
            screen_width = int(self.winfo_screenwidth() or 0)
            screen_height = int(self.winfo_screenheight() or 0)
        screen_width = max(screen_width, 900)
        screen_height = max(screen_height, 600)
        self.geometry(f"{screen_width}x{screen_height}+{pos_x}+{pos_y}")
        self.minsize(900, 600)
        self.maxsize(screen_width, screen_height)

