    # scroll helpers (Linux wheel)
    def _scroll_up(self, _e):
        self.page_canvas.yview_scroll(-1, "units")

    def _scroll_down(self, _e):
        self.page_canvas.yview_scroll(1, "units")

    def attach_local_mousewheel_binding(self, widget_name: str):
        widget = self.__dict__.get(widget_name)
        if widget is None:
            return

        focus_required = True
        attached = self.__dict__.setdefault("_local_mousewheel_bound_widgets", set())
        widget_id = str(widget)
        if widget_id in attached:
            return
        attached.add(widget_id)

        def _widget_has_focus() -> bool:
            try:
                return self.focus_get() == widget
            except Exception:
                return False

        def _scroll_page_units(step: int):
            try:
                self.page_canvas.yview_scroll(step, "units")
            except Exception:
                return None
            return "break"

        def _scroll_widget_units(step: int):
            try:
                widget.yview_scroll(step, "units")
            except Exception:
                return None
            return "break"

        def _scroll_widget_x_units(step: int):
            try:
                widget.xview_scroll(step, "units")
            except Exception:
                return None
            return "break"

        def _on_mousewheel(event):
            delta = int(getattr(event, "delta", 0) or 0)
            if delta == 0:
                return None
            step = -1 if delta > 0 else 1
            if focus_required and not _widget_has_focus():
                return _scroll_page_units(step)
            return _scroll_widget_units(step)

        def _on_wheel_up(_event):
            if focus_required and not _widget_has_focus():
                return _scroll_page_units(-1)
            return _scroll_widget_units(-1)

        def _on_wheel_down(_event):
            if focus_required and not _widget_has_focus():
                return _scroll_page_units(1)
            return _scroll_widget_units(1)

        def _on_shift_mousewheel(event):
            delta = int(getattr(event, "delta", 0) or 0)
            if delta == 0:
                return None
            step = -1 if delta > 0 else 1
            return _scroll_widget_x_units(step)

        def _on_shift_wheel_up(_event):
            return _scroll_widget_x_units(-1)

        def _on_shift_wheel_down(_event):
            return _scroll_widget_x_units(1)

        def _focus_widget(_event):
            try:
                widget.focus_force()
            except Exception:
                pass

        widget.bind("<Button-1>", _focus_widget, add="+")
        widget.bind("<MouseWheel>", _on_mousewheel, add="+")
        widget.bind("<Button-4>", _on_wheel_up, add="+")
        widget.bind("<Button-5>", _on_wheel_down, add="+")
        widget.bind("<Shift-MouseWheel>", _on_shift_mousewheel, add="+")
        widget.bind("<Shift-Button-4>", _on_shift_wheel_up, add="+")
        widget.bind("<Shift-Button-5>", _on_shift_wheel_down, add="+")

