    def on_close(self):
        if bool(self.__dict__.get("_netmon_closing", False)):
            try:
                self.destroy()
            except Exception:
                pass
            return
        self._netmon_closing = True
        try:
            guided_tour = self.__dict__.get("guided_tour")
            if guided_tour is not None:
                guided_tour.stop(log_message=False)
        except Exception:
            pass
        try:
            self.withdraw()
            self.update_idletasks()
        except Exception:
            pass

        def _finish_close():
            try:
                self.system_monitor_active = False
                self.process_guard_monitoring = False
                detached_radio = False
                standalone_transition = False
                if netmon_radio_core is not None:
                    try:
                        detached_radio = bool(netmon_radio_core.radio_is_detached())
                    except Exception:
                        detached_radio = False
                    try:
                        standalone_transition = bool(
                            netmon_radio_core.radio_transition_in_progress("standalone")
                        )
                    except Exception:
                        standalone_transition = False
                panel = self.__dict__.get("radio_embedded_panel")
                if panel is not None and not (detached_radio or standalone_transition):
                    try:
                        panel.close_projectm_visualizer_test()
                    except Exception:
                        pass
                    try:
                        panel.stop_radio_playback(async_mode=False)
                    except Exception:
                        pass
                if netmon_radio_core is not None:
                    try:
                        netmon_radio_core.clear_netmon_host_state(os.getpid())
                    except Exception:
                        pass
                clock_after_id = self.__dict__.get("_clock_after_id")
                if clock_after_id:
                    try:
                        self.after_cancel(clock_after_id)
                    except Exception:
                        pass
                    self._clock_after_id = None
                if not (detached_radio or standalone_transition):
                    try:
                        self.stop_radio()
                    except Exception:
                        pass
                try:
                    self.stop_running_fun_game()
                except Exception:
                    pass
            finally:
                try:
                    self.destroy()
                except Exception:
                    pass

        try:
            self.after(10, _finish_close)
        except Exception:
            _finish_close()

    def report_callback_exception(self, exc, val, tb):
        diagnostic_path = _append_crash_dump(
            "tk.report_callback_exception",
            exc,
            val,
            tb,
            context={
                "area": "gui-callback",
                "ui_state": self._diagnostic_ui_state(),
            },
        )
        self._remember_diagnostic_report_path(diagnostic_path)
        try:
            message = f"Unerwarteter GUI-Fehler. Crash-Dump: {CRASH_LOG_PATH}"
            if diagnostic_path:
                message += f" | Diagnose: {diagnostic_path}"
            self.log(message)
            if diagnostic_path:
                self._append_diagnostic_log_links()
        except Exception:
            pass
        try:
            traceback.print_exception(exc, val, tb, file=sys.stderr)
        except Exception:
            pass

    def _remember_diagnostic_report_path(self, path):
        normalized = os.path.abspath(os.path.expanduser(str(path or "").strip()))
        if normalized and os.path.isfile(normalized):
            self._latest_diagnostic_report_path = normalized
            return normalized
        return ""

    def _get_latest_diagnostic_report_path(self):
        remembered = str(
            getattr(self, "_latest_diagnostic_report_path", "") or ""
        ).strip()
        if remembered and os.path.isfile(remembered):
            return remembered
        latest = str(latest_diagnostic_report_path() or "").strip()
        return self._remember_diagnostic_report_path(latest)

    def _open_path_with_xdg_open(self, path, *, label="Datei"):
        target = os.path.abspath(os.path.expanduser(str(path or "").strip()))
        if not target:
            return False
        if not shutil.which("xdg-open"):
            self.log_safe(f"{label} öffnen nicht verfügbar: xdg-open fehlt.")
            return False
        try:
            subprocess.Popen(
                ["xdg-open", target],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            return True
        except Exception as exc:
            self.log_safe(f"{label} konnte nicht geöffnet werden: {exc}")
            return False

    def _open_latest_diagnostic_report(self):
        path = self._get_latest_diagnostic_report_path()
        if not path:
            self.log_safe("Kein Diagnosebericht gefunden.")
            return False
        return self._open_path_with_xdg_open(path, label="Diagnosebericht")

    def open_netmon_roots_homepage(self, _event=None):
        target = str(getattr(self, "netmon_roots_homepage", "") or "").strip()
        return self._open_url_with_xdg_open(target, label="NetMonRoots")

    def _open_url_with_xdg_open(self, target, label="URL"):
        target = str(target or "").strip()
        if not target:
            return False
        # Wie fetch_url()/_station_logo_url(): xdg-open reicht file:// und
        # beliebige Custom-Scheme-Handler an den Desktop weiter. Ziel-URLs
        # (u. a. die aus einer Remote-Versionsdatei stammende Update-URL)
        # daher auf http/https begrenzen, bevor sie den Handler erreichen.
        if urlparse(target).scheme.lower() not in ("http", "https"):
            self.log_safe(
                f"{label} nicht geöffnet: unzulässiges URL-Schema in {target}"
            )
            return False
        if not shutil.which("xdg-open"):
            self.log_safe(f"{label} öffnen nicht verfügbar: xdg-open fehlt.")
            return False
        try:
            subprocess.Popen(
                ["xdg-open", target],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            self.log_safe(f"{label} geöffnet: {target}")
            return True
        except Exception as exc:
            self.log_safe(f"{label} konnte nicht geöffnet werden: {exc}")
            return False

    def _normalize_version_tuple(self, value):
        parts = re.findall(r"\d+", str(value or ""))
        return tuple(int(part) for part in parts)

    def _compare_version_strings(self, left, right):
        left_parts = list(self._normalize_version_tuple(left))
        right_parts = list(self._normalize_version_tuple(right))
        if not left_parts and not right_parts:
            return 0
        length = max(len(left_parts), len(right_parts))
        left_parts.extend([0] * (length - len(left_parts)))
        right_parts.extend([0] * (length - len(right_parts)))
        if left_parts < right_parts:
            return -1
        if left_parts > right_parts:
            return 1
        return 0

    def _fetch_latest_release_info(self):
        url = str(getattr(self, "netmon_roots_latest_version_url", "") or "").strip()
        if not url:
            raise ValueError("Keine Versionsquelle konfiguriert.")
        with urllib_request.urlopen(url, timeout=8) as response:
            payload = response.read().decode("utf-8", errors="replace")
        data = json.loads(payload)
        if not isinstance(data, dict):
            raise ValueError("Versionsdatei ist kein JSON-Objekt.")
        version = str(data.get("version", "") or "").strip()
        if not version:
            raise ValueError("Versionsdatei enthält keine Version.")
        fallback_url = str(
            getattr(self, "netmon_roots_downloads_url", "")
            or getattr(self, "netmon_roots_homepage", "")
        ).strip()
        download_url = str(
            data.get("download_url") or data.get("downloads_url") or ""
        ).strip()
        # Die Update-URL stammt aus einer Remote-Versionsdatei. Nur eine
        # http/https-URL auf die netmonroots.com-Domain automatisch oeffnen;
        # andernfalls auf die fest konfigurierte Download-Seite zurueckfallen,
        # damit ein kompromittiertes CDN nicht off-site umleiten kann.
        if not self._is_trusted_update_url(download_url):
            download_url = fallback_url
        return {
            "version": version,
            "download_url": download_url,
        }

    @staticmethod
    def _is_trusted_update_url(url):
        parsed = urlparse(str(url or "").strip())
        if parsed.scheme.lower() not in ("http", "https"):
            return False
        host = (parsed.hostname or "").lower()
        return host == "netmonroots.com" or host.endswith(".netmonroots.com")

    def _set_about_version_status(self, text):
        var = getattr(self, "about_version_status_var", None)
        if var is not None:
            try:
                var.set(str(text or "").strip())
                return
            except Exception:
                pass
        self.log_safe(str(text or "").strip())

    def check_about_latest_version(self, auto_open=True, manual=False):
        current_version = str(NETMON_APP_VERSION or "").strip()
        self._set_about_version_status(
            self.tr(
                "about_update_status_checking",
                "Versionsprüfung läuft ...",
            )
        )

        def worker():
            try:
                info = self._fetch_latest_release_info()
                latest_version = str(info.get("version", "") or "").strip()
                download_url = str(info.get("download_url", "") or "").strip()
                cmp_result = self._compare_version_strings(
                    current_version, latest_version
                )
                if cmp_result < 0:
                    status_text = self.tr(
                        "about_update_status_newer",
                        "Neue Version gefunden: {latest} (installiert: {current}).",
                    ).format(latest=latest_version, current=current_version)

                    def handle_newer():
                        self._set_about_version_status(status_text)
                        if auto_open and not self._about_update_redirect_done:
                            self._about_update_redirect_done = True
                            self._open_url_with_xdg_open(
                                download_url
                                or getattr(self, "netmon_roots_downloads_url", ""),
                                label="NetMon Update-Seite",
                            )

                    self.after(0, handle_newer)
                    return

                if cmp_result == 0:
                    status_text = self.tr(
                        "about_update_status_current",
                        "NetMon ist aktuell. Installiert und online: {version}.",
                    ).format(version=current_version)
                else:
                    status_text = self.tr(
                        "about_update_status_local_newer",
                        "Lokale Version ist neuer als der Website-Hinweis ({current} > {latest}).",
                    ).format(current=current_version, latest=latest_version)

                self.after(0, lambda: self._set_about_version_status(status_text))
            except Exception as exc:
                status_text = self.tr(
                    "about_update_status_unavailable",
                    "Versionsprüfung momentan nicht verfügbar.",
                )
                self.after(0, lambda: self._set_about_version_status(status_text))
                if manual:
                    self.log_safe(f"Versionsprüfung fehlgeschlagen: {exc}")

        threading.Thread(target=worker, daemon=True).start()

