    def _remember_support_package_path(self, path):
        normalized = os.path.abspath(os.path.expanduser(str(path or "").strip()))
        if normalized and os.path.isfile(normalized):
            self._latest_support_package_path = normalized
            return normalized
        return ""

    def _get_latest_support_package_path(self):
        remembered = str(
            getattr(self, "_latest_support_package_path", "") or ""
        ).strip()
        if remembered and os.path.isfile(remembered):
            return remembered
        try:
            candidates = []
            for name in os.listdir(support_packages_dir()):
                if not name.startswith("netmon-support-") or not name.endswith(".zip"):
                    continue
                path = os.path.join(support_packages_dir(), name)
                if os.path.isfile(path):
                    candidates.append(path)
            if not candidates:
                return ""
            candidates.sort(key=lambda path: os.path.getmtime(path), reverse=True)
            return self._remember_support_package_path(candidates[0])
        except Exception:
            return ""

    def _support_form_placeholders(self):
        tr = getattr(self, "tr", None)
        if not callable(tr):

            def tr(_key, fallback=None):
                return fallback

        return {
            "contact_name": tr(
                "support_placeholder_contact_name",
                "Platzhalter: Name oder Kürzel (optional)",
            ),
            "contact_email": tr(
                "support_placeholder_contact_email",
                "Platzhalter: E-Mail-Adresse (optional)",
            ),
            "last_step": tr(
                "support_placeholder_last_step",
                "Platzhalter: letzter Schritt vor dem Fehler",
            ),
            "repro": tr(
                "support_placeholder_repro",
                "Platzhalter: z. B. immer / manchmal / noch unklar",
            ),
            "details": tr(
                "support_placeholder_details",
                "Platzhalter: kurze Fehlerbeschreibung, Beobachtungen, gewünschtes Verhalten",
            ),
        }

    def _support_form_clean_value(self, value, placeholder=""):
        text = str(value or "").strip()
        marker = str(placeholder or "").strip()
        if not text or text == marker:
            return ""
        return text

    def _build_about_support_form_metadata(
        self,
        *,
        contact_name="",
        contact_email="",
        last_step="",
        repro_status="",
        details="",
    ):
        placeholders = self._support_form_placeholders()
        return {
            "user_report": {
                "contact_name": self._support_form_clean_value(
                    contact_name,
                    placeholders["contact_name"],
                ),
                "contact_email": self._support_form_clean_value(
                    contact_email,
                    placeholders["contact_email"],
                ),
                "last_step": self._support_form_clean_value(
                    last_step,
                    placeholders["last_step"],
                ),
                "repro_status": self._support_form_clean_value(
                    repro_status,
                    placeholders["repro"],
                ),
                "details": self._support_form_clean_value(
                    details,
                    placeholders["details"],
                ),
            }
        }

    def create_support_package(self, extra_metadata=None):
        metadata = {
            "last_action": self._diagnostic_last_action_context(),
            "runtime_state": self._diagnostic_runtime_state(),
        }
        if isinstance(extra_metadata, dict):
            metadata.update(extra_metadata)
        try:
            path = create_support_package(metadata=metadata)
        except Exception as exc:
            self.log_safe(f"Support package could not be created: {exc}")
            return ""
        remembered = self._remember_support_package_path(path)
        if remembered:
            self.log_safe(f"Support package created: {remembered}")
        return remembered

