    def _register_guided_tour_launcher_button(
        self,
        tour_name,
        button,
        base_label,
        *,
        title_widget=None,
        status_widget=None,
    ):
        if button is None:
            return
        mapping = self.__dict__.setdefault("guided_tour_launcher_buttons", {})
        items = mapping.setdefault(str(tour_name or "").strip().lower(), [])
        items.append(
            {
                "button": button,
                "base_label": str(base_label or "").strip(),
                "title_widget": title_widget,
                "status_widget": status_widget,
            }
        )

    def refresh_guided_tour_buttons(self):
        button_specs = (
            (
                "about_btn_full_tour",
                "full-tour",
                self.tr("tour_label_full", "Volle Tour"),
            ),
            (
                "about_btn_quickstart_tour",
                "quickstart",
                self.tr("tour_about_quickstart", "Schnellstart-Tour"),
            ),
            ("about_btn_dns_tour", "dns", self.tr("tour_about_dns", "DNS-Tour")),
            (
                "about_btn_security_tour",
                "security",
                self.tr("tour_about_security", "Security-Tour"),
            ),
            (
                "about_btn_download_scan_tour",
                "download-scan",
                self.tr("tour_about_download_scan", "D-Scan-Tour"),
            ),
            (
                "about_btn_radio_tour",
                "radio",
                self.tr("tour_about_radio", "Radio-Tour"),
            ),
        )
        for attr_name, tour_name, base_label in button_specs:
            button = self.__dict__.get(attr_name)
            if button is None:
                continue
            try:
                button.configure(
                    text=self._guided_tour_button_text(tour_name, base_label)
                )
            except Exception:
                pass
        launcher_buttons = self.__dict__.get("guided_tour_launcher_buttons", {})
        for tour_name, entries in launcher_buttons.items():
            for entry in entries:
                button = entry.get("button")
                base_label = entry.get("base_label", "")
                title_widget = entry.get("title_widget")
                status_widget = entry.get("status_widget")
                try:
                    button.configure(
                        text=self._guided_tour_button_text(tour_name, base_label)
                    )
                except Exception:
                    pass
                if title_widget is not None:
                    try:
                        title_widget.configure(
                            text=self._guided_tour_title_text(tour_name, base_label)
                        )
                    except Exception:
                        pass
                if status_widget is not None:
                    try:
                        status_widget.configure(
                            text=self._guided_tour_status_symbol(tour_name)
                        )
                    except Exception:
                        pass

    def refresh_guided_tour_status(self):
        status_var = self.__dict__.get("guided_tour_status_var")
        if status_var is None:
            self.refresh_guided_tour_buttons()
            return
        try:
            status_var.set(self._guided_tour_status_text())
        except Exception:
            pass
        self.refresh_guided_tour_buttons()

    def on_guided_tour_completed(self, tour_name):
        tour_id = str(tour_name or "").strip().lower()
        if not tour_id:
            return
        completed = self._guided_tour_completed_settings()
        if completed.get(tour_id):
            return
        completed[tour_id] = True
        self.settings["guided_tour_completed"] = completed
        self.save_settings(log_success=False)
        self.refresh_guided_tour_status()
        try:
            self.after(80, self.return_to_guided_tour_tab)
        except Exception:
            pass
        try:
            self.log_safe(f"Geführte Tour abgeschlossen: {tour_id}")
        except Exception:
            pass

    def return_to_guided_tour_tab(self):
        try:
            self.nb.select(self.tab_settings)
        except Exception:
            pass
        settings_nb = self.__dict__.get("settings_nb")
        settings_tours_tab = self.__dict__.get("settings_tours_tab")
        if settings_nb is None or settings_tours_tab is None:
            return
        try:
            settings_nb.select(settings_tours_tab)
        except Exception:
            pass

    def reset_guided_tour_progress(self):
        self.settings["guided_tour_completed"] = {}
        try:
            self._quickstart_tour_offer_done = False
        except Exception:
            pass
        self.save_settings(log_success=False)
        self.refresh_guided_tour_status()
        try:
            self.log_safe(
                "Tour-Fortschritt zurückgesetzt. Schnellstart kann wieder angeboten werden."
            )
        except Exception:
            pass

