    def _guided_tour_security_tools_hint(self):
        parts = []
        parts.append(
            self.tr("tour_security_tool_lynis_ready", "Lynis ready.")
            if has_cmd("lynis")
            else self.tr("tour_security_tool_lynis_missing", "Lynis missing.")
        )
        try:
            rkh_ready = bool(is_rkhunter_installed())
        except Exception:
            rkh_ready = bool(has_cmd("rkhunter"))
        parts.append(
            self.tr("tour_security_tool_rkhunter_ready", "rkhunter ready.")
            if rkh_ready
            else self.tr("tour_security_tool_rkhunter_missing", "rkhunter missing.")
        )
        parts.append(
            self.tr("tour_security_tool_clamav_ready", "ClamAV ready.")
            if self._download_scan_clamav_available()
            else self.tr("tour_security_tool_clamav_missing", "ClamAV missing.")
        )
        return " ".join(parts)

    def _guided_tour_packet_capture_hint(self):
        if self.wireshark_launch_blocked():
            return self.tr(
                "tour_packet_capture_hint_blocked",
                "Wireshark launch is currently blocked in NetMon. Captures are still possible, but opening them directly in Wireshark remains blocked.",
            )
        dep_status = self.get_dependency_status()
        if bool(dep_status.get("wireshark", False)):
            return self.tr(
                "tour_packet_capture_hint_available",
                "Wireshark is available. Captures can be handed off directly after recording.",
            )
        return self.tr(
            "tour_packet_capture_hint_missing",
            "Wireshark ist aktuell nicht verfügbar. Für Rohmitschnitte reichen die Capture-Funktionen, die GUI-Auswertung braucht aber Wireshark oder tshark.",
        )

    def _guided_tour_security_summary_hint(self):
        recommendations = []
        if not has_cmd("lynis"):
            recommendations.append(
                self.tr("tour_security_summary_add_lynis", "Lynis nachrüsten")
            )
        try:
            rkh_ready = bool(is_rkhunter_installed())
        except Exception:
            rkh_ready = bool(has_cmd("rkhunter"))
        if not rkh_ready:
            recommendations.append(
                self.tr("tour_security_summary_add_rkhunter", "rkhunter nachrüsten")
            )
        if not self._download_scan_clamav_available():
            recommendations.append(
                self.tr("tour_security_summary_add_clamav", "ClamAV nachrüsten")
            )
        if self.wireshark_launch_blocked():
            recommendations.append(
                self.tr(
                    "tour_security_summary_wireshark_blocked",
                    "Wireshark ist in NetMon bewusst gesperrt",
                )
            )
        if recommendations:
            return self.tr(
                "tour_security_summary_current_state",
                "Aktueller Zustand: {items}.",
            ).format(items=", ".join(recommendations))
        return self.tr(
            "tour_security_summary_ready_hint",
            "Vor echten Analysen lohnt sich ein Blick auf Status, Rechte und verfügbare Werkzeuge.",
        )

    def _guided_tour_security_setup_action_label(self):
        try:
            rkh_ready = bool(is_rkhunter_installed())
        except Exception:
            rkh_ready = bool(has_cmd("rkhunter"))
        missing_any = (
            not has_cmd("lynis")
            or not self._download_scan_clamav_available()
            or not rkh_ready
        )
        return (
            self.tr("tour_security_setup_action", "Open setup assistant")
            if missing_any
            else ""
        )

