    def _record_diagnostic_action(self, action, area="", *, details=None):
        self._diagnostic_last_action = str(action or "").strip()
        self._diagnostic_last_area = str(area or "").strip()
        self._diagnostic_last_action_at = datetime.now(timezone.utc).isoformat()
        self._diagnostic_last_details = dict(details or {})
        return App._diagnostic_last_action_context(self)

    def _diagnostic_last_action_context(self):
        return {
            "action": str(getattr(self, "_diagnostic_last_action", "") or ""),
            "area": str(getattr(self, "_diagnostic_last_area", "") or ""),
            "at": str(getattr(self, "_diagnostic_last_action_at", "") or ""),
            "details": dict(getattr(self, "_diagnostic_last_details", {}) or {}),
        }

    def _record_notebook_diagnostic_action(self, notebook, area):
        label = self._selected_notebook_tab_label(notebook)
        if not label:
            return None
        return self._record_diagnostic_action(
            f"Tab gewechselt: {label}",
            area,
            details={"selected_tab": label},
        )

    def _diagnostic_var_value(self, var_name):
        var = getattr(self, var_name, None)
        try:
            return str(var.get() or "")
        except Exception:
            return ""

    def _diagnostic_runtime_state(self):
        return {
            "public_ip": str(getattr(self, "public_ip", "") or ""),
            "country": str(getattr(self, "country", "") or ""),
            "radio_detached": bool(getattr(self, "radio_detached", False)),
            "dns_guard_state": str(getattr(self, "dns_guard_state", "") or ""),
            "dns_guard_status": App._diagnostic_var_value(self, "dns_guard_status_var"),
            "dns_consistency_ok": getattr(self, "last_dns_consistency_ok", None),
            "dot_enabled": bool(getattr(self, "dot_enabled", False)),
            "dot_running": bool(getattr(self, "dot_running", False)),
            "dot_status": App._diagnostic_var_value(self, "dot_status_var"),
            "vpn_status": App._diagnostic_var_value(self, "vpn_status_text_var"),
            "nm_dns_status": App._diagnostic_var_value(self, "nm_dns_header_var"),
            "ufw_logging_status": App._diagnostic_var_value(
                self, "ufw_logging_status_var"
            ),
            "security_filter_mode": str(
                getattr(self, "security_filter_mode", "") or ""
            ),
            "security_events_count": len(
                list(getattr(self, "security_events", []) or [])
            ),
            "security_visible_events_count": len(
                list(getattr(self, "security_visible_events", []) or [])
            ),
            "security_last_alarm": str(getattr(self, "security_last_alarm", "") or ""),
        }

    def _bind_diagnostic_notebook_tracking(self):
        bindings = (
            ("nb", "main-tabs"),
            ("system_nb", "system-tabs"),
            ("tools_nb", "tools-tabs"),
            ("security_nb", "security-tabs"),
        )
        for attr_name, area in bindings:
            notebook = getattr(self, attr_name, None)
            if notebook is None:
                continue
            try:
                notebook.bind(
                    "<<NotebookTabChanged>>",
                    lambda _event, nb=notebook, a=area: (
                        self._record_notebook_diagnostic_action(nb, a)
                    ),
                    add="+",
                )
            except Exception:
                continue
            self._record_notebook_diagnostic_action(notebook, area)

    def _selected_notebook_tab_label(self, notebook):
        if notebook is None:
            return ""
        try:
            tab_id = notebook.select()
            if not tab_id:
                return ""
            return str(notebook.tab(tab_id, "text") or "").strip()
        except Exception:
            return ""

    def _diagnostic_ui_state(self):
        return {
            "theme": str(getattr(self, "_preferred_theme_name", "") or ""),
            "main_tab": self._selected_notebook_tab_label(getattr(self, "nb", None)),
            "system_tab": self._selected_notebook_tab_label(
                getattr(self, "system_nb", None)
            ),
            "tools_tab": self._selected_notebook_tab_label(
                getattr(self, "tools_nb", None)
            ),
            "security_tab": self._selected_notebook_tab_label(
                getattr(self, "security_nb", None)
            ),
            "radio_detached": bool(getattr(self, "radio_detached", False)),
            "last_action": App._diagnostic_last_action_context(self),
            "runtime_state": App._diagnostic_runtime_state(self),
        }

    def _normalize_theme_name(self, theme_name):
        name = str(theme_name or "").strip().lower()
        return name if name in THEMES else "light"

    def _normalize_theme_studio_style(self, style_name):
        style = str(style_name or "").strip().lower()
        return style if style in {"dezent", "kräftig", "warm", "kühl"} else "dezent"

    def _compose_theme(
        self,
        theme_name,
        accent_override="",
        panel_override="",
        style_mode="dezent",
    ):
        base = dict(THEMES.get(self._normalize_theme_name(theme_name), LIGHT_THEME))
        style_mode = self._normalize_theme_studio_style(style_mode)
        accent = normalize_hex_color(accent_override) or base["accent"]
        panel_bg = normalize_hex_color(panel_override) or base["panel_bg"]

        if style_mode == "warm":
            accent = blend_hex_colors(accent, "#ffb36b", 0.24)
        elif style_mode == "kühl":
            accent = blend_hex_colors(accent, "#6bb8ff", 0.24)

        style_levels = {
            "dezent": {"tab": 0.10, "selected": 0.20, "border": 0.18, "select": 0.16},
            "kräftig": {"tab": 0.20, "selected": 0.34, "border": 0.28, "select": 0.30},
            "warm": {"tab": 0.14, "selected": 0.26, "border": 0.22, "select": 0.22},
            "kühl": {"tab": 0.14, "selected": 0.26, "border": 0.22, "select": 0.22},
        }
        levels = style_levels[style_mode]

        theme = dict(base)
        theme["bg"] = panel_bg
        theme["panel_bg"] = panel_bg
        theme["accent"] = accent
        theme["border"] = blend_hex_colors(panel_bg, accent, levels["border"])
        theme["tab_bg"] = blend_hex_colors(panel_bg, accent, levels["tab"])
        theme["tab_selected_bg"] = blend_hex_colors(
            panel_bg, accent, levels["selected"]
        )
        theme["select_bg"] = blend_hex_colors(panel_bg, accent, levels["select"])
        theme["entry_bg"] = blend_hex_colors(panel_bg, "#ffffff", 0.18)
        theme["text_bg"] = blend_hex_colors(panel_bg, "#ffffff", 0.10)
        theme["tree_bg"] = blend_hex_colors(panel_bg, "#ffffff", 0.08)
        theme["tab_fg"] = ideal_text_color(theme["tab_bg"])
        theme["tab_selected_fg"] = ideal_text_color(theme["tab_selected_bg"])
        theme["select_fg"] = ideal_text_color(theme["select_bg"])
        theme["fg"] = ideal_text_color(panel_bg)
        theme["muted_fg"] = blend_hex_colors(theme["fg"], panel_bg, 0.42)
        theme["entry_fg"] = ideal_text_color(theme["entry_bg"])
        theme["text_fg"] = ideal_text_color(theme["text_bg"])
        theme["tree_fg"] = ideal_text_color(theme["tree_bg"])
        theme["chat_user_header_fg"] = accent
        theme["chat_assistant_header_fg"] = blend_hex_colors(accent, theme["fg"], 0.35)
        return theme

    def _get_theme(self, theme_name):
        normalized = self._normalize_theme_name(theme_name)
        if normalized != "pop":
            return dict(THEMES.get(normalized, LIGHT_THEME))
        settings = getattr(self, "settings", {}) or {}
        return self._compose_theme(
            normalized,
            accent_override=settings.get("theme_custom_accent", ""),
            panel_override=settings.get("theme_custom_panel_bg", ""),
            style_mode=settings.get("theme_custom_style", "dezent"),
        )

    def _get_next_theme_name(self, theme_name):
        current = self._normalize_theme_name(theme_name)
        try:
            index = THEME_SEQUENCE.index(current)
        except ValueError:
            index = 0
        return THEME_SEQUENCE[(index + 1) % len(THEME_SEQUENCE)]

    def _get_theme_display_name(self, theme_name):
        return THEME_DISPLAY_NAMES.get(
            self._normalize_theme_name(theme_name),
            THEME_DISPLAY_NAMES["light"],
        )

    def _get_theme_toggle_label(self, current_theme_name):
        next_theme = self._get_next_theme_name(current_theme_name)
        return self._get_theme_display_name(next_theme)

    def _get_theme_header_label(self, theme_name):
        normalized = self._normalize_theme_name(theme_name)
        display_name = self._get_theme_display_name(normalized)
        if normalized == "pop":
            display_name = f"{display_name} (User)"
        return f"Theme: {display_name}"

    def select_theme(self, theme_name, *, log_change=True, persist=True):
        normalized = self._normalize_theme_name(theme_name)
        settings = self.__dict__.get("settings")
        if isinstance(settings, dict):
            settings["theme"] = normalized
        self._preferred_theme_name = normalized
        theme_choice_var = self.__dict__.get("var_theme_choice")
        if theme_choice_var is not None:
            try:
                theme_choice_var.set(self._get_theme_display_name(normalized))
            except Exception:
                pass
        try:
            self.apply_theme(normalized, log_change=log_change, persist=persist)
        except TypeError:
            self.apply_theme(normalized)

    def _install_theme_toggle_button(self):
        if self._theme_toggle_btn is not None:
            return
        btn = ttk.Menubutton(
            self,
            textvariable=self._theme_header_var,
            direction="below",
        )
        menu = tk.Menu(btn, tearoff=False)
        for theme_name, label in (
            ("light", "Light"),
            ("dark", "Dark"),
            ("beige", "Beige"),
            ("pop", "Pop (User)"),
        ):
            menu.add_command(
                label=label,
                command=lambda name=theme_name: self.select_theme(name),
            )
        btn.configure(menu=menu)
        btn.place(x=24, y=10, anchor="ne")
        self._theme_toggle_btn = btn
        self._theme_toggle_menu = menu
        self.add_tooltip(
            btn,
            "Wählt eines der festen NetMon-Themes. Pop bleibt das benutzerdefinierte Testprofil.",
        )
        self.after(250, self._position_theme_button)
        self.after(900, self._position_theme_button)
        self.bind("<Configure>", self._on_window_configure, add="+")

    def _on_window_configure(self, _event=None):
        self.after(50, self._position_theme_button)

    def _find_terminal_button(self):
        stack = [self]
        while stack:
            node = stack.pop()
            for child in node.winfo_children():
                stack.append(child)
                try:
                    if (
                        isinstance(child, ttk.Button)
                        and str(child.cget("text")) == "Terminal"
                    ):
                        return child
                except Exception:
                    pass
        return None

    def _position_theme_button(self):
        if self._theme_toggle_btn is None:
            return
        try:
            self.update_idletasks()
            right_margin = 16
            x = max(180, self.winfo_width() - right_margin)
            y = 12
            self._theme_toggle_btn.place(x=x, y=y, anchor="ne")
            self._theme_toggle_btn.lift()
        except Exception:
            self._theme_toggle_btn.place(x=24, y=10, anchor="ne")
            try:
                self._theme_toggle_btn.lift()
            except Exception:
                pass

    def toggle_theme(self):
        current = (self._app_theme or LIGHT_THEME).get("name", "light")
        next_theme = self._get_next_theme_name(current)
        self.select_theme(next_theme)

    def apply_theme(self, theme_name, log_change=True, persist=True):
        theme = self._get_theme(theme_name)
        self._app_theme = theme
        self._preferred_theme_name = theme["name"]

        self._apply_ttk_theme(theme)
        self._apply_tk_widget_theme(self, theme)

        if self._theme_toggle_btn is not None:
            self._theme_name_var.set(self._get_theme_toggle_label(theme["name"]))
            self.after(0, self._position_theme_button)
        theme_header_var = self.__dict__.get("_theme_header_var")
        if theme_header_var is not None:
            try:
                theme_header_var.set(self._get_theme_header_label(theme["name"]))
            except Exception:
                pass

        if persist and hasattr(self, "privacy_config_path"):
            try:
                self.save_privacy_config()
            except Exception:
                pass

        if log_change:
            self.log(f"Theme gewechselt: {theme['name']}")
        try:
            self.refresh_theme_studio_preview()
        except Exception:
            pass
        cleanup_ui = self.__dict__.get("cleanup_assistant_tab_ui")
        if cleanup_ui is not None:
            try:
                cleanup_ui.apply_theme(theme)
            except Exception:
                pass
        try:
            self._apply_dependency_installer_theme(theme)
        except Exception:
            pass

    def _apply_dependency_installer_theme(self, theme):
        win = getattr(self, "dep_installer_window", None)
        if win is None:
            return
        try:
            if not bool(win.winfo_exists()):
                return
        except Exception:
            return
        self._apply_tk_widget_theme(win, theme)

    def _ensure_colorable_ttk_theme(self):
        style = self.style if hasattr(self, "style") else ttk.Style(self)
        try:
            theme_names = style.theme_names()
        except Exception:
            theme_names = ()
        if "clam" not in theme_names:
            return
        try:
            if style.theme_use() != "clam":
                style.theme_use("clam")
        except Exception:
            pass

    def _apply_ttk_theme(self, theme):
        style = self.style if hasattr(self, "style") else ttk.Style(self)
        self._ensure_colorable_ttk_theme()

        style.configure(".", background=theme["panel_bg"], foreground=theme["fg"])
        style.configure("TFrame", background=theme["panel_bg"])
        style.configure(
            "TLabelframe",
            background=theme["panel_bg"],
            foreground=theme["fg"],
            bordercolor=theme["border"],
        )
        style.configure(
            "TLabelframe.Label", background=theme["panel_bg"], foreground=theme["fg"]
        )
        style.configure("TLabel", background=theme["panel_bg"], foreground=theme["fg"])
        style.configure(
            "TButton",
            background=theme["tab_bg"],
            foreground=theme["fg"],
            bordercolor=theme["border"],
            focuscolor=theme["accent"],
            padding=(6, 3),
        )
        style.configure("LinkSlot.TButton", padding=(12, 10), width=22)
        style.map(
            "TButton",
            background=[("active", theme["tab_selected_bg"])],
            foreground=[("disabled", theme["disabled_fg"]), ("active", theme["fg"])],
        )

        style.configure(
            "TCheckbutton",
            background=theme["panel_bg"],
            foreground=theme["fg"],
            indicatorcolor=theme["entry_bg"],
            focuscolor=theme["accent"],
            padding=(4, 2),
        )
        style.map(
            "TCheckbutton",
            foreground=[("disabled", theme["disabled_fg"]), ("active", theme["fg"])],
            indicatorcolor=[
                ("selected", theme["accent"]),
                ("!selected", theme["entry_bg"]),
            ],
        )
        style.configure(
            "TRadiobutton",
            background=theme["panel_bg"],
            foreground=theme["fg"],
            indicatorcolor=theme["entry_bg"],
            focuscolor=theme["accent"],
        )
        style.map(
            "TRadiobutton",
            foreground=[("disabled", theme["disabled_fg"]), ("active", theme["fg"])],
            indicatorcolor=[
                ("selected", theme["accent"]),
                ("!selected", theme["entry_bg"]),
            ],
        )

        style.configure(
            "TEntry",
            fieldbackground=theme["entry_bg"],
            foreground=theme["entry_fg"],
            bordercolor=theme["border"],
            insertcolor=theme["entry_fg"],
        )
        style.configure(
            "TCombobox",
            fieldbackground=theme["entry_bg"],
            background=theme["entry_bg"],
            foreground=theme["entry_fg"],
            bordercolor=theme["border"],
            arrowcolor=theme["fg"],
            insertcolor=theme["entry_fg"],
        )
        style.map(
            "TCombobox",
            fieldbackground=[
                ("readonly", theme["entry_bg"]),
                ("disabled", theme["panel_bg"]),
            ],
            background=[
                ("readonly", theme["entry_bg"]),
                ("active", theme["tab_selected_bg"]),
            ],
            foreground=[
                ("disabled", theme["disabled_fg"]),
                ("readonly", theme["entry_fg"]),
            ],
            arrowcolor=[("disabled", theme["disabled_fg"]), ("!disabled", theme["fg"])],
        )

        style.configure("TNotebook", background=theme["panel_bg"], borderwidth=0)
        style.configure(
            "TNotebook.Tab",
            background=theme["tab_bg"],
            foreground=theme["tab_fg"],
            padding=(8, 4),
        )
        style.map(
            "TNotebook.Tab",
            background=[
                ("selected", theme["tab_selected_bg"]),
                ("active", theme["tab_bg"]),
            ],
            foreground=[
                ("selected", theme["tab_selected_fg"]),
                ("!selected", theme["tab_fg"]),
            ],
        )

        style.configure(
            "Treeview",
            background=theme["tree_bg"],
            foreground=theme["tree_fg"],
            fieldbackground=theme["tree_bg"],
            bordercolor=theme["border"],
        )
        style.map(
            "Treeview",
            background=[("selected", theme["select_bg"])],
            foreground=[("selected", theme["select_fg"])],
        )
        style.configure(
            "Treeview.Heading",
            background=theme["tab_bg"],
            foreground=theme["fg"],
            bordercolor=theme["border"],
        )
        style.configure(
            "TScrollbar",
            background=theme["tab_bg"],
            troughcolor=theme["panel_bg"],
            bordercolor=theme["border"],
            arrowcolor=theme["fg"],
        )
        style.configure(
            "TScale",
            background=theme["panel_bg"],
            troughcolor=theme["tab_bg"],
            bordercolor=theme["border"],
        )
        style.configure("TPanedwindow", background=theme["panel_bg"])
        style.configure("Sash", background=theme["border"])

        try:
            self.configure(bg=theme["bg"])
        except Exception:
            pass

    def _apply_tk_widget_theme(self, widget, theme):
        klass = str(widget.winfo_class())
        preserve_colors = bool(getattr(widget, "_preserve_theme_colors", False))

        try:
            if klass in {"Frame", "Labelframe", "LabelFrame", "Toplevel"}:
                widget.configure(bg=theme["panel_bg"])
            elif klass in {"Label"}:
                if not preserve_colors:
                    widget.configure(bg=theme["panel_bg"], fg=theme["fg"])
            elif klass in {"Button", "Checkbutton", "Radiobutton"}:
                widget.configure(
                    bg=theme["tab_bg"],
                    fg=theme["fg"],
                    activebackground=theme["tab_selected_bg"],
                    activeforeground=theme["fg"],
                    selectcolor=theme["panel_bg"],
                    highlightbackground=theme["border"],
                )
            elif klass in {"Entry", "Spinbox"}:
                widget.configure(
                    bg=theme["entry_bg"],
                    fg=theme["entry_fg"],
                    insertbackground=theme["entry_fg"],
                    highlightbackground=theme["border"],
                )
            elif klass == "Text":
                widget.configure(
                    bg=theme["text_bg"],
                    fg=theme["text_fg"],
                    insertbackground=theme["text_fg"],
                    selectbackground=theme["select_bg"],
                    selectforeground=theme["select_fg"],
                    highlightbackground=theme["border"],
                )
            elif klass == "Listbox":
                widget.configure(
                    bg=theme["text_bg"],
                    fg=theme["text_fg"],
                    selectbackground=theme["select_bg"],
                    selectforeground=theme["select_fg"],
                    highlightbackground=theme["border"],
                )
            elif klass == "Canvas":
                widget.configure(
                    bg=theme["panel_bg"],
                    highlightbackground=theme["border"],
                    highlightthickness=0,
                )
        except Exception:
            pass

        for child in widget.winfo_children():
            self._apply_tk_widget_theme(child, theme)

        if widget is self:
            self._apply_log_theme(theme)
            self._apply_chad_chat_theme(theme)

    def _apply_log_theme(self, theme):
        log_view_frame = self.__dict__.get("log_view_frame")
