    # ---------- UI helpers ----------
    def make_light(self, parent, label):
        return build_light_widget(parent, label, tk_module=tk, ttk_module=ttk)

    def set_light(self, light, color):
        update_light_widget(light, color)

    def _bind_light_click(self, light, key):
        for part in light:
            if not hasattr(part, "bind"):
                continue
            try:
                part.bind(
                    "<Button-1>",
                    lambda _event, light_key=key: self.on_light_click(light_key),
                    add="+",
                )
            except Exception:
                pass
            try:
                part.configure(cursor="hand2")
            except Exception:
                pass

    def on_light_click(self, key):
        nb = self.__dict__.get("nb")
        if key == "dns":
            tab = self.__dict__.get("tab_dns")
            if nb is not None and tab is not None:
                nb.select(tab)
        elif key == "vpn":
            target = self.__dict__.get("tab_vpn_slots") or self.__dict__.get(
                "tab_system"
            )
            if target is not None:
                self._select_system_tab(target)
        elif key in {"ufw", "ufw_logging"}:
            tab = self.__dict__.get("tab_firewall") or self.__dict__.get("tab_security")
            if tab is not None:
                self._select_security_tab(tab)
        elif key == "security":
            tab = self.__dict__.get("tab_firewall") or self.__dict__.get("tab_security")
            if tab is not None:
                self._select_security_tab(tab)
        elif key in {"killswitch", "ssh"}:
            tab = self.__dict__.get("tab_security")
            if tab is not None:
                self._select_security_tab(tab)
        elif key == "connections":
            tab = self.__dict__.get("tab_conn")
            if nb is not None and tab is not None:
                nb.select(tab)
        elif key == "dns_guard":
            self.show_dns_guard_details()
        elif key == "startup_guard":
            self.open_startup_guard_tab()
        elif key == "path_guard":
            tab = self.__dict__.get("tab_path_guard") or self.__dict__.get(
                "tab_security"
            )
            if tab is not None:
                self._select_security_tab(tab)
        elif key == "process_guard":
            tab = self.__dict__.get("tab_process_guard")
            if tab is not None:
                self._select_security_tab(tab)
        elif key == "capture":
            tab = self.__dict__.get("tab_packet_capture")
            if tab is not None:
                self._select_security_tab(tab)
        elif key == "game_mode":
            self.open_game_mode_tab()
        elif key == "dot":
            tab = self.__dict__.get("tab_dns")
            if nb is not None and tab is not None:
                nb.select(tab)
        elif key == "ipv6":
            target = self.__dict__.get("tab_system")
            if target is not None:
                self._select_system_tab(target)

    def show_firewall_menu(self, event):
        menu = tk.Menu(self, tearoff=0)
        menu.add_command(
            label="Firewall AN",
            command=self.fw_enable,
        )
        menu.add_command(
            label="Firewall AUS",
            command=self.fw_disable,
        )
        menu.add_separator()
        menu.add_command(
            label="Firewall Status",
            command=self.show_firewall_status_clean,
        )
        return self._show_context_menu(menu, event)

    def show_vpn_profile_menu(self, event):
        menu = tk.Menu(self, tearoff=0)
        profiles = self.get_available_vpn_profiles()
        current = self.get_current_vpn_profile()

        if not profiles:
            menu.add_command(
                label=self.tr("menu_no_vpn_profiles_found", "No VPN profiles found"),
                state="disabled",
            )
        else:
            for profile in profiles:
                label = f"✔ {profile}" if profile == current else profile
                menu.add_command(
                    label=label,
                    command=lambda p=profile: self.switch_vpn_profile(p),
                )

        menu.add_separator()
        menu.add_command(
            label="VPN trennen",
            command=self.disconnect_vpn,
        )
        return self._show_context_menu(menu, event)

    def show_firewall_status_clean(self):
        try:
            nb = self.__dict__.get("nb")
            tab_log = self.__dict__.get("tab_log")
            if nb is not None and tab_log is not None:
                nb.select(tab_log)
            if bool(self.__dict__.get("log_overlay_active", False)):
                self.toggle_log_overlay()
            self.clear_log()
            self.fw_status()
            self._append_firewall_log_link()
        except Exception as e:
            self.log_safe(f"Firewall Status Fehler: {e}")

    def show_firewall_ufw_logging_high(self):
        self.show_firewall_ufw_logging("high")

