    def set_dns_guard_enabled(self, enabled):
        enabled = bool(enabled)
        self.dns_guard_enabled = enabled

        guard_var = self.__dict__.get("dns_guard_enabled_var")
        if guard_var is not None:
            try:
                guard_var.set(enabled)
            except Exception:
                pass

        settings_var = self.__dict__.get("var_dns_guard_enabled")
        if settings_var is not None:
            try:
                settings_var.set(enabled)
            except Exception:
                pass

        self.save_privacy_config()

        if enabled:
            self.log_safe("DNS Guard aktiviert.")
        else:
            self.log_safe("DNS Guard deaktiviert.")

        if hasattr(self, "update_dns_guard_indicator"):
            self.after(300, self.update_dns_guard_indicator)

