    def _looks_like_rkhunter_web_cmd_issue(self, text):
        lowered = str(text or "").strip().lower()
        return (
            "invalid web_cmd configuration option" in lowered
            or "web_cmd" in lowered
            and "/bin/false" in lowered
        )

    def _looks_like_dumpcap_permission_issue(self, text):
        lowered = str(text or "").strip().lower()
        if not lowered:
            return False
        if "dumpcap" not in lowered:
            return False
        markers = [
            "permission denied",
            "you do not have permission",
            "operation not permitted",
            "cap_set_proc",
            "couldn't run",
            "could not run",
        ]
        return any(marker in lowered for marker in markers)

    def refresh_safe(self):
        if threading.current_thread() is threading.main_thread():
            self.refresh()
            if "dns_combo" in self.__dict__:
                self.update_dns_controls_state_safe()
            return
        self.after(0, self.refresh)
        if "dns_combo" in self.__dict__:
            self.update_dns_controls_state_safe()

    def update_ipv6_controls_state_safe(self):
        if threading.current_thread() is threading.main_thread():
            self.update_ipv6_controls_state()
            return
        self.after(0, self.update_ipv6_controls_state)

    def _set_stealth_enabled_state(self, enabled):
        self.isp_stealth_enabled.set(enabled)
        self.save_privacy_config()

    def _set_dns_choice_safe(self, choice):
        stealth_dns_var = self.__dict__.get("isp_stealth_dns_profile")
        dns_choice_var = self.__dict__.get("dns_choice")
        if threading.current_thread() is threading.main_thread():
            if dns_choice_var is not None:
                dns_choice_var.set(choice)
            self._sync_dns_protocol_profile_labels()
            if stealth_dns_var is not None:
                try:
                    stealth_dns_var.set(choice)
                except Exception:
                    pass
            return
        self.after(
            0,
            lambda c=choice, v=stealth_dns_var, dns_var=dns_choice_var: (
                dns_var.set(c) if dns_var is not None else None,
                self._sync_dns_protocol_profile_labels(),
                v.set(c) if v is not None else None,
            ),
        )

    def is_vpn_active_for_dns_ui(self):
        service = self._dns_control_service()
        if service is not None:
            code, out = service.read_resolvectl_status(timeout=6)
            if code != 0:
                return False
            return service.detect_vpn_active(out)
        code, out = run_cmd(["resolvectl", "status"], timeout=6)
        if code != 0:
            return False
        text = (out or "").lower()
        return any(
            token in text for token in ("proton", "wireguard", "wg", "tun", "vpn")
        )

    def _dns_controls_locked(self):
        if self.is_vpn_active_for_dns_ui():
            return True, "vpn"
        if self._dns_runtime_transition_active():
            return True, "transition"
        return False, ""

    def update_dns_controls_state(self):
        controls_locked, lock_reason = self._dns_controls_locked()
        dot_active = self.is_dot_active()

        if controls_locked:
            combo_state = "disabled"
            if lock_reason == "transition":
                hint = self.tr(
                    "dns_hint_transition_lock",
                    "VPN/DNS-Wechsel läuft – DNS wird vorübergehend gesperrt.",
                )
            else:
                hint = self.tr(
                    "dns_hint_vpn_managed",
                    "VPN aktiv – DNS wird vom VPN-Profil verwaltet.",
                )
        elif dot_active:
            combo_state = "readonly"
            hint = self.tr(
                "dns_hint_dot_active_selection_monitored",
                "DoT active: DNS selection is active and global resolver paths are monitored.",
            )
        else:
            combo_state = "readonly"
            hint = self.tr("dns_status_selection_active", "DNS selection active.")

        combo = self.__dict__.get("dns_combo")
        if combo is not None:
            try:
                combo.configure(state=combo_state)
            except Exception:
                pass

        action_states = {
            "btn_dns_apply": "disabled" if controls_locked else "normal",
            "btn_dot_on": "disabled" if (controls_locked or dot_active) else "normal",
            "btn_dot_on_side": (
                "disabled" if (controls_locked or dot_active) else "normal"
            ),
            "btn_dot_off": "normal",
            "btn_dot_off_side": "normal",
        }

        for attr, state in action_states.items():
            btn = self.__dict__.get(attr)
            if btn is not None:
                try:
                    btn.configure(state=state)
                except Exception:
                    pass

        hint_var = self.__dict__.get("dns_control_hint_var")
        if hint_var is not None:
            try:
                hint_var.set(hint)
            except Exception:
                pass

    def update_dns_controls_state_safe(self):
        if threading.current_thread() is threading.main_thread():
            self.update_dns_controls_state()
            return
        self.after(0, self.update_dns_controls_state)

    def get_vpn_state(self):
        return self.is_vpn_active()

    def get_active_vpn_dns(self):
        vpn_iface, vpn_dns, _raw = self.find_vpn_dns_servers()
        return vpn_dns if vpn_iface or vpn_dns else []

    def get_selected_user_dns(self):
        choice = self._manual_dns_choice()
        servers = self._dns_servers_for_choice(choice)
        if not servers:
            return []
        return [str(server).strip() for server in servers if str(server).strip()]

    def _is_valid_manual_dns_hostname(self, value):
        hostname = str(value or "").strip().strip(".")
        if not hostname or len(hostname) > 253:
            return False
        if hostname.lower() == "localhost":
            return True
        labels = hostname.split(".")
        return all(
            label
            and len(label) <= 63
            and re.fullmatch(r"[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?", label)
            for label in labels
        )

    def _parse_manual_dns_entries(self, value):
        raw_value = str(value or "").strip()
        if not raw_value:
            return []

        parts = [part.strip() for part in re.split(r"[;,]", raw_value) if part.strip()]
        if not parts:
            return []

        entries = []
        for part in parts:
            dns_server = part
            dns_hostname = ""
            if "#" in part:
                dns_server, dns_hostname = part.split("#", 1)
            else:
                tokens = part.split()
                if len(tokens) == 2:
                    dns_server, dns_hostname = tokens
                elif len(tokens) == 1:
                    dns_server = tokens[0]
                else:
                    return []

            normalized_server = str(dns_server or "").strip().strip("[]")
            normalized_hostname = str(dns_hostname or "").strip().strip("[]")
            if not normalized_server:
                return []
            try:
                ipaddress.ip_address(normalized_server)
            except ValueError:
                return []
            if normalized_hostname and not self._is_valid_manual_dns_hostname(
                normalized_hostname
            ):
                return []

            entry = normalized_server
            if normalized_hostname:
                entry = f"{entry}#{normalized_hostname}"
            if entry not in entries:
                entries.append(entry)
        return entries

    def _normalize_custom_dns_profile_name(self, value):
        return re.sub(r"\s+", " ", str(value or "").strip())

    def _default_custom_dns_profile_name(self, entries):
        normalized = [
            str(entry).strip() for entry in (entries or []) if str(entry).strip()
        ]
        return ", ".join(normalized)

    def _ensure_unique_custom_dns_profile_name(self, name, exclude_name=""):
        base_name = self._normalize_custom_dns_profile_name(name)
        if not base_name:
            return ""
        exclude_name = self._normalize_custom_dns_profile_name(exclude_name)
        existing_names = {
            self._normalize_custom_dns_profile_name(item.get("name"))
            for item in (self.__dict__.get("custom_dns_profiles", []) or [])
            if isinstance(item, dict)
        }
        existing_names.update(
            self._normalize_custom_dns_profile_name(choice)
            for choice in DNS_PROFILES
            if choice != "System (DHCP/auto)"
        )
        if exclude_name:
            existing_names.discard(exclude_name)
        if base_name not in existing_names:
            return base_name
        idx = 2
        while True:
            candidate = f"{base_name} ({idx})"
            if candidate not in existing_names:
                return candidate
            idx += 1

    def _normalize_custom_dns_profile(self, profile):
        if isinstance(profile, str):
            entries = self._parse_manual_dns_entries(profile)
            if not entries:
                return None
            return {
                "name": self._default_custom_dns_profile_name(entries),
                "servers": entries,
                "source": "custom",
            }

        if not isinstance(profile, dict):
            return None

        raw_servers = profile.get("servers")
        if isinstance(raw_servers, (list, tuple)):
            entries = []
            for item in raw_servers:
                entries.extend(self._parse_manual_dns_entries(item))
        else:
            entries = self._parse_manual_dns_entries(raw_servers)
        if not entries:
            return None

        raw_name = self._normalize_custom_dns_profile_name(profile.get("name"))
        name = raw_name or self._default_custom_dns_profile_name(entries)
        return {
            "name": name,
            "servers": entries,
            "source": "custom",
        }

    def _set_custom_dns_profiles(self, profiles):
        normalized_profiles = []
        seen_names = set()
        for profile in profiles or []:
            normalized = self._normalize_custom_dns_profile(profile)
            if not normalized:
                continue
            name = self._ensure_unique_custom_dns_profile_name(normalized["name"])
            if not name or name in seen_names:
                continue
            normalized["name"] = name
            normalized_profiles.append(normalized)
            seen_names.add(name)
        self.custom_dns_profiles = normalized_profiles
        self.custom_dns_profile_choices = [
            item.get("name") for item in normalized_profiles if item.get("name")
        ]
        self._refresh_dns_profile_choices()

    def _custom_dns_profiles_for_config(self):
        profiles = []
        for profile in self.__dict__.get("custom_dns_profiles", []) or []:
            normalized = self._normalize_custom_dns_profile(profile)
            if not normalized:
                continue
            profiles.append(
                {
                    "name": normalized["name"],
                    "servers": list(normalized["servers"]),
                    "source": "custom",
                }
            )
        return profiles

    def _get_custom_dns_profile(self, choice):
        normalized_choice = self._normalize_custom_dns_profile_name(choice)
        if not normalized_choice:
            return None
        for profile in self.__dict__.get("custom_dns_profiles", []) or []:
            if (
                self._normalize_custom_dns_profile_name(profile.get("name"))
                == normalized_choice
            ):
                return profile
        return None

    def _builtin_dns_profiles_for_manager(self):
        profiles = []
        for item in DNS_PROVIDER_CATALOG:
            name = self._normalize_custom_dns_profile_name(item.get("name"))
            servers = [
                str(server).strip()
                for server in (item.get("servers") or [])
                if str(server).strip()
            ]
            if not name or not servers:
                continue
            profiles.append(
                {
                    "name": name,
                    "servers": servers,
                    "category": str(item.get("category") or "Standard").strip()
                    or "Standard",
                    "source": "preset",
                }
            )
        return profiles

    def _dns_profiles_for_manager(self):
        profiles = []
        profiles.extend(self._builtin_dns_profiles_for_manager())
        for item in self.__dict__.get("custom_dns_profiles", []) or []:
            normalized = self._normalize_custom_dns_profile(item)
            if not normalized:
                continue
            profiles.append(
                {
                    "name": normalized["name"],
                    "servers": list(normalized["servers"]),
                    "category": "Eigene",
                    "source": "custom",
                }
            )
        return profiles

    def _get_dns_profile_for_manager(self, choice):
        normalized_choice = self._normalize_custom_dns_profile_name(choice)
        if not normalized_choice:
            return None
        for profile in self._dns_profiles_for_manager():
            if (
                self._normalize_custom_dns_profile_name(profile.get("name"))
                == normalized_choice
            ):
                return profile
        return None

    def _normalize_custom_dns_choice(self, choice):
        profile = self._get_custom_dns_profile(choice)
        if profile is not None:
            return str(profile.get("name") or "").strip()
        entries = self._parse_manual_dns_entries(choice)
        if not entries:
            return ""
        return ", ".join(entries)

    def _is_custom_dns_choice(self, choice):
        return bool(self._normalize_custom_dns_choice(choice))

    def get_dns_profile_choices(self):
        choices = list(DNS_PROFILES.keys())
        for profile in self.__dict__.get("custom_dns_profiles", []) or []:
            name = self._normalize_custom_dns_profile_name(profile.get("name"))
            if name and name not in choices:
                choices.append(name)
        for choice in self.__dict__.get("custom_dns_profile_choices", []) or []:
            normalized = self._normalize_custom_dns_profile_name(choice)
            if normalized and normalized not in choices:
                choices.append(normalized)
        return choices

    def _refresh_dns_profile_choices(self):
        choices = self.get_dns_profile_choices()
        combo = self.__dict__.get("dns_combo")
        if combo is not None:
            combo["values"] = choices
        return choices

    def _register_manual_dns_choice(self, choice):
        existing_profile = self._get_custom_dns_profile(choice)
        if existing_profile is not None:
            return str(existing_profile.get("name") or "").strip()
        normalized = self._normalize_custom_dns_choice(choice)
        if not normalized:
            return ""
        if self._get_custom_dns_profile(normalized) is None:
            self._set_custom_dns_profiles(
                list(self.__dict__.get("custom_dns_profiles", []) or [])
                + [
                    {
                        "name": normalized,
                        "servers": self._parse_manual_dns_entries(normalized),
                        "source": "custom",
                    }
                ]
            )
        self._refresh_dns_profile_choices()
        return normalized

    def _dns_servers_for_choice(self, choice):
        normalized_choice = str(choice or "").strip()
        if normalized_choice in DNS_PROFILES:
            servers = DNS_PROFILES.get(normalized_choice)
            return [
                str(server).strip() for server in (servers or []) if str(server).strip()
            ]
        profile = self._get_custom_dns_profile(normalized_choice)
        if profile is not None:
            return [
                str(server).strip()
                for server in (profile.get("servers") or [])
                if str(server).strip()
            ]
        return self._parse_manual_dns_entries(normalized_choice)

    def add_manual_dns_server(self):
        raw_value = self.manual_dns_entry_var.get()
        normalized_choice = self._register_manual_dns_choice(raw_value)
        if not normalized_choice:
            messagebox.showwarning(
                self.tr("dns_manual_invalid_title", "Invalid DNS server"),
                self.tr(
                    "dns_manual_invalid_message",
                    "Please enter a valid IPv4/IPv6 address, optionally with a DNS name, e.g. 1.1.1.1#cloudflare-dns.com.",
                ),
                parent=self,
            )
            return False
        self._set_dns_choice_safe(normalized_choice)
        self.manual_dns_entry_var.set("")
        self.save_privacy_config()
        self.log_safe(f"Manueller DNS zur Auswahl hinzugefügt: {normalized_choice}")
        try:
            self._refresh_dns_profile_manager_tree()
        except Exception:
            pass
        return True

    def remove_manual_dns_server(self, choice=None):
        selected_choice = str(choice or self._manual_dns_choice() or "").strip()
        normalized_choice = self._normalize_custom_dns_choice(selected_choice)
        if not normalized_choice:
            return False

        existing_profile = self._get_custom_dns_profile(normalized_choice)
        known_choices = {
            self._normalize_custom_dns_profile_name(item)
            for item in (self.__dict__.get("custom_dns_profile_choices", []) or [])
        }
        if existing_profile is None and normalized_choice not in known_choices:
            return False

        self._set_custom_dns_profiles(
            [
                item
                for item in (self.__dict__.get("custom_dns_profiles", []) or [])
                if self._normalize_custom_dns_profile_name(item.get("name"))
                != self._normalize_custom_dns_profile_name(normalized_choice)
            ]
        )
        self.custom_dns_profile_choices = [
            item
            for item in self.__dict__.get("custom_dns_profile_choices", []) or []
            if self._normalize_custom_dns_profile_name(item) != normalized_choice
        ]

        choice_var = self.__dict__.get("dns_choice")
        if choice_var is not None:
            try:
                current_choice = str(choice_var.get() or "").strip()
            except Exception:
                current_choice = ""
            if current_choice == normalized_choice:
                self._set_dns_choice_safe("System (DHCP/auto)")

        stealth_dns_var = self.__dict__.get("isp_stealth_dns_profile")
        if stealth_dns_var is not None:
            try:
                if str(stealth_dns_var.get() or "").strip() == normalized_choice:
                    stealth_dns_var.set("System (DHCP/auto)")
            except Exception:
                pass

        self.save_privacy_config()
        self.log_safe(f"Manueller DNS aus Auswahl entfernt: {normalized_choice}")
        try:
            self._refresh_dns_profile_manager_tree()
        except Exception:
            pass
        return True

    def upsert_custom_dns_profile(self, name, servers_value, previous_name=""):
        entries = self._parse_manual_dns_entries(servers_value)
        if not entries:
            return False, "Please enter at least one valid DNS server."

        raw_name = self._normalize_custom_dns_profile_name(name)
        if not raw_name:
            raw_name = self._default_custom_dns_profile_name(entries)

        profile_name = self._ensure_unique_custom_dns_profile_name(
            raw_name,
            exclude_name=previous_name,
        )
        previous_normalized = self._normalize_custom_dns_profile_name(previous_name)
        updated_profiles = []
        replaced = False

        for profile in self.__dict__.get("custom_dns_profiles", []) or []:
            current_name = self._normalize_custom_dns_profile_name(profile.get("name"))
            if previous_normalized and current_name == previous_normalized:
                updated_profiles.append(
                    {
                        "name": profile_name,
                        "servers": entries,
                        "source": "custom",
                    }
                )
                replaced = True
            else:
                updated_profiles.append(profile)

        if not replaced:
            updated_profiles.append(
                {
                    "name": profile_name,
                    "servers": entries,
                    "source": "custom",
                }
            )

        self._set_custom_dns_profiles(updated_profiles)

        choice_var = self.__dict__.get("dns_choice")
        if choice_var is not None:
            try:
                current_choice = self._normalize_custom_dns_profile_name(
                    choice_var.get() or ""
                )
            except Exception:
                current_choice = ""
            if previous_normalized and current_choice == previous_normalized:
                self._set_dns_choice_safe(profile_name)

        stealth_dns_var = self.__dict__.get("isp_stealth_dns_profile")
        if stealth_dns_var is not None:
            try:
                current_stealth = self._normalize_custom_dns_profile_name(
                    stealth_dns_var.get() or ""
                )
            except Exception:
                current_stealth = ""
            if previous_normalized and current_stealth == previous_normalized:
                stealth_dns_var.set(profile_name)

        self.save_privacy_config()
        return True, profile_name

    def _current_custom_dns_profile_for_manager(self):
        popup = self.__dict__.get("dns_profile_manager_popup")
        if popup is None or not popup.winfo_exists():
            return None
        name = self.__dict__.get("dns_profile_manager_selected_name")
        return self._get_dns_profile_for_manager(name)

    def _refresh_dns_profile_manager_tree(self):
        tree = self.__dict__.get("dns_profile_manager_tree")
        popup = self.__dict__.get("dns_profile_manager_popup")
        if tree is None or popup is None or not popup.winfo_exists():
            return

        selected_name = self.__dict__.get("dns_profile_manager_selected_name") or ""
        active_choice = self._normalize_custom_dns_choice(self._manual_dns_choice())
        for item_id in tree.get_children():
            tree.delete(item_id)

        for profile in self._dns_profiles_for_manager():
            name = str(profile.get("name") or "").strip()
            servers = ", ".join(profile.get("servers") or [])
            category = str(profile.get("category") or "–").strip() or "–"
            source = (
                self.tr("dns_profile_manager_source_system", "System")
                if profile.get("source") == "preset"
                else self.tr("dns_profile_manager_source_custom", "Custom")
            )
            is_active = (
                self.tr("dns_profile_manager_active_yes", "Yes")
                if name and name == active_choice
                else ""
            )
            item_id = tree.insert(
                "",
                "end",
                values=(name, servers, category, source, is_active),
            )
            if name and name == selected_name:
                tree.selection_set(item_id)

        status_var = self.__dict__.get("dns_profile_manager_active_var")
        if status_var is not None:
            try:
                if (
                    active_choice
                    and self._get_custom_dns_profile(active_choice) is not None
                ):
                    status_var.set(
                        self.tr(
                            "dns_profile_manager_status_active_custom",
                            "Active custom profile: {name}",
                        ).format(name=active_choice)
                    )
                elif active_choice and active_choice in DNS_PROFILES:
                    status_var.set(
                        self.tr(
                            "dns_profile_manager_status_active_profile",
                            "Active profile: {name}",
                        ).format(name=active_choice)
                    )
                else:
                    status_var.set(
                        self.tr(
                            "dns_profile_manager_status_active_system",
                            "Active profile: System (DHCP/auto)",
                        )
                    )
            except Exception:
                pass

    def _populate_dns_profile_manager_editor(self, profile=None):
        name_var = self.__dict__.get("dns_profile_manager_name_var")
        servers_var = self.__dict__.get("dns_profile_manager_servers_var")
        if name_var is None or servers_var is None:
            return
        if profile is None:
            self.dns_profile_manager_selected_name = ""
            name_var.set("")
            servers_var.set("")
            return
        self.dns_profile_manager_selected_name = str(profile.get("name") or "").strip()
        name_var.set(self.dns_profile_manager_selected_name)
        servers_var.set(", ".join(profile.get("servers") or []))

    def _on_dns_profile_manager_select(self, _event=None):
        tree = self.__dict__.get("dns_profile_manager_tree")
        if tree is None:
            return
        selection = tree.selection()
        if not selection:
            self._populate_dns_profile_manager_editor(None)
            return
        values = tree.item(selection[0], "values") or ()
        profile_name = str(values[0] or "").strip() if values else ""
        self._populate_dns_profile_manager_editor(
            self._get_dns_profile_for_manager(profile_name)
        )

    def _save_dns_profile_from_manager(self):
        name_var = self.__dict__.get("dns_profile_manager_name_var")
        servers_var = self.__dict__.get("dns_profile_manager_servers_var")
        if name_var is None or servers_var is None:
            return False
        previous_name = str(
            self.__dict__.get("dns_profile_manager_selected_name") or ""
        ).strip()
        ok, result = self.upsert_custom_dns_profile(
            name_var.get(),
            servers_var.get(),
            previous_name=previous_name,
        )
        if not ok:
            messagebox.showwarning(
                self.tr("dns_profile_dialog_title", "DNS profile"),
                result,
                parent=self,
            )
            return False
        self._populate_dns_profile_manager_editor(
            self._get_dns_profile_for_manager(result)
        )
        self._refresh_dns_profile_manager_tree()
        return True

    def _delete_dns_profile_from_manager(self):
        profile = self._current_custom_dns_profile_for_manager()
        if profile is None:
            return False
        if profile.get("source") != "custom":
            messagebox.showinfo(
                self.tr("dns_profile_dialog_title", "DNS profile"),
                self.tr(
                    "dns_profile_delete_preset_info",
                    "Predefined DNS profiles cannot be deleted. "
                    "Create your own profile based on these values if needed.",
                ),
                parent=self,
            )
            return False
        profile_name = str(profile.get("name") or "").strip()
        ok = messagebox.askyesno(
            self.tr("dns_profile_delete_title", "Delete DNS profile"),
            self.tr(
                "dns_profile_delete_confirm",
                "Delete DNS profile '{profile_name}'?",
            ).format(profile_name=profile_name),
            parent=self,
        )
        if not ok:
            return False
        removed = self.remove_manual_dns_server(profile_name)
        if removed:
            self._populate_dns_profile_manager_editor(None)
            self._refresh_dns_profile_manager_tree()
        return removed

    def _activate_dns_profile_from_manager(self):
        profile = self._current_custom_dns_profile_for_manager()
        if profile is None:
            return False
        profile_name = str(profile.get("name") or "").strip()
        self._set_dns_choice_safe(profile_name)
        stealth_dns_var = self.__dict__.get("isp_stealth_dns_profile")
        if stealth_dns_var is not None:
            try:
                stealth_dns_var.set(profile_name)
            except Exception:
                pass
        self.save_privacy_config()
        return True

    def open_dns_profile_manager(self):
        popup = self.__dict__.get("dns_profile_manager_popup")
        if popup is not None and popup.winfo_exists():
            try:
                popup.deiconify()
                popup.lift()
                popup.focus_force()
            except Exception:
                pass
            self._refresh_dns_profile_manager_tree()
            return

        popup = tk.Toplevel(self)
        popup.title(self.tr("dns_profile_manager_title", "Manage DNS profiles"))
        popup.transient(self)
        popup.resizable(True, True)
        popup.minsize(760, 420)
        popup.columnconfigure(0, weight=1)
        popup.rowconfigure(0, weight=1)
        self.dns_profile_manager_popup = popup
        self.dns_profile_manager_selected_name = self._normalize_custom_dns_choice(
            self._manual_dns_choice()
        )
        self.dns_profile_manager_name_var = tk.StringVar(value="")
        self.dns_profile_manager_servers_var = tk.StringVar(value="")
        self.dns_profile_manager_active_var = tk.StringVar(
            value=self.tr(
                "dns_profile_manager_status_none",
                "Active custom profile: none",
            )
        )

        container = ttk.Frame(popup, padding=12)
        container.grid(row=0, column=0, sticky="nsew")
        container.columnconfigure(0, weight=1)
        container.rowconfigure(0, weight=1)

        tree_frame = ttk.Frame(container)
        tree_frame.grid(row=0, column=0, sticky="nsew")
        tree_frame.columnconfigure(0, weight=1)
        tree_frame.rowconfigure(0, weight=1)

        columns = ("name", "servers", "category", "source", "active")
        tree = ttk.Treeview(
            tree_frame,
            columns=columns,
            show="headings",
            height=8,
        )
        tree.heading("name", text=self.tr("dns_profile_col_name", "Name"))
        tree.heading("servers", text=self.tr("dns_profile_col_servers", "DNS-Server"))
        tree.heading("category", text=self.tr("dns_profile_col_category", "Kategorie"))
        tree.heading("source", text=self.tr("dns_profile_col_type", "Typ"))
        tree.heading("active", text=self.tr("dns_profile_col_active", "Aktiv"))
        tree.column("name", width=180, anchor="w")
        tree.column("servers", width=320, anchor="w")
        tree.column("category", width=100, anchor="w")
        tree.column("source", width=70, anchor="center")
        tree.column("active", width=70, anchor="center")
        tree.grid(row=0, column=0, sticky="nsew")
        tree.bind("<<TreeviewSelect>>", self._on_dns_profile_manager_select)
        self.dns_profile_manager_tree = tree

        tree_scroll = ttk.Scrollbar(tree_frame, orient="vertical", command=tree.yview)
        tree_scroll.grid(row=0, column=1, sticky="ns")
        tree.configure(yscrollcommand=tree_scroll.set)

        status_row = ttk.Frame(container)
        status_row.grid(row=1, column=0, sticky="ew", pady=(8, 0))
        ttk.Label(
            status_row,
            textvariable=self.dns_profile_manager_active_var,
        ).pack(anchor="w")

        editor = ttk.LabelFrame(
            container,
            text=self.tr(
                "dns_profile_group_edit_or_create",
                "Edit or create profile",
            ),
            padding=8,
        )
        editor.grid(row=2, column=0, sticky="ew", pady=(10, 0))
        editor.columnconfigure(1, weight=1)

        ttk.Label(editor, text=self.tr("dns_profile_label_name", "Name:")).grid(
            row=0, column=0, sticky="w"
        )
        name_entry = ttk.Entry(
            editor,
            textvariable=self.dns_profile_manager_name_var,
            width=32,
        )
        name_entry.grid(row=0, column=1, sticky="ew", padx=(8, 0))
        self.attach_text_context_menu(name_entry)

        ttk.Label(
            editor,
            text=self.tr("dns_profile_label_servers", "DNS-Server:"),
        ).grid(row=1, column=0, sticky="w", pady=(8, 0))
        servers_entry = ttk.Entry(
            editor,
            textvariable=self.dns_profile_manager_servers_var,
        )
        servers_entry.grid(row=1, column=1, sticky="ew", padx=(8, 0), pady=(8, 0))
        self.attach_text_context_menu(servers_entry)

        ttk.Label(
            editor,
            text=self.tr(
                "dns_profile_servers_hint",
                "Separate multiple DNS servers with commas. Optionally add a hostname with #.\n"
                "Beispiel: 1.1.1.1#cloudflare-dns.com, 1.0.0.1#cloudflare-dns.com",
            ),
        ).grid(row=2, column=0, columnspan=2, sticky="w", pady=(8, 0))

        button_row = ttk.Frame(container)
        button_row.grid(row=3, column=0, sticky="ew", pady=(10, 0))

        ttk.Button(
            button_row,
            text=self.tr("dns_profile_btn_new", "New"),
            command=lambda: self._populate_dns_profile_manager_editor(None),
        ).pack(side="left")
        ttk.Button(
            button_row,
            text=self.tr("dns_profile_btn_save", "Save"),
            command=self._save_dns_profile_from_manager,
        ).pack(side="left", padx=(6, 0))
        ttk.Button(
            button_row,
            text=self.tr("dns_profile_btn_delete", "Delete"),
            command=self._delete_dns_profile_from_manager,
        ).pack(side="left", padx=(6, 0))
        ttk.Button(
            button_row,
            text=self.tr("dns_profile_btn_set_active", "Set as active"),
            command=self._activate_dns_profile_from_manager,
        ).pack(side="left", padx=(6, 0))
        ttk.Button(
            button_row,
            text=self.tr("btn_close", "Close"),
            command=popup.destroy,
        ).pack(side="right")

        def _close_popup():
            self.__dict__.pop("dns_profile_manager_popup", None)
            self.__dict__.pop("dns_profile_manager_tree", None)
            self.__dict__.pop("dns_profile_manager_name_var", None)
            self.__dict__.pop("dns_profile_manager_servers_var", None)
            self.__dict__.pop("dns_profile_manager_selected_name", None)
            self.__dict__.pop("dns_profile_manager_active_var", None)
            popup.destroy()

        popup.protocol("WM_DELETE_WINDOW", _close_popup)
        self._refresh_dns_profile_manager_tree()
        current_profile = self._get_dns_profile_for_manager(
            self.__dict__.get("dns_profile_manager_selected_name")
        )
        if current_profile is not None:
            self._populate_dns_profile_manager_editor(current_profile)

    def attach_dns_combo_context_menu(self):
        combo = self.__dict__.get("dns_combo")
        if combo is None:
            return

        attached = self.__dict__.setdefault("_dns_combo_context_menu_attached", set())
        widget_id = str(combo)
        if widget_id in attached:
            return
        attached.add(widget_id)

        menu = tk.Menu(combo, tearoff=0)

        def delete_selected_dns():
            choice_var = self.__dict__.get("dns_choice")
            current_choice = ""
            if choice_var is not None:
                try:
                    current_choice = str(choice_var.get() or "").strip()
                except Exception:
                    current_choice = ""
            self.remove_manual_dns_server(current_choice)

        menu.add_command(
            label=self.tr("menu_delete_dns_profile", "Delete DNS profile"),
            command=delete_selected_dns,
        )

        def show_menu(event):
            choice_var = self.__dict__.get("dns_choice")
            current_choice = ""
            if choice_var is not None:
                try:
                    current_choice = str(choice_var.get() or "").strip()
                except Exception:
                    current_choice = ""
            can_delete = bool(self._normalize_custom_dns_choice(current_choice))
            try:
                menu.entryconfigure(0, state="normal" if can_delete else "disabled")
            except Exception:
                pass
            try:
                combo.focus_set()
            except Exception:
                pass
            return self._show_context_menu(menu, event)

        combo.bind("<Button-3>", show_menu, add="+")
        combo._netmon_context_menu = menu

    def get_selected_dot_dns(self):
        choice_var = self.__dict__.get("dot_choice")
        profile_name = (
            (choice_var.get() if choice_var is not None else "") or ""
        ).strip()
        profile = DOT_PROFILES.get(profile_name, {})
        dns_values = [
            str(ip).strip() for ip in (profile.get("dns") or []) if str(ip).strip()
        ]
        hostname = (profile.get("hostname") or "").strip()
        if hostname:
            dns_values.extend([f"{ip}#{hostname}" for ip in dns_values])
        return dns_values

    def is_dot_active(self):
        if bool(self.__dict__.get("dot_enabled", False)):
            return True
        service = self._dns_control_service()
        if service is not None:
            code, out = service.read_resolvectl_status(timeout=6)
        else:
            code, out = run_cmd(["resolvectl", "status"], timeout=6)
        if code != 0:
            return False
        return "+DNSOverTLS" in out or "DNSOverTLS=yes" in out

    def normalize_dns_value(self, value: str) -> str:
        normalized = str(value or "").strip()
        if not normalized:
            return ""
        if "#" in normalized:
            normalized = normalized.split("#", 1)[0].strip()
        return normalized

    def rebuild_dns_guard_whitelist(self):
        if self.is_vpn_active():
            allowed = self.get_active_vpn_dns()
        elif self.is_dot_active():
            allowed = self.get_selected_dot_dns()
        else:
            allowed = self.get_selected_user_dns()
            if not allowed:
                allowed = self.get_current_dns()
        self.dns_guard_allowed_dns = [
            str(dns).strip() for dns in (allowed or []) if str(dns).strip()
        ]
        return list(self.dns_guard_allowed_dns)

    def _normalized_dns_values(self, values):
        return [
            self.normalize_dns_value(dns)
            for dns in (values or [])
            if self.normalize_dns_value(dns)
        ]

    def get_allowed_dns(self):
        cached = [
            str(dns).strip()
            for dns in (self.__dict__.get("dns_guard_allowed_dns") or [])
            if str(dns).strip()
        ]
        if cached:
            return cached
        return self.rebuild_dns_guard_whitelist()

    def get_current_dns(self):
        return self.get_active_dns_servers()

    def dns_is_clean(self, current, allowed):
        allowed_set = set(self._normalized_dns_values(allowed))
        current_set = set(self._normalized_dns_values(current))
        if not current_set:
            return False
        if not allowed_set:
            return False
        return current_set.issubset(allowed_set)

    def get_dns_guard_status(self):
        guard_var = self.__dict__.get("dns_guard_enabled_var")
        guard_enabled = bool(guard_var.get()) if guard_var is not None else False
        if not guard_enabled:
            return "off"

        if time.time() < float(self.__dict__.get("dns_guard_transition_until", 0.0)):
            return "transition"

        explicit_state = str(self.__dict__.get("dns_guard_state") or "").strip().lower()
        if explicit_state in {"ok", "problem", "off", "unknown", "transition", "error"}:
            return explicit_state

        current_dns = self.get_current_dns()
        allowed_dns = self.get_allowed_dns()
        normalized_allowed = self._normalized_dns_values(allowed_dns)

        if not current_dns:
            return "unknown"

        if not normalized_allowed:
            return "unknown"

        if not self.dns_is_clean(current_dns, allowed_dns):
            return "problem"

        return "ok"

    def update_dns_guard_indicator(self):
        status = self.get_dns_guard_status()
        if status == "ok":
            color = "green"
            text = self.tr("dns_guard_indicator_ok", "DNS Guard: aktiv (OK)")
        elif status == "problem":
            color = "red"
            text = self.tr("dns_guard_indicator_problem", "DNS Guard: Problem erkannt")
        elif status == "transition":
            color = "yellow"
            text = self.tr(
                "dns_guard_indicator_transition", "DNS Guard: Wechsel wird geprüft"
            )
        elif status == "off":
            color = "gray"
            text = self.tr("dns_guard_indicator_off", "DNS Guard: deaktiviert")
        else:
            color = "orange"
            text = self.tr("dns_guard_indicator_unknown", "DNS Guard: unbekannt")

        if "dns_guard_label" in self.__dict__:
            try:
                self.dns_guard_label.configure(text=text)
            except Exception:
                pass
        indicator = self.__dict__.get("dns_guard_indicator")
        if indicator is not None:
            self.set_light(indicator, color)
        return status

    def show_dns_guard_details(self):
        current = self.get_current_dns()
        allowed = self.get_allowed_dns()
        messagebox.showinfo(
            "DNS Guard Details",
            "Current DNS:\n"
            + ("\n".join(current) if current else "-")
            + "\n\nAllowed DNS:\n"
            + ("\n".join(allowed) if allowed else "-"),
            parent=self,
        )

    def dns_guard_ui_loop(self):
        try:
            self.update_dns_guard_indicator()
        finally:
            self.after(3000, self.dns_guard_ui_loop)

    def _set_dns_guard_status(self, status: str, last_action: str | None = None):
        self.dns_guard_status_var.set(
            self.tr("dns_guard_status_value", "DNS Guard: {status}").format(
                status=status
            )
        )
        if last_action is not None:
            self.dns_guard_last_action_var.set(last_action)

    def _start_dns_guard_transition(self, delay_ms=2000):
        self.dns_guard_transition_until = time.time() + max(1.0, delay_ms / 1000.0)
        self.set_dns_guard_state("transition")
        self.after(delay_ms, self.run_dns_guard_check_once)

    def cleanup_old_vpn_dns_links(self):
        actions = []
        code, out = run_cmd(["resolvectl", "status"], timeout=8)
        if code != 0:
            return actions

        candidates = set()
        get_ifaces = getattr(self, "get_wg_interfaces", None)
        if callable(get_ifaces):
            try:
                candidates.update(
                    str(iface).strip() for iface in (get_ifaces() or []) if iface
                )
            except Exception:
                pass

        for line in (out or "").splitlines():
            stripped = line.strip()
            if not stripped.startswith("Link "):
                continue
            low = stripped.lower()
            iface = ""
            try:
                iface = stripped.split("(", 1)[1].split(")", 1)[0].strip()
            except Exception:
                iface = ""
            iface_low = iface.lower()
            if any(
                token in low or token in iface_low
                for token in ("proton", "wireguard", "wg", "tun", "vpn")
            ):
                if iface:
                    candidates.add(iface)

        for iface in sorted(candidate for candidate in candidates if candidate):
            rc, _cmd_out = run_cmd(
                ["sudo", "-n", "resolvectl", "revert", iface], timeout=10
            )
            actions.append(f"resolvectl revert {iface}: rc={rc}")

        return actions

    def prepare_dns_for_vpn_profile_switch(self):
        actions = []
        cleanup_failed = False
        sudo_failed = False

        self.dns_guard_transition_until = time.time() + 4.0
        try:
            self.set_dns_guard_state("transition")
        except Exception:
            pass

        try:
            actions.extend(self.cleanup_old_vpn_dns_links())
        except Exception:
            cleanup_failed = True

        ok_remove, out_remove = self._remove_root_text_file(DOT_DROPIN_PATH)
        actions.append(
            (
                f"remove {os.path.basename(DOT_DROPIN_PATH)}",
                0 if ok_remove else 1,
                out_remove,
            )
        )
        if not ok_remove and (out_remove or "").strip():
            sudo_failed = True

        for cmd, label in (
            (
                ["sudo", "-n", "resolvectl", "flush-caches"],
                "resolvectl flush-caches",
            ),
            (
                ["sudo", "-n", "systemctl", "restart", "systemd-resolved"],
                "restart systemd-resolved",
            ),
        ):
            rc, out = run_cmd(cmd, timeout=15)
            actions.append(f"{label}: rc={rc}")
            if rc != 0:
                cleanup_failed = True
                low_out = (out or "").lower()
                if "sudo" in low_out or "password" in low_out:
                    sudo_failed = True

        self.__dict__["last_vpn_dns_cleanup_actions"] = list(actions)
        try:
            self.log_safe("Profilwechsel: DNS bereinigt, Recheck geplant.")
            if sudo_failed:
                self.log_safe("DNS Cleanup benötigt sudo-Rechte.")
        except Exception:
            pass

        if cleanup_failed:
            try:
                self.__dict__["dns_guard_last_cleanup_warning"] = True
            except Exception:
                pass

        return actions

    def _isp_dns_restore_choice_after_vpn(self):
        choice = self._manual_dns_choice()
        if choice != "System (DHCP/auto)":
            return choice
        return self._normalize_isp_dns_fallback_profile(
            self.__dict__.get("settings", {}).get("isp_dns_fallback_profile")
        )

    def _restore_isp_dns_after_vpn_switch(self):
        if self.__dict__.get("internet_vpn_restore_active", False):
            try:
                self.log_network_debug(
                    "[DEBUG] DNS nach VPN-Aus übersprungen: Internet-AN-Restore aktiv."
                )
            except Exception:
                pass
            return False

        try:
            if self.is_vpn_active():
                return False
        except Exception:
            return False

        choice = self._isp_dns_restore_choice_after_vpn()
        if not self._auto_dns_control_available():
            try:
                self.log_safe(
                    f"DNS nach VPN-Aus nicht gesetzt: sudo -n fehlt (Ziel: {choice})."
                )
            except Exception:
                pass
            return False

        ok = self._apply_automatic_dns_restore_choice(choice)

        try:
            self.log_safe(
                f"DNS nach VPN-Aus {'gesetzt' if ok else 'nicht gesetzt'}: {choice}"
            )
        except Exception:
            pass
        return bool(ok)

    def _apply_automatic_dns_restore_choice(self, choice):
        try:
            if self._dns_runtime_transition_active():
                self._set_dns_choice_safe(choice)
                result = self._apply_dns_profile_choice_via_control(choice)
                try:
                    self.refresh_dns_policy_status()
                except Exception:
                    pass
                return bool(result.get("success"))

            return bool(
                self.apply_dns(
                    choice=choice,
                    refresh_ui=False,
                    update_choice_var=True,
                    confirm_dnssec=False,
                )
            )
        except Exception as exc:
            try:
                self.log_safe(f"DNS nach VPN-Aus fehlgeschlagen: {exc}")
            except Exception:
                pass
            return False

    def _restore_isp_dns_on_startup_if_needed(self):
        try:
            if self.is_vpn_active():
                return False
        except Exception:
            return False

        if not self._auto_dns_control_available():
            return False

        if not has_cmd("resolvectl"):
            return self._restore_isp_dns_after_vpn_switch()

        rc, out = run_cmd(["resolvectl", "status"], timeout=8)
        if rc != 0:
            return self._restore_isp_dns_after_vpn_switch()

        active_dns = []
        try:
            active_dns = self._parse_active_dns_servers(out)
        except Exception:
            active_dns = []

        if active_dns:
            try:
                self.log_network_debug(
                    "[DEBUG] DNS-Startup-Fallback übersprungen: aktive DNS-Server vorhanden."
                )
            except Exception:
                pass
            return False

        try:
            self.log_safe(
                "DNS-Startup-Fallback wird angewendet: keine aktiven DNS-Server erkannt."
            )
        except Exception:
            pass
        return self._restore_isp_dns_after_vpn_switch()

    def finalize_dns_after_vpn_profile_switch(self):
        self.dns_guard_transition_until = 0.0
        self.__dict__.pop("_dns_finalize_scheduled_token", None)

        try:
            status = self._collect_dot_status(run_test=False)
            self._set_dot_state(
                status.get("ok"),
                profile=status.get("profile", ""),
                servers=status.get("servers") or [],
                mode=status.get("mode", ""),
                enabled=status.get("enabled"),
                vpn_conflict=status.get("vpn_conflict"),
                vpn_active=status.get("vpn_active"),
            )
        except Exception:
            pass

        try:
            self._restore_isp_dns_after_vpn_switch()
        except Exception:
            pass

        try:
            self.rebuild_dns_guard_whitelist()
        except Exception:
            pass

        try:
            self.run_dns_guard_check_once()
        except Exception:
            pass

        try:
            self.update_dns_controls_state()
        except Exception:
            pass

        try:
            self.run_dns_leak_check(quiet=True)
        except Exception:
            pass

    def _schedule_dns_finalize_after_vpn_profile_switch(self, delay_ms=2500):
        callback = self.finalize_dns_after_vpn_profile_switch
        token = int(self.__dict__.get("_dns_finalize_token", 0)) + 1
        self.__dict__["_dns_finalize_token"] = token
        self.__dict__["_dns_finalize_scheduled_token"] = token

        def guarded_callback():
            if token != int(self.__dict__.get("_dns_finalize_token", 0)):
                return
            try:
                callback()
            except Exception:
                pass

        after = getattr(self, "after", None)
        if callable(after):
            try:
                after(delay_ms, guarded_callback)
                return
            except Exception:
                pass
        try:
            guarded_callback()
        except Exception:
            pass

    def set_dns_guard_state(
        self,
        state: str,
        *,
        status_text: str | None = None,
        last_action: str | None = None,
        log_message: str | None = None,
    ):
        state_value = str(state or "unknown").strip().lower() or "unknown"
        previous = self.__dict__.get("last_dns_guard_state")
        self.dns_guard_state = state_value
        self.last_dns_guard_state = state_value

        status_map = {
            "off": self.tr("dns_guard_status_off", "deaktiviert"),
            "ok": self.tr("dns_guard_status_ok_clean", "aktiv / sauber"),
            "problem": self.tr("dns_guard_status_problem", "Problem erkannt"),
            "transition": self.tr(
                "dns_guard_status_transition", "Wechsel wird geprüft"
            ),
            "unknown": self.tr("dns_guard_status_unknown", "aktiv / unklar"),
            "error": self.tr("dns_guard_status_error", "aktiv / Fehler"),
        }
        text = status_text or status_map.get(state_value, state_value)
        self._set_dns_guard_status(text, last_action)

        if log_message and previous != state_value:
            self.log_safe(log_message)

        self.update_dns_guard_indicator()

    def run_dns_guard_check_once(self, auto_repair=False):
        if self.__dict__.get("dns_guard_check_running", False):
            return

        now = time.time()
        if now < float(self.__dict__.get("dns_guard_transition_until", 0.0)):
            self.set_dns_guard_state("transition")
            return

        self.dns_guard_check_running = True
        try:
            self.last_dns_guard_check_ts = now
            guard_var = self.__dict__.get("dns_guard_enabled_var")
            guard_enabled = bool(guard_var.get()) if guard_var is not None else False
            if not guard_enabled:
                self.set_dns_guard_state("off")
                return

            allowed = self.rebuild_dns_guard_whitelist()
            current = self.get_current_dns()
            normalized_allowed = self._normalized_dns_values(allowed)

            if not current:
                self.set_dns_guard_state("unknown")
                return

            if not normalized_allowed:
                if self.is_vpn_active():
                    status_text = self.tr(
                        "dns_guard_status_vpn_dns_unclear", "aktiv / VPN-DNS unklar"
                    )
                elif self.is_dot_active():
                    status_text = self.tr(
                        "dns_guard_status_dot_target_unclear",
                        "aktiv / DoT-Ziel unklar",
                    )
                else:
                    status_text = self.tr(
                        "dns_guard_status_dns_target_unclear",
                        "aktiv / DNS-Ziel unklar",
                    )
                self.set_dns_guard_state(
                    "unknown",
                    status_text=status_text,
                    log_message=self.tr(
                        "dns_guard_log_target_unclear",
                        "DNS Guard: DNS-Ziel unklar",
                    ),
                )
                return

            if self.dns_is_clean(current, allowed):
                if self.is_vpn_active():
                    status_text = self.tr(
                        "dns_guard_status_vpn_dns_ok", "aktiv / VPN-DNS OK"
                    )
                elif self.is_dot_active():
                    status_text = self.tr(
                        "dns_guard_status_dot_resolver_ok",
                        "aktiv (DoT-Resolver OK)",
                    )
                else:
                    status_text = self.tr("dns_guard_status_ok_clean", "aktiv / sauber")
                self.set_dns_guard_state(
                    "ok",
                    status_text=status_text,
                    log_message=self.tr("dns_guard_log_ok", "DNS Guard: OK"),
                )
                return

            if self.is_dot_active() and not self.is_vpn_active():
                problem_text = self.tr(
                    "dns_guard_status_problem_dot_mismatch",
                    "Problem (DoT-DNS abweichend)",
                )
            else:
                problem_text = self.tr("dns_guard_status_problem", "Problem erkannt")
            self.set_dns_guard_state(
                "problem",
                status_text=problem_text,
                log_message=self.tr(
                    "dns_guard_log_problem_detected",
                    "DNS Guard: Abweichung erkannt",
                ),
            )
            if not auto_repair:
                return

            repair_last = float(self.__dict__.get("last_dns_guard_repair_ts", 0.0))
            if (now - repair_last) < 30:
                return

            success, text = self.enforce_dns_clean()
            self.last_dns_guard_repair_ts = time.time()
            self.dns_guard_last_fix_ts = self.last_dns_guard_repair_ts
            ts_text = datetime.fromtimestamp(self.last_dns_guard_repair_ts).strftime(
                "%Y-%m-%d %H:%M:%S"
            )
            self.update_dns_output(text, append=True)
            self.set_dns_guard_state(
                "ok" if success else "problem",
                status_text=(
                    self.tr("dns_guard_status_corrected", "aktiv / korrigiert")
                    if success
                    else self.tr("dns_guard_status_problem", "Problem erkannt")
                ),
                last_action=self.tr(
                    "dns_guard_last_action_value",
                    "Letzte Korrektur: {timestamp}",
                ).format(timestamp=ts_text),
                log_message=(
                    self.tr(
                        "dns_guard_log_autorepair_success",
                        "DNS Guard: Inkonsistenz erkannt → Auto-Korrektur",
                    )
                    if success
                    else self.tr(
                        "dns_guard_log_autorepair_failed",
                        "DNS Guard: Auto-Korrektur fehlgeschlagen",
                    )
                ),
            )
            self.rebuild_dns_guard_whitelist()
        except Exception as exc:
            self.set_dns_guard_state(
                "error",
                last_action=self.dns_guard_last_action_var.get(),
                log_message=self.tr(
                    "dns_guard_log_error_detected",
                    "DNS Guard: Fehler erkannt",
                ),
            )
            self.log_debug_safe(f"DNS Guard Fehler: {exc}")
        finally:
            self.dns_guard_check_running = False

    def enforce_dns_clean(self):
        if not self._auto_dns_control_available():
            return (
                False,
                self.tr(
                    "dns_guard_result_skipped_no_sudo",
                    "=== DNS Guard ===\nStatus: Korrektur übersprungen\nGrund: sudo -n ist nicht verfügbar.",
                ),
            )

        if self.is_vpn_active():
            return self.use_vpn_dns()

        selected = self.get_selected_user_dns()
        if selected:
            choice = self._manual_dns_choice()
            ok = self.apply_dns(
                choice=choice,
                refresh_ui=False,
                update_choice_var=False,
                confirm_dnssec=False,
            )
            return (
                ok,
                self.tr(
                    "dns_guard_result_user_dns",
                    "=== DNS Guard ===\nAktion: User DNS erzwingen\nProfil: {profile}\nErgebnis: {result}",
                ).format(
                    profile=choice,
                    result=(
                        self.tr("result_success", "erfolgreich")
                        if ok
                        else self.tr("result_failed", "fehlgeschlagen")
                    ),
                ),
            )

        return (
            True,
            self.tr(
                "dns_guard_result_no_correction_needed",
                "=== DNS Guard ===\nStatus: Keine Korrektur nötig\nGrund: Kein manuelles DNS-Profil aktiv.",
            ),
        )

    def _auto_dns_control_available(self):
        return has_cmd("sudo") and check_sudo_nopasswd()

    def _show_auto_dns_policy_result(self, title: str, text: str):
        self.update_dns_output(text, append=True)
        self.refresh_dns_policy_status()
        self.update_dns_controls_state()
        self.log_safe(title)

    def initial_dns_cleanup(self, defer_followup=False):
        if not self._auto_dns_control_available():
            self.log_safe(
                self.tr(
                    "dns_startup_cleanup_skipped_no_sudo",
                    "DNS-Startbereinigung übersprungen: sudo -n nicht verfügbar",
                )
            )
            if not defer_followup:
                self.rebuild_dns_guard_whitelist()
                self.run_dns_guard_check_once()
                self.update_dns_controls_state_safe()
            return
        rc, out = run_cmd(
            ["sudo", "-n", "systemctl", "restart", "systemd-resolved"],
            timeout=15,
        )
        if rc == 0:
            self.log_safe(
                self.tr(
                    "dns_startup_cleanup_resolved_restarted",
                    "DNS-Startbereinigung: systemd-resolved neu gestartet",
                )
            )
        else:
            self.log_safe(
                self.tr(
                    "dns_startup_cleanup_failed",
                    "DNS-Startbereinigung fehlgeschlagen",
                )
            )
            if out:
                self.log_debug_safe(out)
        if defer_followup:
            return
        self.rebuild_dns_guard_whitelist()
        self.run_dns_guard_check_once()
        self.update_dns_controls_state_safe()

    def _dns_startup_transition_active(self):
        return bool(self.__dict__.get("dns_startup_sequence_running", False))

    def _dns_runtime_transition_active(self):
        if self._dns_startup_transition_active():
            return True
        if time.time() < float(self.__dict__.get("dns_guard_transition_until", 0.0)):
            return True
        if bool(self.__dict__.get("dns_policy_running", False)):
            return True
        if bool(self.__dict__.get("dot_running", False)):
            return True
        active_operation = str(self.__dict__.get("network_active_operation") or "")
        active_operation = active_operation.strip().lower()
        return bool(
            active_operation
            and any(token in active_operation for token in ("vpn", "dns"))
        )

    def _schedule_dns_startup_step(self, delay_ms, callback):
        after = getattr(self, "after", None)
        if callable(after):
            try:
                after(delay_ms, callback)
                return
            except Exception:
                pass
        try:
            callback()
        except Exception:
            pass

    def _start_dns_startup_transition(self, duration_ms=4200):
        self.__dict__["dns_startup_sequence_running"] = True
        self.dns_guard_transition_until = time.time() + max(1.0, duration_ms / 1000.0)
        self.set_dns_guard_state(
            "transition",
            log_message=self.tr(
                "dns_startup_sequence_initializing",
                "DNS-Startsequenz: Initialisierung läuft",
            ),
        )
        try:
            self.update_dns_controls_state()
        except Exception:
            pass

    def _run_dns_startup_cleanup_step(self):
        try:
            self.initial_dns_cleanup(defer_followup=True)
        except Exception as exc:
            self.log_debug_safe(f"DNS-Startsequenz Cleanup Fehler: {exc}")
        try:
            self._restore_isp_dns_on_startup_if_needed()
        except Exception as exc:
            self.log_debug_safe(f"DNS-Startsequenz Fallback Fehler: {exc}")

    def _run_dns_startup_dot_step(self):
        try:
            self.startup_dot_status_check()
        except Exception as exc:
            self.log_debug_safe(f"DNS-Startsequenz DoT Fehler: {exc}")

    def _run_dns_startup_policy_step(self):
        try:
            self.startup_dns_policy_check()
        except Exception as exc:
            self.log_debug_safe(f"DNS-Startsequenz Policy Fehler: {exc}")

    def _finalize_dns_startup_sequence(self):
        self.__dict__["dns_startup_sequence_running"] = False
        self.dns_guard_transition_until = 0.0
        try:
            self.refresh_dns_policy_status()
        except Exception:
            pass
        try:
            self.update_dns_controls_state()
        except Exception:
            pass
        try:
            self.rebuild_dns_guard_whitelist()
        except Exception:
            pass
        try:
            self.run_dns_guard_check_once()
        except Exception:
            pass
        try:
            self.update_dns_guard_indicator()
        except Exception:
            pass

    def start_dns_startup_sequence(self):
        if self.__dict__.get("dns_startup_sequence_running", False):
            return
        self._start_dns_startup_transition(duration_ms=4200)
        self._schedule_dns_startup_step(0, self._run_dns_startup_cleanup_step)
        self._schedule_dns_startup_step(700, self._run_dns_startup_dot_step)
        self._schedule_dns_startup_step(1500, self._run_dns_startup_policy_step)
        self._schedule_dns_startup_step(2400, self._finalize_dns_startup_sequence)
        self._schedule_dns_startup_step(2600, self.dns_guard_ui_loop)
        self._schedule_dns_startup_step(3200, self.monitor_vpn_changes)
        self._schedule_dns_startup_step(3800, self.dns_guard_loop)

    def on_vpn_state_changed(self, vpn_active: bool):
        self.dns_guard_transition_until = time.time() + 5
        self.set_dns_guard_state(
            "transition",
            log_message=self.tr(
                "dns_vpn_state_changed",
                "VPN-Wechsel erkannt: {state}",
            ).format(
                state=(
                    self.tr("status_active", "active")
                    if vpn_active
                    else self.tr("status_inactive", "inactive")
                )
            ),
        )
        try:
            self.update_dns_controls_state()
        except Exception:
            pass
        self._schedule_dns_finalize_after_vpn_profile_switch(delay_ms=2500)

    def on_vpn_connected(self):
        self.log_safe(
            self.tr("dns_vpn_connected_cleanup", "VPN erkannt -> DNS wird bereinigt")
        )
        if not self._auto_dns_control_available():
            result = self.tr(
                "dns_vpn_connected_skipped_no_sudo",
                "=== DNS Control ===\nAktion: VPN verbunden\nStatus: automatische DNS-Bereinigung übersprungen\nGrund: sudo -n ist nicht verfügbar.",
            )
            self._show_auto_dns_policy_result(
                self.tr(
                    "dns_vpn_connected_cleanup_skipped",
                    "VPN detected -> DNS cleanup skipped",
                ),
                result,
            )
            return

        def worker():
            success, text = self.use_vpn_dns()

            def finish():
                self._show_auto_dns_policy_result(
                    (
                        self.tr(
                            "dns_vpn_connected_switched",
                            "DNS switched to VPN DNS",
                        )
                        if success
                        else self.tr(
                            "dns_vpn_connected_cleanup_failed",
                            "DNS cleanup while on VPN failed",
                        )
                    ),
                    text,
                )

            self.after(0, finish)

        threading.Thread(target=worker, daemon=True).start()

    def on_vpn_disconnected(self):
        self.log_safe(
            self.tr(
                "dns_vpn_disconnected_reset",
                "VPN disconnected -> resetting DNS",
            )
        )
        if not self._auto_dns_control_available():
            result = self.tr(
                "dns_vpn_disconnected_skipped_no_sudo",
                "=== DNS Control ===\nAction: VPN disconnected\nStatus: DNS reset skipped\nReason: sudo -n is not available.",
            )
            self._show_auto_dns_policy_result(
                self.tr(
                    "dns_vpn_disconnected_reset_skipped",
                    "VPN disconnected -> DNS reset skipped",
                ),
                result,
            )
            return

        service = self._dns_control_service()

        def worker():
            if service is None:
                success = False
                text = self.tr(
                    "dns_vpn_disconnected_service_missing",
                    "=== DNS Control ===\nAction: VPN disconnected\nStatus: failed\nReason: DNS control service unavailable.",
                )
            else:
                nm_ok, nm_details = service.apply_nm_dns_policy_to_targets(
                    ignore_auto_dns=False,
                    targets=self._active_nm_dns_targets(),
                )
                rm_ok, rm_detail = service.remove_dropin()
                restart_ok, restart_detail = service.restart_resolved()
                success = nm_ok and rm_ok and restart_ok
                lines = [
                    self.tr("dns_control_report_title", "=== DNS Control ==="),
                    self.tr(
                        "dns_vpn_disconnected_action",
                        "Action: VPN disconnected / DNS back to default",
                    ),
                    self.tr("result_label", "Result: {result}").format(
                        result=(
                            self.tr("result_success", "successful")
                            if success
                            else self.tr("result_failed", "failed")
                        )
                    ),
                    "",
                    "[System]",
                    (
                        self.tr(
                            "dns_vpn_disconnected_dot_removed",
                            "✔ NetMon DoT-Konfiguration entfernt",
                        )
                        if rm_ok
                        else self.tr(
                            "dns_vpn_disconnected_dot_remove_failed",
                            "✖ Fehler beim Entfernen der NetMon DoT-Konfiguration: {detail}",
                        ).format(
                            detail=rm_detail or self.tr("value_unknown", "unknown")
                        )
                    ),
                    (
                        self.tr(
                            "dns_vpn_disconnected_resolved_restarted",
                            "✔ systemd-resolved neu gestartet",
                        )
                        if restart_ok
                        else self.tr(
                            "dns_vpn_disconnected_resolved_restart_failed",
                            "✖ Fehler beim Neustarten von systemd-resolved: {detail}",
                        ).format(
                            detail=restart_detail
                            or self.tr("result_failed", "fehlgeschlagen")
                        )
                    ),
                    "",
                    "[NetworkManager]",
                    *nm_details,
                ]
                text = "\n".join(lines).strip()

            def finish():
                self._show_auto_dns_policy_result(
                    (
                        self.tr(
                            "dns_vpn_disconnected_reset_done",
                            "DNS zurück auf Standard",
                        )
                        if success
                        else self.tr(
                            "dns_vpn_disconnected_reset_failed",
                            "DNS reset after VPN disconnect failed",
                        )
                    ),
                    text,
                )

            self.after(0, finish)

        threading.Thread(target=worker, daemon=True).start()

    def monitor_vpn_changes(self):
        try:
            if self._dns_runtime_transition_active():
                self.update_dns_controls_state()
                return
            current = bool(self.get_vpn_state())
            if current != bool(self.last_vpn_state):
                self.on_vpn_state_changed(current)
                self.last_vpn_state = current
            self.update_dns_controls_state()
        except Exception as exc:
            self.log_debug_safe(f"VPN-State-Monitor Fehler: {exc}")
        finally:
            self.after(3000, self.monitor_vpn_changes)

    def dns_guard_loop(self):
        try:
            if self._dns_runtime_transition_active():
                self.set_dns_guard_state("transition")
                return
            self.run_dns_guard_check_once(auto_repair=True)
        except Exception as exc:
            self.log_debug_safe(f"DNS Guard Fehler: {exc}")
            self.set_dns_guard_state("error")
        finally:
            self.after(5000, self.dns_guard_loop)

    def _async_job_label(self, func, job_name=""):
        explicit = str(job_name or "").strip()
        if explicit:
            return explicit
        inferred = str(getattr(func, "__name__", "") or "").strip()
        if inferred and inferred != "<lambda>":
            return inferred
        return "unbenannter Async-Job"

    def _log_async_job_error(self, func, exc, job_name=""):
        debug_logger = self.__dict__.get("log_debug_safe")
        plain_logger = self.__dict__.get("log")
        label = self._async_job_label(func, job_name=job_name)
        message = f"Async-Job Fehler [{label}]: {exc}"
        try:
            if callable(debug_logger):
                debug_logger(message)
            elif callable(plain_logger):
                plain_logger(message)
        except Exception:
            pass
        if callable(debug_logger):
            try:
                debug_logger(traceback.format_exc())
            except Exception:
                pass

    def run_async(self, func, job_name=""):
        def runner():
            try:
                func()
            except Exception as exc:
                self._log_async_job_error(func, exc, job_name=job_name)

        threading.Thread(target=runner, daemon=True).start()

    def _sync_network_operation_state_from_coordinator(self):
        coordinator = self.__dict__.get("network_ops_coordinator")
        if coordinator is None:
            return
        self.network_ops_lock = coordinator.lock
        self.network_active_operation = coordinator.active_operation
        self._network_op_owner = coordinator.owner_thread_id
        self._network_op_depth = coordinator.depth

    def _network_service(self):
        service = self.__dict__.get("network_service")
        if service is not None:
            return service
        if NetmonNetworkService is None:
            return None
        service = NetmonNetworkService(run_cmd)
        self.network_service = service
        return service

    def _state_coordinator(self):
        coordinator = self.__dict__.get("state_coordinator")
        if coordinator is not None:
            return coordinator
        if NetmonStateCoordinator is None:
            return None
        coordinator = NetmonStateCoordinator()
        self.state_coordinator = coordinator
        return coordinator

    def _dns_control_service(self):
        service = self.__dict__.get("dns_control_service")
        if service is not None:
            return service
        if DNSControlService is None:
            return None
        service = DNSControlService(
            run_cmd,
            has_cmd,
            dot_dropin_path=DOT_DROPIN_PATH,
            dot_dropin_dir=DOT_DROPIN_DIR,
        )
        self.dns_control_service = service
        return service

    def _new_rollback_transaction(self, name):
        if RollbackTransaction is None:
            return None
        return RollbackTransaction(
            name,
            log_fn=self.log_safe,
            log_debug_fn=self.log_debug_safe,
        )

    def _security_parser(self):
        parser = self.__dict__.get("security_parser")
        if parser is not None:
            return parser

        parser_cls = NetmonSecurityParser
        if parser_cls is None:
            if self.__dict__.get("_security_parser_load_failed"):
                return None
            module_path = os.path.join(
                os.path.dirname(__file__), "netmon_security_parser.py"
            )
            try:
                spec = importlib.util.spec_from_file_location(
                    "netmon_security_parser_dynamic", module_path
                )
                if spec and spec.loader:
                    mod = importlib.util.module_from_spec(spec)
                    spec.loader.exec_module(mod)
                    parser_cls = getattr(mod, "NetmonSecurityParser", None)
            except Exception as exc:
                parser_cls = None
                self.log_debug(f"Security parser dynamisch laden fehlgeschlagen: {exc}")
            if parser_cls is None:
                self._security_parser_load_failed = True
                return None

        try:
            parser = parser_cls()
        except Exception as exc:
            self.log_debug(f"Security parser Initialisierung fehlgeschlagen: {exc}")
            self._security_parser_load_failed = True
            return None
        self.security_parser = parser
        return parser

    def _security_store(self):
        store = self.__dict__.get("security_store")
        if store is not None:
            return store
        if NetmonSecurityStore is None:
            return None
        store = NetmonSecurityStore()
        self.security_store = store
        return store

    def _try_begin_network_operation(self, operation, log_busy=True):
        coordinator = self.__dict__.get("network_ops_coordinator")
        if coordinator is not None:
            started = coordinator.try_begin(operation, log_busy=log_busy)
            self._sync_network_operation_state_from_coordinator()
            return started

        lock = self.__dict__.get("network_ops_lock")
        if lock is None:
            lock = threading.RLock()
            self.network_ops_lock = lock
        current_tid = threading.get_ident()
        owner = self.__dict__.get("_network_op_owner")
        depth = self.__dict__.get("_network_op_depth", 0)

        if owner == current_tid:
            lock.acquire()
            self._network_op_depth = depth + 1
            return True

        if not lock.acquire(blocking=False):
            if log_busy:
                active = (
                    self.__dict__.get("network_active_operation")
                    or "andere Netzwerkaktion"
                ).strip()
                self.log_safe(
                    f"Netzwerkaktion blockiert: {operation} wird nicht gestartet, da bereits '{active}' läuft."
                )
            return False

        self._network_op_owner = current_tid
        self._network_op_depth = 1
        self.network_active_operation = operation
        return True

    def _network_operation_active_elsewhere(self):
        active_operation = str(self.__dict__.get("network_active_operation") or "")
        if not active_operation.strip():
            return False

        coordinator = self.__dict__.get("network_ops_coordinator")
        if coordinator is not None:
            owner = getattr(coordinator, "owner_thread_id", None)
        else:
            owner = self.__dict__.get("_network_op_owner")
        return owner != threading.get_ident()

    def _end_network_operation(self):
        coordinator = self.__dict__.get("network_ops_coordinator")
        if coordinator is not None:
            coordinator.end()
            self._sync_network_operation_state_from_coordinator()
            return

        lock = self.__dict__.get("network_ops_lock")
        if lock is None:
            return
        current_tid = threading.get_ident()
        owner = self.__dict__.get("_network_op_owner")
        if owner != current_tid:
            return

        depth = max(0, int(self.__dict__.get("_network_op_depth", 1)) - 1)
        self._network_op_depth = depth
        if depth == 0:
            self._network_op_owner = None
            self.network_active_operation = ""
        lock.release()

    def _refresh_security_table_safe(self):
        if threading.current_thread() is threading.main_thread():
            self._refresh_security_table()
            return
        self.after(0, self._refresh_security_table)

    def clear_log(self):
        try:
            self.text.delete("1.0", "end")
        except Exception:
            pass
        try:
            self._clear_runtime_log_file()
        except Exception:
            pass

    def copy_log_selection(self, _event=None):
        try:
            selected = self.text.get("sel.first", "sel.last")
        except tk.TclError:
            return "break"
        self.clipboard_clear()
        self.clipboard_append(selected)
        return "break"

    def prepare_log_selection_chad_analysis(self):
        try:
            selected = self.text.get("sel.first", "sel.last").strip()
        except tk.TclError:
            self.chad_analysis_status_var.set(
                self.tr(
                    "chad_status_select_log_text_first",
                    "Bitte zuerst Text im Log markieren.",
                )
            )
            return
        if not selected:
            self.chad_analysis_status_var.set(
                self.tr(
                    "chad_status_select_log_text_first",
                    "Bitte zuerst Text im Log markieren.",
                )
            )
            return
        self.prepare_chad_analysis("Log Analyse", selected)

    def _persist_log_overlay_preferences(self):
        if "privacy_config" not in self.__dict__:
            return
        try:
            self.save_privacy_config()
        except Exception:
            pass

    def _default_log_overlay_dir(self):
        log_pics_dir = get_netmon_documents_subdir("Log-Pics")
        try:
            os.makedirs(log_pics_dir, exist_ok=True)
        except Exception:
            pass
        if os.path.isdir(log_pics_dir):
            return log_pics_dir
        netmon_docs_dir = get_netmon_documents_dir()
        if os.path.isdir(netmon_docs_dir):
            return netmon_docs_dir
        return os.path.expanduser("~")

    def _default_log_overlay_image_path(self):
        candidate_dirs = [
            self._default_log_overlay_dir(),
            "/usr/share/netmon/assets/log-pics",
            "/opt/netmon/assets/log-pics",
            "/opt/netmon-dark/assets/log-pics",
            os.path.join(NETMON_REPO_ROOT, "tools", "Log-Pics"),
        ]
        seen = set()
        for folder in candidate_dirs:
            folder = str(folder or "").strip()
            if not folder or folder in seen:
                continue
            seen.add(folder)
            for filename in ("Netmon.png", "netmon.png"):
                candidate = os.path.join(folder, filename)
                if os.path.isfile(candidate):
                    return candidate
        return ""

    def _preferred_log_overlay_dir(self):
        picker_dir = str(self.__dict__.get("log_overlay_picker_dir") or "").strip()
        if picker_dir and os.path.isdir(picker_dir):
            return picker_dir

        config = getattr(self, "privacy_config", {})
        if isinstance(config, dict):
            saved = str(config.get("log_overlay_last_dir") or "").strip()
            if saved and os.path.isdir(saved):
                self.log_overlay_picker_dir = saved
                return saved

        default_dir = self._default_log_overlay_dir()
        self.log_overlay_picker_dir = default_dir
        return default_dir

    def _list_overlay_images(self, folder):
        folder_path = os.path.abspath(os.path.expanduser(folder or "")).strip()
        if not folder_path or not os.path.isdir(folder_path):
            return []
        exts = {".png", ".jpg", ".jpeg", ".PNG", ".JPG", ".JPEG"}
        files = []
        try:
            for name in sorted(os.listdir(folder_path)):
                full = os.path.join(folder_path, name)
                if not os.path.isfile(full):
                    continue
                _, ext = os.path.splitext(name)
                if ext in exts:
                    files.append(full)
        except Exception:
            return []
        return files

    def open_log_overlay_picker(self, folder=""):
        picker = self.__dict__.get("log_overlay_picker_frame")
        if picker is None:
            return False

        target_folder = (folder or self.log_overlay_picker_dir or "").strip()
        if not target_folder:
            current_path = str(self.log_overlay_image_path or "").strip()
            if current_path:
                target_folder = os.path.dirname(current_path)

        if not target_folder:
            target_folder = self._preferred_log_overlay_dir()

        target_folder = os.path.abspath(os.path.expanduser(target_folder))
        files = self._list_overlay_images(target_folder)
        if not files:
            self.log_safe("Keine Bilddateien (PNG/JPG) im gewählten Ordner gefunden.")
            return False

        self.log_overlay_picker_open = True
        self.log_overlay_picker_dir = target_folder
        self.log_overlay_picker_files = files

        self.log_overlay_picker_list.delete(0, "end")
        for img_path in files:
            self.log_overlay_picker_list.insert("end", os.path.basename(img_path))

        selected_path = str(self.log_overlay_image_path or "").strip()
        idx = 0
        if selected_path and selected_path in files:
            idx = files.index(selected_path)

        self.log_overlay_picker_index = idx
        self.log_overlay_picker_list.selection_clear(0, "end")
        self.log_overlay_picker_list.selection_set(idx)
        self.log_overlay_picker_list.activate(idx)
        self.log_overlay_picker_list.see(idx)

        picker.place(relx=1.0, rely=0.0, x=-10, y=10, anchor="ne")
        picker.lift()
        self._apply_log_overlay_picker_index(idx)
        return True

    def close_log_overlay_picker(self):
        picker = self.__dict__.get("log_overlay_picker_frame")
        if picker is not None:
            picker.place_forget()
        self.log_overlay_picker_open = False

    def _choose_log_overlay_folder(self):
        initial_dir = self._preferred_log_overlay_dir()
        folder = filedialog.askdirectory(
            title=self.tr(
                "log_overlay_folder_dialog_title",
                "Ordner mit Overlay-Bildern wählen",
            ),
            initialdir=initial_dir,
        )
        if not folder:
            return
        if self.open_log_overlay_picker(folder):
            self.log_safe(f"Overlay-Bilder geladen: {folder}")

    def _apply_log_overlay_picker_index(self, idx):
        files = list(self.log_overlay_picker_files or [])
        if not files:
            return False
        if idx < 0 or idx >= len(files):
            return False

        target = files[idx]
        ok = self._load_log_overlay_image(target)
        if not ok:
            return False

        self.log_overlay_picker_index = idx
        self._render_log_overlay_image()
        self._set_log_overlay_visible(True)
        return True

    def _step_log_overlay_selection(self, step):
        files = list(self.log_overlay_picker_files or [])
        if not files:
            return
        current = int(self.log_overlay_picker_index)
        if current < 0:
            current = 0
        nxt = (current + int(step)) % len(files)
        self.log_overlay_picker_list.selection_clear(0, "end")
        self.log_overlay_picker_list.selection_set(nxt)
        self.log_overlay_picker_list.activate(nxt)
        self.log_overlay_picker_list.see(nxt)
        self._apply_log_overlay_picker_index(nxt)

    def _on_log_overlay_picker_select(self, _event=None):
        selection = self.log_overlay_picker_list.curselection()
        if not selection:
            return
        idx = int(selection[0])
        self._apply_log_overlay_picker_index(idx)

    def _format_log_overlay_image_name(self, image_path):
        base = os.path.basename(str(image_path or "").strip())
        if not base:
            return ""
        stem, _ext = os.path.splitext(base)
        title = (stem or base).replace("_", " ").strip()
        return title or base

    def _update_log_overlay_title(self):
        badge = self.__dict__.get("log_overlay_name_badge")
        text_var = self.__dict__.get("log_overlay_name_var")
        if badge is None or text_var is None:
            return

        if not self.log_overlay_active:
            badge.place_forget()
            text_var.set("")
            return

        title = self._format_log_overlay_image_name(self.log_overlay_image_path)
        if not title:
            badge.place_forget()
            text_var.set("")
            return

        text_var.set(title)
        badge.place(relx=0.5, rely=0.0, y=12, anchor="n")
        badge.lift()

    def _restore_log_overlay_from_config(self):
        self.close_log_overlay_picker()
        config = getattr(self, "privacy_config", {})
        if not isinstance(config, dict):
            self._set_log_overlay_visible(False, persist=False)
            return

        image_path = str(config.get("log_overlay_image_path") or "").strip()
        if not image_path:
            image_path = self._default_log_overlay_image_path()
        active = bool(config.get("log_overlay_active", False))
        last_dir = str(config.get("log_overlay_last_dir") or "").strip()

        if last_dir and os.path.isdir(last_dir):
            self.log_overlay_picker_dir = last_dir
        elif image_path:
            guessed = os.path.dirname(image_path)
            if guessed and os.path.isdir(guessed):
                self.log_overlay_picker_dir = guessed
            else:
                self.log_overlay_picker_dir = self._default_log_overlay_dir()
        else:
            self.log_overlay_picker_dir = self._default_log_overlay_dir()

        loaded = False
        if image_path:
            loaded = self._load_log_overlay_image(image_path)
            if loaded:
                self._render_log_overlay_image()

        self._set_log_overlay_visible(active and loaded, persist=False)

    def _set_log_overlay_visible(self, visible, persist=True):
        self.log_overlay_active = bool(visible)
        if not hasattr(self, "log_overlay_frame"):
            return

        if self.log_overlay_active:
            self.log_overlay_frame.place(
                relx=0.0, rely=0.0, relwidth=1.0, relheight=1.0
            )
            self.log_overlay_frame.lift()
            if hasattr(self, "log_overlay_controls"):
                self.log_overlay_controls.lift()
            if self.log_overlay_picker_open and hasattr(
                self, "log_overlay_picker_frame"
            ):
                self.log_overlay_picker_frame.lift()
            if hasattr(self, "log_overlay_toggle_text"):
                self.log_overlay_toggle_text.set(
                    self.tr("log_overlay_button_log", "Log")
                )
        else:
            self.log_overlay_frame.place_forget()
            if hasattr(self, "log_overlay_toggle_text"):
                self.log_overlay_toggle_text.set(
                    self.tr("log_overlay_button_image", "Bild")
                )

        self._update_log_overlay_title()

        if persist:
            self._persist_log_overlay_preferences()

    def _on_log_overlay_resize(self, _event=None):
        if self.log_overlay_active:
            self._render_log_overlay_image()

    def _log_overlay_max_source_size(self):
        fallback_w, fallback_h = 1920, 1080
        frame = self.__dict__.get("log_view_frame")
        if frame is None:
            return fallback_w, fallback_h

        width = int(frame.winfo_width() or 0)
        height = int(frame.winfo_height() or 0)
        if width <= 1 or height <= 1:
            return fallback_w, fallback_h

        max_w = max(640, min(width * 2, 3840))
        max_h = max(360, min(height * 2, 2160))
        return max_w, max_h

    def _load_log_overlay_image(self, path):
        image_path = os.path.abspath(os.path.expanduser(path or "")).strip()
        if not image_path:
            return False
        if not os.path.isfile(image_path):
            self.log_safe("Log-Bild nicht gefunden.")
            return False

        self.log_overlay_source_image = None
        self.log_overlay_source_photo = None
        self.log_overlay_photo = None

        if Image is not None and ImageTk is not None:
            try:
                max_w, max_h = self._log_overlay_max_source_size()
                with warnings.catch_warnings():
                    bomb_warning = getattr(Image, "DecompressionBombWarning", None)
                    if bomb_warning is not None:
                        warnings.simplefilter("error", bomb_warning)
                    img = Image.open(image_path)
                    img.load()

                if img.mode != "RGB":
                    img = img.convert("RGB")

                if img.width > max_w or img.height > max_h:
                    if hasattr(Image, "Resampling"):
                        img.thumbnail((max_w, max_h), Image.Resampling.LANCZOS)
                    else:
                        img.thumbnail((max_w, max_h), Image.LANCZOS)

                self.log_overlay_source_image = img
                self.log_overlay_image_path = image_path
                self.log_overlay_picker_dir = os.path.dirname(image_path)
                self._persist_log_overlay_preferences()
                return True
            except Exception as exc:
                bomb_warning = getattr(Image, "DecompressionBombWarning", None)
                if bomb_warning is not None and isinstance(exc, bomb_warning):
                    self.log_safe(
                        "Log-Bild abgelehnt: extrem große Bilddatei (Pillow-Schutz aktiv)."
                    )
                else:
                    self.log_safe(f"Log-Bild konnte nicht geladen werden: {exc}")
                return False

        try:
            self.log_overlay_source_photo = tk.PhotoImage(file=image_path)
            self.log_overlay_image_path = image_path
            self.log_overlay_picker_dir = os.path.dirname(image_path)
            self._persist_log_overlay_preferences()
            return True
        except Exception:
            detail = (PIL_IMPORT_ERROR or "").strip()
            if detail:
                self.log_safe(
                    "Bildformat nicht unterstützt. Pillow ist nicht nutzbar: " + detail
                )
            else:
                self.log_safe(
                    "Bildformat nicht unterstützt. Für JPG-Skalierung bitte Pillow und ImageTk installieren (python3-pil python3-pil.imagetk)."
                )
            return False

    def _render_log_overlay_image(self):
        if not hasattr(self, "log_overlay_label"):
            return

        if (
            self.log_overlay_source_image is None
            and self.log_overlay_source_photo is None
        ):
            self.log_overlay_label.configure(
                image="",
                text=self.tr("log_overlay_no_image_loaded", "No image loaded."),
                fg="#f0f0f0",
            )
            self.log_overlay_photo = None
            return

        if (
            self.log_overlay_source_image is not None
            and Image is not None
            and ImageTk is not None
        ):
            width = max(1, int(self.log_view_frame.winfo_width()))
            height = max(1, int(self.log_view_frame.winfo_height()))
            if width <= 1 or height <= 1:
                return

            src = self.log_overlay_source_image
            src_w, src_h = src.size
            if src_w <= 0 or src_h <= 0:
                self.log_overlay_label.configure(
                    image="",
                    text=self.tr("log_overlay_invalid_image", "Bild ungültig."),
                    fg="#f0f0f0",
                )
                self.log_overlay_photo = None
                return

            # cover: Bereich vollständig füllen, Seitenverhältnis erhalten,
            # bei Bedarf zentriert beschneiden.
            scale = max(width / src_w, height / src_h)
            new_w = max(1, int(round(src_w * scale)))
            new_h = max(1, int(round(src_h * scale)))

            if hasattr(Image, "Resampling"):
                resized = src.resize((new_w, new_h), Image.Resampling.LANCZOS)
            else:
                resized = src.resize((new_w, new_h), Image.LANCZOS)

            if resized.mode != "RGB":
                resized = resized.convert("RGB")

            left = max(0, (new_w - width) // 2)
            top = max(0, (new_h - height) // 2)
            right = left + width
            bottom = top + height
            cover_img = resized.crop((left, top, right, bottom))

            self.log_overlay_photo = ImageTk.PhotoImage(cover_img)
            self.log_overlay_label.configure(image=self.log_overlay_photo, text="")
            return

        if self.log_overlay_source_photo is not None:
            self.log_overlay_photo = self.log_overlay_source_photo
            self.log_overlay_label.configure(image=self.log_overlay_photo, text="")
            return

    def choose_log_overlay_image(self):
        folder = self.log_overlay_picker_dir
        if not folder:
            current_path = str(self.log_overlay_image_path or "").strip()
            if current_path:
                folder = os.path.dirname(current_path)
        if not folder or not os.path.isdir(folder):
            folder = self._preferred_log_overlay_dir()

        if self.open_log_overlay_picker(folder):
            self.log_safe("Bildauswahl geöffnet (mit 'Auswahl schließen' beenden).")

    def toggle_log_overlay(self):
        if not self.log_overlay_active:
            if not (
                self.log_overlay_source_image is not None
                or self.log_overlay_source_photo is not None
            ):
                self.choose_log_overlay_image()
                return
            self._render_log_overlay_image()
            self._set_log_overlay_visible(True)
            if self.log_overlay_picker_open and hasattr(
                self, "log_overlay_picker_frame"
            ):
                self.log_overlay_picker_frame.lift()
            self.log_safe("Log-Overlay aktiviert.")
            return

        self._set_log_overlay_visible(False)
        self.log_safe("Log-Overlay deaktiviert.")

    def tr(self, key: str, default: str | None = None) -> str:
        lang = self.__dict__.get("lang")
        if isinstance(lang, dict):
            value = lang.get(key)
            if isinstance(value, str) and value:
                return value
        if default is not None:
            return default
        return key

    def tooltip_lang_key(self, text: str) -> str:
        raw = str(text or "").strip()
        digest = hashlib.sha1(raw.encode("utf-8")).hexdigest()[:12]
        return f"tooltip_auto_{digest}"

    def _translate_tooltip_text(self, text_or_key: str) -> str:
        raw = str(text_or_key or "").strip()
        if not raw:
            return ""

        lang = self.__dict__.get("lang")
        if isinstance(lang, dict):
            value = lang.get(raw)
            if isinstance(value, str) and value:
                return value

            tooltips = lang.get("tooltips")
            if isinstance(tooltips, dict):
                value = tooltips.get(self.tooltip_lang_key(raw))
                if isinstance(value, str) and value:
                    return value

            tooltip_map = lang.get("tooltips_by_source")
            if isinstance(tooltip_map, dict):
                value = tooltip_map.get(raw)
                if isinstance(value, str) and value:
                    return value

        return raw

    def add_tooltip(self, widget, text):
        translated = self._translate_tooltip_text(text)
        tip = SimpleTooltip(widget, translated, self.tooltips_enabled)
        tip._netmon_tooltip_source = text
        self._tooltips.append(tip)

    def refresh_tooltip_translations(self):
        for tip in list(self.__dict__.get("_tooltips", []) or []):
            try:
                source = getattr(tip, "_netmon_tooltip_source", "")
                tip.text = self._translate_tooltip_text(source)
                tip._hide()
            except Exception:
                continue
        self._hide_notebook_tab_tooltip()

    def refresh_runtime_language_state(self):
        self.refresh_tooltip_translations()

        try:
            self._refresh_text_widget_placeholders_for_language()
        except Exception:
            pass

        try:
            self._refresh_dns_runtime_language_state()
        except Exception:
            pass

        try:
            self.refresh_guided_tour_status()
        except Exception:
            pass

        try:
            self.update_vpn_status_text()
        except Exception:
            pass

        try:
            self.update_dns_header()
        except Exception:
            pass

        try:
            self._sync_dns_protocol_profile_labels()
        except Exception:
            pass

        try:
            self.connections_summary_var.set(
                self.summarize_connections_rows(
                    getattr(self, "_conn_rows_cache", []) or []
                )
            )
        except Exception:
            pass

        try:
            self.route_status_var.set(
                self.tr(
                    "connections_route_status_count",
                    "Routing: {count} Einträge",
                ).format(count=len(getattr(self, "_route_rows_cache", []) or []))
            )
        except Exception:
            pass

        try:
            self.arp_status_var.set(
                self.tr("connections_arp_status_count", "ARP: {count} Einträge").format(
                    count=len(getattr(self, "_arp_rows_cache", []) or [])
                )
            )
        except Exception:
            pass

        try:
            self.resolved_status_async(select_tab=False)
        except Exception:
            pass

        try:
            self.run_dns_guard_check_once()
        except Exception:
            pass

    def _refresh_text_widget_placeholders_for_language(self):
        placeholder_specs = [
            (
                "lynis_text",
                (
                    "Lynis-Ausgabe erscheint hier.\n",
                    "Lynis output will appear here.\n",
                ),
                self.tr("lynis_output_placeholder", "Lynis output will appear here.\n"),
            ),
            (
                "rkhunter_text",
                (
                    "rkhunter-Ausgabe erscheint hier.\n",
                    "rkhunter output will appear here.\n",
                ),
                self.tr(
                    "rkhunter_output_placeholder",
                    "rkhunter output will appear here.\n",
                ),
            ),
            (
                "packet_capture_text",
                (
                    "Packet-Capture-Status und Dateiinformationen erscheinen hier.\n",
                    "Packet capture status and file information will appear here.\n",
                ),
                self.tr(
                    "packet_capture_output_default",
                    "Packet capture status and file information will appear here.\n",
                ),
            ),
        ]

        for widget_name, legacy_values, translated_text in placeholder_specs:
            widget = self.__dict__.get(widget_name)
            if widget is None:
                continue
            try:
                current = widget.get("1.0", "end")
            except Exception:
                continue
            if current not in legacy_values and str(current or "").strip():
                continue
            try:
                widget.configure(state="normal")
                widget.delete("1.0", "end")
                widget.insert("1.0", translated_text)
                widget.configure(state="disabled")
            except Exception:
                pass

    def _refresh_dns_runtime_language_state(self):
        system_auto_label = self.tr("dns_profile_system_auto", "System (DHCP/auto)")
        dns_choice_var = self.__dict__.get("dns_choice")
        dns_combo = self.__dict__.get("dns_combo")

        try:
            choices = self._refresh_dns_profile_choices()
        except Exception:
            choices = None

        if dns_combo is not None and choices is not None:
            try:
                dns_combo.configure(values=choices)
            except Exception:
                pass

        if dns_choice_var is not None:
            try:
                current_choice = str(dns_choice_var.get() or "").strip()
            except Exception:
                current_choice = ""
            if current_choice in {"System (DHCP/auto)", system_auto_label}:
                try:
                    dns_choice_var.set(system_auto_label)
                except Exception:
                    pass

        try:
            self.update_dnssec_mode_status_labels("unknown")
        except Exception:
            pass

        try:
            self.update_dns_controls_state()
        except Exception:
            pass

    def _hide_notebook_tab_tooltip(self):
        state = self.__dict__.get("_notebook_tab_tooltip_state") or {}
        after_id = state.get("after_id")
        hide_after_id = state.get("hide_after_id")
        notebook = state.get("notebook")
        if after_id is not None and notebook is not None:
            try:
                notebook.after_cancel(after_id)
            except Exception:
                pass
        if hide_after_id is not None and notebook is not None:
            try:
                notebook.after_cancel(hide_after_id)
            except Exception:
                pass
        state["after_id"] = None
        state["hide_after_id"] = None
        state["notebook"] = None
        state["tab_id"] = None
        state["text"] = ""
        tipwindow = state.get("tipwindow")
        state["tipwindow"] = None
        if tipwindow is not None:
            try:
                tipwindow.destroy()
            except Exception:
                pass
        self._notebook_tab_tooltip_state = state

    def _show_notebook_tab_tooltip(self):
        state = self.__dict__.get("_notebook_tab_tooltip_state") or {}
        state["after_id"] = None
        if not self.tooltips_enabled.get():
            self._notebook_tab_tooltip_state = state
            return
        notebook = state.get("notebook")
        tab_id = state.get("tab_id")
        text = str(state.get("text") or "").strip()
        if notebook is None or not tab_id or not text:
            self._notebook_tab_tooltip_state = state
            return
        try:
            index = notebook.index(tab_id)
            x, y, width, height = notebook.bbox(index)
        except Exception:
            self._notebook_tab_tooltip_state = state
            return
        try:
            root_x = notebook.winfo_rootx() + x + 8
            root_y = notebook.winfo_rooty() + y + height + 8
        except Exception:
            self._notebook_tab_tooltip_state = state
            return
        tw = tk.Toplevel(notebook)
        tw.wm_overrideredirect(True)
        tw.wm_geometry(f"+{root_x}+{root_y}")
        label = tk.Label(
            tw,
            text=text,
            justify="left",
            background="#ffffe0",
            relief="solid",
            borderwidth=1,
            wraplength=420,
            padx=6,
            pady=4,
        )
        label.pack()
        state["tipwindow"] = tw
        try:
            state["hide_after_id"] = notebook.after(
                10000,
                self._hide_notebook_tab_tooltip,
            )
        except Exception:
            state["hide_after_id"] = None
        self._notebook_tab_tooltip_state = state

    def _notebook_tab_at_coords(self, notebook, x, y):
        if notebook is None:
            return None, None
        try:
            element = str(notebook.identify(x, y) or "").strip().lower()
        except Exception:
            element = ""

        if element and element == "client":
            return None, None

        try:
            index = notebook.index(f"@{x},{y}")
            tab_id = notebook.tabs()[index]
            return str(tab_id), index
        except Exception:
            return None, None

    def _notebook_tab_at_pointer(self, notebook):
        if notebook is None:
            return None, None
        try:
            pointer_x, pointer_y = notebook.winfo_pointerxy()
            local_x = pointer_x - notebook.winfo_rootx()
            local_y = pointer_y - notebook.winfo_rooty()
        except Exception:
            return None, None
        return self._notebook_tab_at_coords(notebook, local_x, local_y)

    def _schedule_notebook_tab_tooltip_hide_if_needed(self, notebook):
        def maybe_hide():
            state = self.__dict__.get("_notebook_tab_tooltip_state") or {}
            tipwindow = state.get("tipwindow")
            if tipwindow is not None:
                try:
                    pointer_x, pointer_y = notebook.winfo_pointerxy()
                    local_x = pointer_x - tipwindow.winfo_rootx()
                    local_y = pointer_y - tipwindow.winfo_rooty()
                    if (
                        0 <= local_x < tipwindow.winfo_width()
                        and 0 <= local_y < tipwindow.winfo_height()
                    ):
                        return
                except Exception:
                    pass

            tab_id, _index = self._notebook_tab_at_pointer(notebook)
            if tab_id is None:
                self._hide_notebook_tab_tooltip()

        try:
            notebook.after(80, maybe_hide)
        except Exception:
            maybe_hide()

    def _schedule_notebook_tab_tooltip(self, notebook, tab_id, text):
        self._hide_notebook_tab_tooltip()
        state = self.__dict__.setdefault("_notebook_tab_tooltip_state", {})
        state["notebook"] = notebook
        state["tab_id"] = tab_id
        state["text"] = text
        try:
            state["after_id"] = notebook.after(500, self._show_notebook_tab_tooltip)
        except Exception:
            state["after_id"] = None
            self._show_notebook_tab_tooltip()

    @staticmethod
    def _normalize_notebook_tab_label(text):
        return " ".join(str(text or "").strip().lower().split())

    def _resolve_notebook_tab_tooltip_text(self, notebook, notebook_id, tab_id, index):
        notebook_map = self.__dict__.get("_notebook_tab_tooltips", {}).get(notebook_id)
        if not isinstance(notebook_map, dict):
            return ""

        by_tab_id = notebook_map.get("by_tab_id", {})
        text = str(by_tab_id.get(str(tab_id), "") or "").strip()
        if text:
            return self._translate_tooltip_text(text)

        by_index = notebook_map.get("by_index", {})
        text = str(by_index.get(index, "") or "").strip()
        if text:
            return self._translate_tooltip_text(text)

        try:
            label = notebook.tab(tab_id, "text")
        except Exception:
            label = ""
        normalized_label = self._normalize_notebook_tab_label(label)
        by_label = notebook_map.get("by_label", {})
        return self._translate_tooltip_text(
            str(by_label.get(normalized_label, "") or "").strip()
        )

    def _bind_notebook_tab_tooltips(self, notebook):
        if notebook is None:
            return
        attached = self.__dict__.setdefault("_notebook_tab_tooltips_attached", set())
        notebook_id = str(notebook)
        if notebook_id in attached:
            return
        attached.add(notebook_id)

        def on_motion(event):
            tab_id, index = self._notebook_tab_at_coords(notebook, event.x, event.y)
            if tab_id is None or index is None:
                self._hide_notebook_tab_tooltip()
                return
            text = self._resolve_notebook_tab_tooltip_text(
                notebook,
                notebook_id,
                str(tab_id),
                index,
            )
            if not text:
                self._hide_notebook_tab_tooltip()
                return
            state = self.__dict__.get("_notebook_tab_tooltip_state") or {}
            if (
                state.get("notebook") is notebook
                and state.get("tab_id") == str(tab_id)
                and state.get("text") == text
            ):
                return
            self._schedule_notebook_tab_tooltip(notebook, str(tab_id), text)

        notebook.bind("<Motion>", on_motion, add="+")
        notebook.bind(
            "<Leave>",
            lambda _event: self._schedule_notebook_tab_tooltip_hide_if_needed(notebook),
            add="+",
        )
        notebook.bind(
            "<ButtonPress>",
            lambda _event: self._hide_notebook_tab_tooltip(),
            add="+",
        )

    def register_notebook_tab_tooltip(self, notebook, tab, text):
        if notebook is None or tab is None:
            return
        try:
            tab_id = str(tab)
            notebook.tab(tab_id)
            tab_index = notebook.index(tab_id)
            tab_label = notebook.tab(tab_id, "text")
        except Exception:
            return
        tooltip_map = self.__dict__.setdefault("_notebook_tab_tooltips", {})
        notebook_map = tooltip_map.setdefault(str(notebook), {})
        source = str(text or "").strip()
        notebook_map.setdefault("by_tab_id", {})[tab_id] = source
        notebook_map.setdefault("by_index", {})[tab_index] = source
        normalized_label = self._normalize_notebook_tab_label(tab_label)
        if normalized_label:
            notebook_map.setdefault("by_label", {})[normalized_label] = source
        self._bind_notebook_tab_tooltips(notebook)

