    def open_external_terminal(self):
        """Öffnet ein externes System-Terminal."""
        candidates = [
            ["x-terminal-emulator"],
            ["gnome-terminal"],
            ["konsole"],
            ["xfce4-terminal"],
            ["mate-terminal"],
            ["lxterminal"],
            ["xterm"],
        ]
        for cmd in candidates:
            if shutil.which(cmd[0]):
                try:
                    subprocess.Popen(cmd, start_new_session=True)
                    self.log(f"Externes Terminal gestartet: {cmd[0]}")
                    return
                except Exception as e:
                    self.log(f"Start fehlgeschlagen ({cmd[0]}): {e}")
        messagebox.showerror(
            "Terminal",
            "Kein unterstütztes Terminal-Programm gefunden.",
            parent=self,
        )

    def on_tooltip_toggle(self):
        tooltips_var = self.__dict__.get("tooltips_enabled")
        if tooltips_var is None:
            return
        try:
            enabled = bool(tooltips_var.get())
        except Exception:
            enabled = True
        if enabled:
            return
        for tip in self.__dict__.get("_tooltips", []):
            try:
                tip._hide()
            except Exception:
                pass
        self._hide_notebook_tab_tooltip()

