    def _system_row(self, parent, row, title, value_var):
        box = ttk.LabelFrame(parent, text=title, padding=8)
        box.grid(row=row, column=0, sticky="ew", pady=(0 if row == 0 else 8, 0))
        box.columnconfigure(0, weight=1)
        ttk.Label(box, textvariable=value_var).grid(row=0, column=0, sticky="w")
        status = tk.Label(box, text="–", fg="#666666")
        status.grid(row=0, column=1, sticky="e", padx=(8, 0))
        bar = ttk.Progressbar(
            box,
            mode="determinate",
            maximum=100,
            style="SystemGreen.Horizontal.TProgressbar",
        )
        bar.grid(row=1, column=0, sticky="ew", pady=(6, 0))
        return {"box": box, "bar": bar, "status": status}

    def _system_color_band(self, percent):
        p = max(0.0, min(100.0, float(percent)))
        if p < 70:
            return (
                "OK",
                "#2e7d32",
                "SystemGreen.Horizontal.TProgressbar",
            )
        if p < 90:
            return (
                "Warnung",
                "#b26a00",
                "SystemYellow.Horizontal.TProgressbar",
            )
        return (
            "Kritisch",
            "#b71c1c",
            "SystemRed.Horizontal.TProgressbar",
        )

    def _set_system_row_state(self, row_widgets, percent):
        label, color, style = self._system_color_band(percent)
        row_widgets["status"].config(text=label, fg=color)
        row_widgets["bar"]["value"] = percent
        row_widgets["bar"]["style"] = style

    def _set_swap_action_buttons_enabled(self, enabled):
        state = "normal" if enabled else "disabled"
        for key in ("btn_system_swap_clear", "btn_system_swap_resize"):
            button = self.__dict__.get(key)
            if button is None:
                continue
            try:
                button.config(state=state)
            except Exception:
                pass

    def _detect_supported_swapfile(self):
        rc, out = run_cmd(
            ["swapon", "--show=NAME,TYPE", "--noheadings", "--raw"], timeout=5
        )
        if rc != 0:
            return ""
        preferred = []
        fallback = []
        for line in (out or "").splitlines():
            parts = [part.strip() for part in line.split() if part.strip()]
            if not parts:
                continue
            path = parts[0]
            swap_type = parts[1].lower() if len(parts) > 1 else ""
            if swap_type != "file" or not path.startswith("/"):
                continue
            if not os.path.isfile(path):
                continue
            if path == "/swapfile":
                preferred.append(path)
            else:
                fallback.append(path)
        if preferred:
            return preferred[0]
        if fallback:
            return fallback[0]
        return ""

    def _read_swapfile_size_bytes(self, path):
        path = str(path or "").strip()
        if not path:
            return None
        try:
            return int(os.path.getsize(path))
        except Exception:
            return None

    def _read_ram_available_bytes(self):
        if psutil is not None:
            try:
                return int(psutil.virtual_memory().available)
            except Exception:
                pass
        try:
            with open("/proc/meminfo", "r", encoding="utf-8") as fh:
                for line in fh:
                    if line.startswith("MemAvailable:"):
                        parts = line.split()
                        if len(parts) >= 2:
                            return int(parts[1]) * 1024
        except Exception:
            pass
        return None

    def clear_swap_async(self):
        if not self._confirm_danger_action(
            "system:clear_swap",
            title=self.tr("system_swap_clear_confirm_title", "Clear swap"),
            prompt=self.tr(
                "system_swap_clear_confirm_prompt",
                "This action temporarily disables and re-enables swap.\n\nContinue?",
            ),
            cooldown_s=0,
            require_phrase="SWAP",
            force_guard=True,
        ):
            self.log_safe(
                self.tr("system_swap_clear_cancelled", "Swap clear canceled.")
            )
            return

        if not self.ensure_sudo_session(
            self.tr("system_swap_clear_reason", "Clear swap")
        ):
            self.log_safe(
                self.tr(
                    "system_swap_clear_sudo_missing",
                    "Swap could not be cleared because sudo approval is missing.",
                )
            )
            return

        self._set_swap_action_buttons_enabled(False)
        self.log_safe(self.tr("system_swap_clear_started", "Swap clear started."))

        def finish(message_key, fallback, *, refresh=False):
            def _done():
                self._set_swap_action_buttons_enabled(True)
                self.log_safe(self.tr(message_key, fallback))
                if refresh:
                    self.system_monitor_refresh()

            self.after(0, _done)

        def fail(message):
            def _done():
                self._set_swap_action_buttons_enabled(True)
                self.log_safe(message)

            self.after(0, _done)

        def job():
            for cmd in (
                ["sudo", "-n", "swapoff", "-a"],
                ["sudo", "-n", "swapon", "-a"],
            ):
                rc, out = run_cmd(cmd, timeout=30)
                if rc != 0:
                    msg = (out or "").strip() or self.tr(
                        "system_swap_clear_error_unknown",
                        "Unknown error",
                    )
                    fail(
                        self.tr(
                            "system_swap_clear_failed",
                            "Swap clear failed: {error}",
                        ).format(error=msg)
                    )
                    return
            finish("system_swap_clear_finished", "Swap clear completed.", refresh=True)

        threading.Thread(target=job, daemon=True).start()

    def resize_swap_async(self):
        swapfile = self._detect_supported_swapfile()
        if not swapfile:
            messagebox.showwarning(
                self.tr(
                    "system_swap_resize_unsupported_title", "Swap resize unavailable"
                ),
                self.tr(
                    "system_swap_resize_unsupported_body",
                    "Automatic swap resize currently supports only active file-based swap entries.",
                ),
                parent=self,
            )
            self.log_safe(
                self.tr(
                    "system_swap_resize_unsupported_log",
                    "Swap resize skipped: no supported file-based swap entry detected.",
                )
            )
            return

        current_bytes = self._read_swapfile_size_bytes(swapfile)
        if current_bytes:
            current_gib = max(1, int(round(float(current_bytes) / (1024**3))))
        else:
            total_bytes, _used, _free = self._read_swap_usage()
            current_gib = max(1, int(round(float(total_bytes or 0) / (1024**3))))
        target_gib = simpledialog.askinteger(
            self.tr("system_swap_resize_dialog_title", "Resize swap"),
            self.tr(
                "system_swap_resize_dialog_prompt",
                "Current swap size: {size} GiB\n\nEnter the new swap size in GiB:",
            ).format(size=current_gib),
            parent=self,
            minvalue=1,
            maxvalue=64,
            initialvalue=max(4, current_gib),
        )
        if target_gib is None:
            self.log_safe(
                self.tr("system_swap_resize_cancelled", "Swap resize canceled.")
            )
            return
        if target_gib == current_gib:
            self.log_safe(
                self.tr(
                    "system_swap_resize_same_size",
                    "Swap resize skipped: requested size already active.",
                )
            )
            return

        _swap_total, swap_used, _swap_free = self._read_swap_usage()
        ram_available = self._read_ram_available_bytes()
        if swap_used and ram_available:
            if swap_used > ram_available:
                messagebox.showwarning(
                    self.tr(
                        "system_swap_resize_memory_block_title",
                        "Swap resize blocked",
                    ),
                    self.tr(
                        "system_swap_resize_memory_block_body",
                        "Swap currently uses {swap_used} while only {ram_available} RAM is available.\n\nSwapoff would likely fail. Close applications first and try again.",
                    ).format(
                        swap_used=human_size(swap_used),
                        ram_available=human_size(ram_available),
                    ),
                    parent=self,
                )
                self.log_safe(
                    self.tr(
                        "system_swap_resize_memory_block_log",
                        "Swap resize blocked: too little free RAM for swapoff ({swap_used} swap in use, {ram_available} RAM available).",
                    ).format(
                        swap_used=human_size(swap_used),
                        ram_available=human_size(ram_available),
                    )
                )
                return
            if swap_used > int(ram_available * 0.8):
                proceed = messagebox.askyesno(
                    self.tr(
                        "system_swap_resize_memory_warn_title",
                        "Swap resize warning",
                    ),
                    self.tr(
                        "system_swap_resize_memory_warn_body",
                        "Swap currently uses {swap_used} and available RAM is only {ram_available}.\n\nSwapoff may fail or the system may become sluggish.\n\nContinue anyway?",
                    ).format(
                        swap_used=human_size(swap_used),
                        ram_available=human_size(ram_available),
                    ),
                    parent=self,
                )
                if not proceed:
                    self.log_safe(
                        self.tr(
                            "system_swap_resize_memory_warn_cancelled",
                            "Swap resize canceled after memory warning.",
                        )
                    )
                    return

        if not self._confirm_danger_action(
            "system:resize_swap",
            title=self.tr("system_swap_resize_confirm_title", "Resize swap"),
            prompt=self.tr(
                "system_swap_resize_confirm_prompt",
                "Swap file: {path}\nCurrent size: {current} GiB\nNew size: {target} GiB\n\nThis action recreates the swap file. Continue?",
            ).format(path=swapfile, current=current_gib, target=target_gib),
            cooldown_s=0,
            require_phrase="SWAP",
            force_guard=True,
        ):
            self.log_safe(
                self.tr("system_swap_resize_cancelled", "Swap resize canceled.")
            )
            return

        if not self.ensure_sudo_session(
            self.tr("system_swap_resize_reason", "Resize swap")
        ):
            self.log_safe(
                self.tr(
                    "system_swap_resize_sudo_missing",
                    "Swap could not be resized because sudo approval is missing.",
                )
            )
            return

        self._set_swap_action_buttons_enabled(False)
        self.log_safe(
            self.tr(
                "system_swap_resize_started",
                "Swap resize started: {target} GiB.",
            ).format(target=target_gib)
        )

        def finish(message):
            def _done():
                self._set_swap_action_buttons_enabled(True)
                self.log_safe(message)
                self.system_monitor_refresh()

            self.after(0, _done)

        def fail(message):
            def _done():
                self._set_swap_action_buttons_enabled(True)
                self.log_safe(message)

            self.after(0, _done)

        def job():
            commands = [["sudo", "-n", "swapoff", swapfile]]
            if has_cmd("rm"):
                commands.append(["sudo", "-n", "rm", "-f", swapfile])
            if has_cmd("fallocate"):
                commands.append(
                    ["sudo", "-n", "fallocate", "-l", f"{target_gib}G", swapfile]
                )
            elif has_cmd("dd"):
                commands.append(
                    [
                        "sudo",
                        "-n",
                        "dd",
                        "if=/dev/zero",
                        f"of={swapfile}",
                        "bs=1M",
                        f"count={target_gib * 1024}",
                        "status=none",
                    ]
                )
            commands.extend(
                [
                    ["sudo", "-n", "chmod", "600", swapfile],
                    ["sudo", "-n", "mkswap", swapfile],
                    ["sudo", "-n", "swapon", swapfile],
                ]
            )
            resize_written = False
            for cmd in commands:
                rc, out = run_cmd(cmd, timeout=60)
                if rc != 0:
                    if len(cmd) >= 3 and cmd[2] == "fallocate":
                        if has_cmd("dd"):
                            dd_cmd = [
                                "sudo",
                                "-n",
                                "dd",
                                "if=/dev/zero",
                                f"of={swapfile}",
                                "bs=1M",
                                f"count={target_gib * 1024}",
                                "status=none",
                            ]
                            rc, out = run_cmd(dd_cmd, timeout=120)
                            if rc == 0:
                                resize_written = True
                                continue
                        continue
                    msg = (out or "").strip() or self.tr(
                        "system_swap_clear_error_unknown",
                        "Unknown error",
                    )
                    fail(
                        self.tr(
                            "system_swap_resize_failed",
                            "Swap resize failed: {error}",
                        ).format(error=msg)
                    )
                    return
                if len(cmd) >= 3 and cmd[2] in {"fallocate", "dd"}:
                    resize_written = True
            if not resize_written:
                fail(
                    self.tr(
                        "system_swap_resize_failed",
                        "Swap resize failed: {error}",
                    ).format(
                        error=self.tr(
                            "system_swap_resize_missing_fallocate",
                            "Swap resize failed: fallocate is missing.",
                        )
                    )
                )
                return
            finish(
                self.tr(
                    "system_swap_resize_finished",
                    "Swap resized successfully to {target} GiB.",
                ).format(target=target_gib)
            )

        threading.Thread(target=job, daemon=True).start()

    def _system_temp_band(self, temp_c):
        # Gleiche Ampellogik, aber mit praxisnahen CPU-Temperatur-Schwellen.
        t = float(temp_c)
        if t < 70:
            return (
                "OK",
                "#2e7d32",
                "SystemGreen.Horizontal.TProgressbar",
            )
        if t < 85:
            return (
                "Warnung",
                "#b26a00",
                "SystemYellow.Horizontal.TProgressbar",
            )
        return (
            "Kritisch",
            "#b71c1c",
            "SystemRed.Horizontal.TProgressbar",
        )

    def _set_system_temp_state(self, row_widgets, temp_c):
        label, color, style = self._system_temp_band(temp_c)
        row_widgets["status"].config(text=label, fg=color)
        row_widgets["bar"]["value"] = max(0.0, min(100.0, float(temp_c)))
        row_widgets["bar"]["style"] = style

    def _format_uptime(self, seconds):
        total = max(0, int(seconds))
        days, rest = divmod(total, 86400)
        hours, rest = divmod(rest, 3600)
        minutes, _ = divmod(rest, 60)
        if days > 0:
            return f"{days}d {hours}h {minutes}m"
        if hours > 0:
            return f"{hours}h {minutes}m"
        return f"{minutes}m"

    def _build_sysinfo_group(self, parent, row, col, title, entries):
        box = ttk.LabelFrame(parent, text=title, padding=8)
        box.grid(
            row=row,
            column=col,
            sticky="ew",
            padx=(0 if col == 0 else 6, 0),
            pady=(0 if row == 0 else 6, 0),
        )
        box.columnconfigure(1, weight=1)
        for idx, (key, label_text) in enumerate(entries):
            ttk.Label(box, text=f"{label_text}:").grid(
                row=idx, column=0, sticky="w", padx=(0, 8), pady=(0, 2)
            )
            var = tk.StringVar(value="-")
            ttk.Label(box, textvariable=var).grid(
                row=idx, column=1, sticky="w", pady=(0, 2)
            )
            self.sysinfo_vars[key] = var

    def _set_sysinfo_value(self, key, value):
        var = self.sysinfo_vars.get(key)
        if var is None:
            return
        txt = "-" if value is None else str(value).strip()
        var.set(txt if txt else "-")

    def _safe_read_file(self, path):
        try:
            with open(path, "r", encoding="utf-8") as fh:
                return fh.read().strip()
        except Exception:
            return ""

    def _read_os_release(self):
        info = {}
        path = "/etc/os-release"
        try:
            with open(path, "r", encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if not line or "=" not in line:
                        continue
                    key, val = line.split("=", 1)
                    info[key.strip()] = val.strip().strip('"')
        except Exception:
            return {}
        return info

    def _read_cpu_model(self):
        try:
            with open("/proc/cpuinfo", "r", encoding="utf-8") as fh:
                for line in fh:
                    if ":" not in line:
                        continue
                    key, val = line.split(":", 1)
                    if key.strip().lower() in {"model name", "hardware", "processor"}:
                        model = val.strip()
                        if model:
                            return model
        except Exception:
            pass
        rc, out = run_cmd(["lscpu"], timeout=5)
        if rc == 0 and out:
            for line in out.splitlines():
                if ":" not in line:
                    continue
                key, val = line.split(":", 1)
                if key.strip().lower() == "model name":
                    model = val.strip()
                    if model:
                        return model
        return "-"

    def _read_cpu_cores_threads(self):
        cores = None
        threads = None
        if psutil is not None:
            cores = psutil.cpu_count(logical=False)
            threads = psutil.cpu_count(logical=True)
        if cores is None or threads is None:
            rc, out = run_cmd(["lscpu"], timeout=5)
            if rc == 0 and out:
                data = {}
                for line in out.splitlines():
                    if ":" not in line:
                        continue
                    key, val = line.split(":", 1)
                    data[key.strip().lower()] = val.strip()
                try:
                    sockets = int(data.get("socket(s)", "1"))
                    core_per_socket = int(data.get("core(s) per socket", "0"))
                    if core_per_socket > 0:
                        cores = core_per_socket * sockets
                except Exception:
                    pass
                try:
                    threads = int(data.get("cpu(s)", "0")) or threads
                except Exception:
                    pass
        if threads is None:
            threads = os.cpu_count()
        return cores or "-", threads or "-"

    def _read_gpu_model(self):
        rc, out = run_cmd(["lspci"], timeout=6)
        if rc != 0 or not out:
            return "-"
        candidates = []
        for line in out.splitlines():
            low = line.lower()
            if (
                "vga compatible controller" in low
                or "3d controller" in low
                or "display controller" in low
            ):
                candidates.append(line)
        if not candidates:
            return "-"
        first = candidates[0]
        if ":" in first:
            return first.split(":", 2)[-1].strip() or "-"
        return first.strip() or "-"

    def _read_board_name(self):
        vendor = self._safe_read_file("/sys/devices/virtual/dmi/id/board_vendor")
        name = self._safe_read_file("/sys/devices/virtual/dmi/id/board_name")
        version = self._safe_read_file("/sys/devices/virtual/dmi/id/board_version")
        parts = [p for p in [vendor, name, version] if p and p.lower() != "none"]
        if parts:
            return " ".join(parts)
        return "-"

    def _read_mem_totals(self):
        if psutil is not None:
            vm = psutil.virtual_memory()
            sm = psutil.swap_memory()
            return vm.total, sm.total
        mem_total = None
        swap_total = None
        try:
            with open("/proc/meminfo", "r", encoding="utf-8") as fh:
                for line in fh:
                    if line.startswith("MemTotal:"):
                        parts = line.split()
                        if len(parts) >= 2:
                            mem_total = int(parts[1]) * 1024
                    elif line.startswith("SwapTotal:"):
                        parts = line.split()
                        if len(parts) >= 2:
                            swap_total = int(parts[1]) * 1024
        except Exception:
            pass
        return mem_total, swap_total

    def _read_root_usage(self):
        if psutil is not None:
            du = psutil.disk_usage("/")
            return du.total, du.used, du.free
        rc, out = run_cmd(["df", "-B1", "/"], timeout=5)
        if rc != 0 or not out:
            return None, None, None
        lines = out.splitlines()
        if len(lines) < 2:
            return None, None, None
        parts = lines[1].split()
        if len(parts) < 6:
            return None, None, None
        try:
            total = int(parts[1])
            used = int(parts[2])
            free = int(parts[3])
            return total, used, free
        except Exception:
            return None, None, None

    def _read_swap_usage(self):
        if psutil is not None:
            sm = psutil.swap_memory()
            return sm.total, sm.used, sm.free
        total = None
        free = None
        try:
            with open("/proc/meminfo", "r", encoding="utf-8") as fh:
                for line in fh:
                    if line.startswith("SwapTotal:"):
                        parts = line.split()
                        if len(parts) >= 2:
                            total = int(parts[1]) * 1024
                    elif line.startswith("SwapFree:"):
                        parts = line.split()
                        if len(parts) >= 2:
                            free = int(parts[1]) * 1024
        except Exception:
            pass
        if total is None or free is None:
            return total, None, free
        return total, max(0, total - free), free

    def _load_sysinfo_static(self):
        osr = self._read_os_release()
        distro = osr.get("NAME") or osr.get("PRETTY_NAME") or "-"
        version = osr.get("VERSION_ID") or osr.get("VERSION") or "-"
        kernel = platform.release() or "-"
        arch = platform.machine() or "-"
        hostname = socket.gethostname() or "-"
        cpu_model = self._read_cpu_model()
        cores, threads = self._read_cpu_cores_threads()
        gpu_model = self._read_gpu_model()
        board_name = self._read_board_name()
        mem_total, swap_total = self._read_mem_totals()

        self.sysinfo_static = {
            "distribution": distro,
            "version": version,
            "kernel": kernel,
            "arch": arch,
            "hostname": hostname,
            "cpu_model": cpu_model or "-",
            "cores": cores,
            "threads": threads,
            "gpu_model": gpu_model or "-",
            "board_name": board_name or "-",
            "ram_total": human_size(mem_total),
            "swap_total": human_size(swap_total),
        }

        self._set_sysinfo_value("os_distribution", self.sysinfo_static["distribution"])
        self._set_sysinfo_value("os_version", self.sysinfo_static["version"])
        self._set_sysinfo_value("os_kernel", self.sysinfo_static["kernel"])
        self._set_sysinfo_value("os_arch", self.sysinfo_static["arch"])
        self._set_sysinfo_value("os_hostname", self.sysinfo_static["hostname"])
        self._set_sysinfo_value("hw_cpu", self.sysinfo_static["cpu_model"])
        self._set_sysinfo_value(
            "hw_cores_threads",
            f"{self.sysinfo_static['cores']} / {self.sysinfo_static['threads']}",
        )
        self._set_sysinfo_value("hw_gpu", self.sysinfo_static["gpu_model"])
        self._set_sysinfo_value("hw_board", self.sysinfo_static["board_name"])
        self._set_sysinfo_value("hw_ram_total", self.sysinfo_static["ram_total"])
        self._set_sysinfo_value("hw_swap_total", self.sysinfo_static["swap_total"])

    def _update_sysinfo_dynamic(self):
        if not hasattr(self, "sysinfo_vars"):
            return
        total, used, free = self._read_root_usage()
        swap_total, swap_used, _swap_free = self._read_swap_usage()
        desktop = (
            os.environ.get("XDG_CURRENT_DESKTOP")
            or os.environ.get("DESKTOP_SESSION")
            or "-"
        )
        user = getpass.getuser() or "-"
        pyver = platform.python_version() or sys.version.split()[0]

        self._set_sysinfo_value("os_user", user)
        self._set_sysinfo_value(
            "sys_root",
            f"{human_size(free)} frei von {human_size(total)} ({human_size(used)} belegt)",
        )
        self._set_sysinfo_value(
            "sys_swap",
            f"{human_size(swap_used)} / {human_size(swap_total)} genutzt",
        )
        self._set_sysinfo_value("sw_python", pyver)
        self._set_sysinfo_value("sw_desktop", desktop)

    def _entry_temp_current(self, entry):
        cur = getattr(entry, "current", None)
        if cur is None:
            return None
        try:
            return float(cur)
        except Exception:
            return None

    def _read_cpu_temp(self):
        temps = {}
        try:
            temps = psutil.sensors_temperatures(fahrenheit=False) or {}
        except Exception:
            temps = {}

        def _entry_match_score(entry):
            label = str(getattr(entry, "label", "") or "").strip().lower()
            name = str(getattr(entry, "name", "") or "").strip().lower()
            text = f"{label} {name}".strip()
            if not text:
                return 0
            if "tdie" in text:
                return 100
            if "package id" in text or "package" in text:
                return 90
            if "ccd" in text:
                return 80
            if "tctl" in text:
                return 30
            if "temp1" in text:
                return 20
            return 10

        def _pick_best(entries):
            ranked = []
            for entry in entries:
                cur = self._entry_temp_current(entry)
                if cur is None:
                    continue
                label = str(
                    getattr(entry, "label", "") or getattr(entry, "name", "") or ""
                ).strip()
                ranked.append((_entry_match_score(entry), cur, label))
            if not ranked:
                return "", None
            ranked.sort(key=lambda item: (item[0], item[1]), reverse=True)
            best_score, best_value, best_label = ranked[0]
            if best_score > 0:
                return best_label, best_value
            hottest = max(ranked, key=lambda item: item[1])
            return hottest[2], hottest[1]

        preferred = [
            "coretemp",
            "k10temp",
            "cpu_thermal",
            "x86_pkg_temp",
            "zenpower",
        ]
        for key in preferred:
            label, selected = _pick_best(temps.get(key, []))
            if selected is not None:
                return label, selected

        values = []
        for entries in temps.values():
            for entry in entries:
                cur = self._entry_temp_current(entry)
                if cur is not None:
                    label = str(
                        getattr(entry, "label", "") or getattr(entry, "name", "") or ""
                    ).strip()
                    values.append((label, cur))
        if values:
            hottest = max(values, key=lambda item: item[1])
            return hottest

        zone_root = "/sys/class/thermal"
        try:
            entries = os.listdir(zone_root)
        except Exception:
            entries = []
        best_label = ""
        best = None
        for name in entries:
            if not name.startswith("thermal_zone"):
                continue
            base = os.path.join(zone_root, name)
            temp_path = os.path.join(base, "temp")
            type_path = os.path.join(base, "type")
            try:
                raw = open(temp_path, "r", encoding="utf-8").read().strip()
                milli = float(raw)
                c = milli / 1000.0 if milli > 1000 else milli
            except Exception:
                continue
            try:
                ztype = open(type_path, "r", encoding="utf-8").read().strip().lower()
            except Exception:
                ztype = ""
            if "cpu" in ztype or "x86" in ztype or "pkg" in ztype:
                return ztype, c
            if best is None or c > best:
                best = c
                best_label = ztype
        return best_label, best

    def _read_cpu_temp_c(self):
        _label, value = self._read_cpu_temp()
        return value

    def _read_gpu_temp(self):
        if has_cmd("nvidia-smi"):
            rc, out = run_cmd(
                [
                    "nvidia-smi",
                    "--query-gpu=temperature.gpu",
                    "--format=csv,noheader,nounits",
                ],
                timeout=5,
            )
            if rc == 0 and out:
                for line in out.splitlines():
                    raw = str(line or "").strip()
                    if not raw:
                        continue
                    try:
                        return "nvidia-smi", float(raw)
                    except Exception:
                        continue

        temps = {}
        try:
            temps = psutil.sensors_temperatures(fahrenheit=False) or {}
        except Exception:
            temps = {}

        gpu_entries = list(temps.get("amdgpu", []) or [])
        ranked = []
        for entry in gpu_entries:
            cur = self._entry_temp_current(entry)
            if cur is None:
                continue
            label = str(
                getattr(entry, "label", "") or getattr(entry, "name", "") or ""
            ).strip()
            label_low = label.lower()
            score = (
                100
                if "edge" in label_low
                else 80 if "junction" in label_low else 60 if "mem" in label_low else 40
            )
            ranked.append((score, cur, label))
        if ranked:
            ranked.sort(key=lambda item: (item[0], -item[1]), reverse=True)
            best = ranked[0]
            return best[2], best[1]

        zone_root = "/sys/class/thermal"
        try:
            entries = os.listdir(zone_root)
        except Exception:
            entries = []
        for name in entries:
            if not name.startswith("thermal_zone"):
                continue
            base = os.path.join(zone_root, name)
            temp_path = os.path.join(base, "temp")
            type_path = os.path.join(base, "type")
            try:
                ztype = open(type_path, "r", encoding="utf-8").read().strip().lower()
                raw = open(temp_path, "r", encoding="utf-8").read().strip()
                milli = float(raw)
                c = milli / 1000.0 if milli > 1000 else milli
            except Exception:
                continue
            if "gpu" in ztype or "amdgpu" in ztype:
                return ztype, c
        return "", None

    def _system_monitor_missing_psutil(self):
        self.system_cpu_var.set("CPU: –")
        self.system_ram_var.set("RAM: –")
        self.system_swap_var.set("Swap: –")
        self.system_disk_var.set("Disk /: –")
        self.system_temp_var.set(
            self.tr("system_status_temp_default", "CPU temp (sensor): –")
        )
        self.system_gpu_temp_var.set(
            self.tr("system_status_gpu_temp_default", "GPU temp: –")
        )
        self.system_uptime_var.set("Uptime: –")
        for bar in [
            self.system_cpu_bar,
            self.system_ram_bar,
            self.system_swap_bar,
            self.system_disk_bar,
            self.system_temp_bar,
            self.system_gpu_temp_bar,
        ]:
            self._set_system_row_state(bar, 0)
            bar["status"].config(text="–", fg="#666666")
        if not self.system_monitor_psutil_hint_logged:
            self.log("Systemmonitor benötigt das Python-Modul psutil.")
            self.log("Installationsbefehl:")
            self.log("pip install psutil")
            self.system_monitor_psutil_hint_logged = True
        self._update_sysinfo_dynamic()

    def system_monitor_refresh(self):
        if not self.system_monitor_active:
            return

        if psutil is None:
            self._system_monitor_missing_psutil()
        else:
            cpu = max(0.0, min(100.0, float(psutil.cpu_percent(interval=None))))
            vm = psutil.virtual_memory()
            sm = psutil.swap_memory()
            du = psutil.disk_usage("/")
            cpu_temp_label, temp_c = self._read_cpu_temp()
            gpu_temp_label, gpu_temp_c = self._read_gpu_temp()
            up_sec = time.time() - float(psutil.boot_time())

            self.system_cpu_var.set(f"CPU: {cpu:.0f} %")
            self.system_ram_var.set(
                f"RAM: {human_size(vm.used)} / {human_size(vm.total)} ({vm.percent:.0f} %)"
            )
            self.system_swap_var.set(
                f"Swap: {human_size(sm.used)} / {human_size(sm.total)} ({sm.percent:.0f} %)"
            )
            self.system_disk_var.set(
                f"Disk /: {human_size(du.used)} / {human_size(du.total)} ({du.percent:.0f} %)"
            )
            if temp_c is None:
                self.system_temp_var.set(
                    self.tr(
                        "system_status_temp_unavailable",
                        "CPU temp (sensor): unavailable",
                    )
                )
                self.system_temp_bar["bar"]["value"] = 0
                self.system_temp_bar["bar"][
                    "style"
                ] = "SystemGreen.Horizontal.TProgressbar"
                self.system_temp_bar["status"].config(text="–", fg="#666666")
            else:
                sensor_hint = f" ({cpu_temp_label})" if cpu_temp_label else ""
                self.system_temp_var.set(
                    self.tr(
                        "system_status_temp_value",
                        "CPU temp{sensor}: {value:.1f} °C",
                    ).format(sensor=sensor_hint, value=temp_c)
                )
                self._set_system_temp_state(self.system_temp_bar, temp_c)
            if gpu_temp_c is None:
                self.system_gpu_temp_var.set(
                    self.tr(
                        "system_status_gpu_temp_unavailable", "GPU temp: unavailable"
                    )
                )
                self.system_gpu_temp_bar["bar"]["value"] = 0
                self.system_gpu_temp_bar["bar"][
                    "style"
                ] = "SystemGreen.Horizontal.TProgressbar"
                self.system_gpu_temp_bar["status"].config(text="–", fg="#666666")
            else:
                gpu_hint = f" ({gpu_temp_label})" if gpu_temp_label else ""
                self.system_gpu_temp_var.set(
                    self.tr(
                        "system_status_gpu_temp_value",
                        "GPU temp{sensor}: {value:.1f} °C",
                    ).format(sensor=gpu_hint, value=gpu_temp_c)
                )
                self._set_system_temp_state(self.system_gpu_temp_bar, gpu_temp_c)
            self.system_uptime_var.set(f"Uptime: {self._format_uptime(up_sec)}")

            self._set_system_row_state(self.system_cpu_bar, cpu)
            self._set_system_row_state(self.system_ram_bar, vm.percent)
            self._set_system_row_state(self.system_swap_bar, sm.percent)
            self._set_system_row_state(self.system_disk_bar, du.percent)
            self._update_sysinfo_dynamic()

        self.after(self.system_monitor_interval_ms, self.system_monitor_refresh)

    def _select_system_tab(self, tab):
        nb = self.__dict__.get("nb")
        system_main = self.__dict__.get("tab_system_main")
        system_nb = self.__dict__.get("system_nb")
        if nb is None:
            return
        if system_main is not None and system_nb is not None:
            nb.select(system_main)
            system_nb.select(tab)
            return
        nb.select(tab)

    def _select_tools_tab(self, tab):
        nb = self.__dict__.get("nb")
        tools_tab = self.__dict__.get("tab_tools")
        tools_nb = self.__dict__.get("tools_nb")
        if nb is None:
            return
        if tools_tab is not None and tools_nb is not None:
            nb.select(tools_tab)
            tools_nb.select(tab)
            return
        nb.select(tab)

    def open_radio_tab(self, event=None):
        if radio_controller is None:
            return "break"
        return radio_controller.open_radio_tab(self, event)

    def _sync_radio_theme_to_current_theme(self):
        if radio_controller is None:
            return False
        theme_name = "light"
        theme_palette = {}
        try:
            current_theme = dict(self._app_theme or LIGHT_THEME)
            theme_name = (
                str(current_theme.get("name", "light") or "light").strip().lower()
                or "light"
            )
            theme_palette = dict(current_theme)
        except Exception:
            theme_name = "light"
            theme_palette = {}
        panel = self.__dict__.get("radio_embedded_panel")
        target = panel if panel is not None else self
        try:
            target.radio_settings["theme"] = theme_name
        except Exception:
            pass
        if panel is not None:
            try:
                panel.radio_settings["theme"] = theme_name
            except Exception:
                pass
            try:
                apply_theme_palette = getattr(panel, "apply_theme_palette", None)
                if callable(apply_theme_palette):
                    apply_theme_palette(theme_name, theme_palette)
                else:
                    panel.apply_theme(theme_name)
                return True
            except Exception:
                pass
        try:
            self.radio_settings["theme"] = theme_name
        except Exception:
            pass
        try:
            radio_controller.save_radio_settings(self)
            return True
        except Exception:
            return False

    def _current_radio_theme_name(self):
        try:
            return (
                str((self._app_theme or LIGHT_THEME).get("name", "light") or "light")
                .strip()
                .lower()
                or "light"
            )
        except Exception:
            return "light"

    def _log_radio_theme_diagnostic(self, stage):
        try:
            with open(self.radio_settings_path, "r", encoding="utf-8") as handle:
                radio_settings = json.load(handle)
            radio_theme = (
                str((radio_settings or {}).get("theme", "") or "").strip().lower()
            )
        except Exception:
            radio_theme = ""
        current_theme = self._current_radio_theme_name()
        stored_theme = str(self.settings.get("theme", "") or "").strip().lower()
        launcher_mode = str(getattr(self, "radio_launcher_mode", "") or "").strip()
        self.log_safe(
            "[RadioThemeDiag] "
            f"{stage} | app_theme={current_theme or '-'} | "
            f"settings_theme={stored_theme or '-'} | "
            f"radio_settings_theme={radio_theme or '-'} | "
            f"launcher_mode={launcher_mode or '-'}"
        )

    def open_radio_external_app(self):
        self._record_diagnostic_action(
            "Radio loslösen",
            "radio",
            details={
                "launcher_mode": str(getattr(self, "radio_launcher_mode", "") or ""),
                "radio_detached": bool(getattr(self, "radio_detached", False)),
            },
        )
        if netmon_radio_core is None:
            self.log_safe("Radio-App Launcher nicht verfügbar.")
            return False
        source_app = getattr(self, "radio_embedded_panel", None)
        if source_app is None or getattr(self, "radio_launcher_mode", "") != "embedded":
            source_app = self
        try:
            if netmon_radio_core.radio_transition_in_progress("standalone"):
                self.log_safe("Radio-Uebergang zu Standalone läuft bereits.")
                status_var = self.__dict__.get("radio_launcher_status_var")
                if status_var is not None:
                    try:
                        status_var.set(
                            "Radio wird bereits als Standalone-App gestartet."
                        )
                    except Exception:
                        pass
                return False
            if netmon_radio_core.standalone_radio_is_running():
                netmon_radio_core.set_radio_detached_state(True)
                try:
                    netmon_radio_core.request_standalone_radio_show()
                except Exception:
                    pass
                refresh_fn = getattr(self, "refresh_radio_launcher_state", None)
                if callable(refresh_fn):
                    try:
                        refresh_fn()
                    except Exception:
                        pass
                self.log_safe("Radio-App läuft bereits standalone.")
                return True
        except Exception:
            pass
        status_var = self.__dict__.get("radio_launcher_status_var")
        if status_var is not None:
            try:
                status_var.set(
                    self.tr(
                        "radio_status_launch_standalone",
                        "Radio wird als Standalone-App gestartet.",
                    )
                )
            except Exception:
                pass
        self._log_radio_theme_diagnostic("before_detach_launch")
        try:
            self._sync_radio_theme_to_current_theme()
        except Exception:
            pass
        self._log_radio_theme_diagnostic("after_detach_theme_sync")
        handover_payload = {}
        if radio_controller is not None:
            try:
                handover_payload = radio_controller.build_radio_handover_payload(
                    source_app
                )
            except Exception:
                handover_payload = {}
        try:
            netmon_radio_core.clear_radio_attach_request()
            netmon_radio_core.clear_standalone_radio_attach_request()
            netmon_radio_core.consume_radio_handover_ack("embedded")
            netmon_radio_core.begin_radio_transition(
                from_mode="embedded",
                target_mode="standalone",
                owner_pid=os.getpid(),
                current_station_id=str(
                    handover_payload.get(
                        "current_station_id",
                        getattr(source_app, "radio_current_station_id", ""),
                    )
                    or ""
                ),
                started_from="netmon_detach",
            )
            transition_id = netmon_radio_core.current_radio_transition_id()
            netmon_radio_core.request_radio_handover(
                target_mode="standalone",
                payload=handover_payload,
                action="detach",
                transition_id=transition_id,
            )
        except Exception:
            transition_id = ""
        proc = netmon_radio_core.launch_radio_app(
            logger=getattr(self, "log_safe", None),
            theme_name=self._current_radio_theme_name(),
            started_from="netmon_detach",
        )
        if proc is not None:
            try:
                netmon_radio_core.request_standalone_radio_show(
                    transition_id=transition_id
                )
            except Exception:
                pass
            self._radio_detach_source = source_app
            self._radio_detach_waiting_ack = bool(handover_payload.get("was_playing"))
            if not self._radio_detach_waiting_ack:
                try:
                    netmon_radio_core.set_radio_detached_state(True)
                except Exception:
                    pass
                refresh_fn = getattr(self, "refresh_radio_launcher_state", None)
                if callable(refresh_fn):
                    try:
                        refresh_fn()
                    except Exception:
                        pass
        else:
            try:
                netmon_radio_core.cancel_radio_transition(os.getpid())
                netmon_radio_core.clear_radio_handover_request("standalone")
            except Exception:
                pass
        return proc is not None

    def reattach_radio_app(self, handover_payload=None):
        self._record_diagnostic_action(
            "Radio anheften",
            "radio",
            details={
                "has_handover_payload": bool(isinstance(handover_payload, dict)),
                "radio_detached": bool(getattr(self, "radio_detached", False)),
            },
        )
        if handover_payload is None and netmon_radio_core is not None:
            try:
                if netmon_radio_core.standalone_radio_is_running():
                    status_var = self.__dict__.get("radio_launcher_status_var")
                    if status_var is not None:
                        try:
                            status_var.set(
                                self.tr(
                                    "radio_status_reattach",
                                    "Radio wird wieder an NetMon angeheftet.",
                                )
                            )
                        except Exception:
                            pass
                    return netmon_radio_core.request_standalone_radio_attach()
            except Exception:
                pass
        self._log_radio_theme_diagnostic("before_reattach")
        status_var = self.__dict__.get("radio_launcher_status_var")
        if status_var is not None:
            try:
                status_var.set(
                    self.tr(
                        "radio_status_reattach",
                        "Radio wird wieder an NetMon angeheftet.",
                    )
                )
            except Exception:
                pass
        if radio_controller is not None:
            try:
                with open(self.radio_settings_path, "r", encoding="utf-8") as handle:
                    radio_settings = json.load(handle)
                if isinstance(radio_settings, dict):
                    theme_name = self._normalize_theme_name(
                        radio_settings.get("theme", "light")
                    )
                    self.radio_settings.update(radio_settings)
                    self.settings["theme"] = theme_name
                    theme_choice_var = self.__dict__.get("var_theme_choice")
                    if theme_choice_var is not None:
                        try:
                            theme_choice_var.set(
                                self._get_theme_display_name(theme_name)
                            )
                        except Exception:
                            pass
                    self.apply_theme(theme_name, log_change=False, persist=False)
                    try:
                        self.save_settings()
                    except Exception:
                        pass
                    try:
                        self.update_idletasks()
                    except Exception:
                        pass
            except Exception:
                pass
        self._log_radio_theme_diagnostic("after_reattach_theme_apply")
        if netmon_radio_core is not None:
            try:
                netmon_radio_core.complete_radio_transition(
                    mode="embedded",
                    owner_pid=os.getpid(),
                    current_station_id=getattr(self, "radio_current_station_id", ""),
                    started_from="netmon_attach",
                    attached=True,
                )
                netmon_radio_core.set_radio_detached_state(False)
            except Exception:
                pass
        if radio_controller is not None:
            try:
                radio_controller.open_radio_tab(self)
            except Exception:
                pass
        refresh_fn = getattr(self, "refresh_radio_launcher_state", None)
        if callable(refresh_fn):
            try:
                refresh_fn()
            except Exception:
                pass
        if radio_controller is not None and isinstance(handover_payload, dict):
            target = getattr(self, "radio_embedded_panel", None) or self
            try:
                radio_controller.apply_radio_handover_payload(
                    target,
                    handover_payload,
                    auto_play=True,
                )
            except Exception:
                pass
        return True

    def _poll_radio_attach_request(self):
        if netmon_radio_core is not None:
            try:
                ack_payload = netmon_radio_core.consume_radio_handover_ack(
                    "embedded",
                    transition_id=netmon_radio_core.current_radio_transition_id(),
                )
                if (
                    isinstance(ack_payload, dict)
                    and ack_payload.get("action") == "detach_ready"
                ):
                    source_app = self.__dict__.pop("_radio_detach_source", None)
                    self._radio_detach_waiting_ack = False
                    if source_app is not None:
                        try:
                            source_app.stop_radio_playback(async_mode=False)
                        except Exception:
                            pass
                    try:
                        netmon_radio_core.set_radio_detached_state(True)
                    except Exception:
                        pass
                    refresh_fn = getattr(self, "refresh_radio_launcher_state", None)
                    if callable(refresh_fn):
                        try:
                            refresh_fn()
                        except Exception:
                            pass
                transition_id = netmon_radio_core.current_radio_transition_id()
                if netmon_radio_core.consume_radio_attach_request(
                    transition_id=transition_id
                ):
                    handover_payload = netmon_radio_core.consume_radio_handover(
                        "embedded",
                        transition_id=transition_id,
                    )
                    self.reattach_radio_app(handover_payload=handover_payload)
            except Exception:
                pass
        try:
            self.after(800, self._poll_radio_attach_request)
        except Exception:
            pass

