    def update_dns_output(self, text: str, append: bool = False):
        if not hasattr(self, "dns_text") or self.dns_text is None:
            return
        self.dns_text.configure(state="normal")
        if not append:
            self.dns_text.delete("1.0", "end")
        if text:
            if append and self.dns_text.index("end-1c") != "1.0":
                self.dns_text.insert("end", "\n\n")
        self.dns_text.insert("end", text)
        self.dns_text.see("end")
        self.dns_text.configure(state="normal")

    def clear_dns_output(self):
        self.update_dns_output("")
        if "chad_analysis_status_var" in self.__dict__:
            self.chad_analysis_status_var.set(
                self.tr("chad_status_dns_output_cleared", "DNS output cleared.")
            )

    def update_dns_header(self):
        iface = self.get_default_iface()
        dns_servers = []

        nm_dns_list = self.__dict__.get("nm_get_dns_list")
        if callable(nm_dns_list):
            try:
                dns_servers = list(nm_dns_list(iface) or [])
            except Exception:
                dns_servers = []

        if not dns_servers:
            try:
                dns_servers = list(self.get_active_dns_servers() or [])
            except Exception:
                dns_servers = []

        dns_text = ", ".join(
            str(server).strip() for server in dns_servers if str(server).strip()
        )
        if not dns_text:
            dns_text = "-"

        public_ip = str(self.__dict__.get("public_ip", "-") or "-").strip()
        country = str(self.__dict__.get("country", "-") or "-").strip()
        text = f"NM DNS ({iface}): {dns_text} | IP: {public_ip} | Land: {country}"
        self.nm_dns_header_text = text

        header_var = self.__dict__.get("nm_dns_header_var")
        if header_var is not None:
            try:
                header_var.set(text)
            except Exception:
                pass

    def is_vpn_active(self):
        service = self._dns_control_service()
        if service is None:
            code, out = run_cmd(["resolvectl", "status"], timeout=6)
            if code != 0:
                return False
            return self.detect_vpn_active(out)
        code, out = service.read_resolvectl_status(timeout=6)
        if code != 0:
            return False
        return service.detect_vpn_active(out)

    def update_vpn_status_text(self):
        tr = getattr(self, "tr", None)
        if not callable(tr):

            def tr(_key, fallback=None):
                return fallback

        try:
            vpn_active = self.is_vpn_active()
        except Exception:
            vpn_active = False

        ip = getattr(self, "public_ip", "-") or "-"
        country = getattr(self, "country", "-") or "-"
        status_var = self.__dict__.get("vpn_status_text_var")
        if status_var is None:
            return

        if vpn_active:
            status_var.set(
                tr(
                    "vpn_status_active", "VPN: aktiv | IP: {ip} | Land: {country}"
                ).format(ip=ip, country=country)
            )
        else:
            status_var.set(tr("vpn_status_default", "VPN: aus | IP: - | Land: -"))

    def _manual_dns_choice(self):
        choice_var = self.__dict__.get("dns_choice")
        choice = (
            (choice_var.get() if choice_var is not None else "") or "System (DHCP/auto)"
        ).strip()
        if choice in DNS_PROFILES:
            return choice
        normalized_choice = self._register_manual_dns_choice(choice)
        if normalized_choice:
            return normalized_choice
        return "System (DHCP/auto)"

    def _dot_profile_for_dns_choice(self, dns_choice):
        choice = str(dns_choice or "").strip()
        mapping = {
            "Cloudflare (1.1.1.1)": "Cloudflare",
            "Google (8.8.8.8)": "Google",
            "Quad9 (malware-blocking)": "Quad9",
        }
        return mapping.get(choice, "Cloudflare")

    def _sync_dns_protocol_profile_labels(self):
        dns_choice = self._manual_dns_choice()
        if not self.is_dot_active() and not bool(
            self.__dict__.get("dot_running", False)
        ):
            dot_profile = self._dot_profile_for_dns_choice(dns_choice)
            if dns_choice not in DNS_PROFILES:
                dot_profile = self.tr("dns_manual_selection_label", "manual selection")
            dot_profile_var = self.__dict__.get("dot_profile_var")
            if dot_profile_var is not None:
                dot_profile_var.set(
                    self.tr("dot_profile_value", "Profile: {profile}").format(
                        profile=dot_profile if dot_profile else "–"
                    )
                )
            dot_servers = self._dns_servers_for_choice(dns_choice)
            dot_server_var = self.__dict__.get("dot_server_var")
            if dot_server_var is not None:
                dot_server_var.set(
                    self.tr("dot_server_value", "Server: {server}").format(
                        server=", ".join(dot_servers) if dot_servers else "–"
                    )
                )

    def _on_dns_choice_changed(self, *_args):
        self._sync_dns_protocol_profile_labels()
        self.update_dns_controls_state_safe()

    def _normalize_allowed_root_text_path(self, path):
        candidate = os.path.realpath(str(path or "").strip())
        allowed_paths = {
            os.path.realpath(DOT_DROPIN_PATH),
            os.path.realpath(RKHUNTER_BACKUP_PATH),
        }
        if not candidate or candidate not in allowed_paths:
            return ""
        return candidate

    def _write_root_text_file(self, path, content):
        tmp_path = ""
        try:
            safe_path = self._normalize_allowed_root_text_path(path)
            if not safe_path:
                return False, f"Nicht erlaubter Root-Zielpfad: {path}"
            parent_dir = os.path.dirname(safe_path)
            if parent_dir:
                rc_dir, out_dir = run_cmd(
                    ["sudo", "-n", "mkdir", "-p", parent_dir], timeout=10
                )
                if rc_dir != 0:
                    return (
                        False,
                        (out_dir or "").strip()
                        or f"Verzeichnis konnte nicht erstellt werden: {parent_dir}",
                    )
            with tempfile.NamedTemporaryFile(
                mode="w", encoding="utf-8", delete=False
            ) as temp_file:
                temp_file.write(content)
                tmp_path = temp_file.name
            rc_install, out_install = run_cmd(
                ["sudo", "-n", "install", "-m", "644", tmp_path, safe_path],
                timeout=12,
            )
            if rc_install != 0:
                return (
                    False,
                    (out_install or "").strip()
                    or f"Datei konnte nicht geschrieben werden: {safe_path}",
                )
            return True, ""
        finally:
            if tmp_path:
                try:
                    os.remove(tmp_path)
                except Exception:
                    pass

    def _remove_root_text_file(self, path):
        safe_path = self._normalize_allowed_root_text_path(path)
        if not safe_path:
            return False, f"Nicht erlaubter Root-Zielpfad: {path}"
        rc_rm, out_rm = run_cmd(["sudo", "-n", "rm", "-f", safe_path], timeout=10)
        if rc_rm != 0:
            return (
                False,
                (out_rm or "").strip()
                or f"Datei konnte nicht entfernt werden: {safe_path}",
            )
        return True, ""

    def is_physical_dns_candidate(self, name: str, conn_type: str, device: str) -> bool:
        service = self._dns_control_service()
        if service is None:
            return False
        return service.is_physical_dns_candidate(name, conn_type, device)

    def nm_active_connections_detailed(self):
        service = self._dns_control_service()
        if service is None:
            return []
        return service.nm_active_connections_detailed()

    def _active_nm_dns_targets(self):
        service = self._dns_control_service()
        if service is None:
            return []
        iface = self.get_default_iface()
        con = self.nm_active_conn_for_dev(iface)
        return service.filter_physical_nm_targets(
            self.nm_active_connections_detailed(),
            default_iface=iface or "",
            default_connection=con or "",
        )

    def _apply_nm_dns_policy_to_targets(self, *, ignore_auto_dns):
        service = self._dns_control_service()
        if service is None:
            return False, ["DNS-Control-Service nicht verfügbar."]
        ok, details = service.apply_nm_dns_policy_to_targets(
            ignore_auto_dns=ignore_auto_dns,
            targets=self._active_nm_dns_targets(),
        )
        return ok, [self._translate_nm_dns_policy_detail(item) for item in details]

    def _translate_nm_dns_policy_detail(self, text: str) -> str:
        value = str(text or "").strip()
        if not value:
            return value
        if value == "nmcli fehlt – NetworkManager ist nicht verfügbar.":
            return self.tr(
                "dns_nm_missing",
                "nmcli is missing - NetworkManager is not available.",
            )
        if value == "Keine aktive physische LAN/WLAN-Connection gefunden.":
            return self.tr(
                "dns_nm_no_physical_connection",
                "No active physical LAN/WLAN connection found.",
            )
        if value.startswith("✔ Verbindung erkannt: "):
            payload = value.removeprefix("✔ Verbindung erkannt: ")
            return self.tr(
                "dns_nm_connection_detected", "✔ Connection detected: {value}"
            ).format(value=payload)
        if value == "✔ Auto-DNS deaktiviert (IPv4 / IPv6)":
            return self.tr(
                "dns_nm_auto_dns_disabled",
                "✔ Auto-DNS disabled (IPv4 / IPv6)",
            )
        if value == "✔ Auto-DNS aktiviert (IPv4 / IPv6)":
            return self.tr(
                "dns_nm_auto_dns_enabled",
                "✔ Auto-DNS enabled (IPv4 / IPv6)",
            )
        if value == "✔ Manuelle DNS-Server zurückgesetzt":
            return self.tr(
                "dns_nm_manual_dns_reset",
                "✔ Manual DNS servers reset",
            )
        if value == "✔ Verbindung neu gestartet":
            return self.tr(
                "dns_nm_connection_restarted",
                "✔ Connection restarted",
            )
        replacements = {
            "✖ Fehler beim Setzen von Auto-DNS (IPv4)": self.tr(
                "dns_nm_error_set_auto_dns_ipv4",
                "✖ Error setting auto DNS (IPv4)",
            ),
            "✖ Fehler beim Setzen von Auto-DNS (IPv6)": self.tr(
                "dns_nm_error_set_auto_dns_ipv6",
                "✖ Error setting auto DNS (IPv6)",
            ),
            "✖ Fehler beim Zurücksetzen der DNS-Server (IPv4)": self.tr(
                "dns_nm_error_reset_dns_ipv4",
                "✖ Error resetting DNS servers (IPv4)",
            ),
            "✖ Fehler beim Zurücksetzen der DNS-Server (IPv6)": self.tr(
                "dns_nm_error_reset_dns_ipv6",
                "✖ Error resetting DNS servers (IPv6)",
            ),
            "✖ Fehler beim Neustart der Verbindung": self.tr(
                "dns_nm_error_restart_connection",
                "✖ Error restarting connection",
            ),
        }
        for de_prefix, translated in replacements.items():
            if value.startswith(de_prefix):
                return value.replace(de_prefix, translated, 1)
        return value

    def _write_manual_dns_dropin(self, dns_choice):
        servers = self._dns_servers_for_choice(dns_choice)
        if not servers:
            return False, "Keine gültigen DNS-Server ausgewählt."
        dnssec_mode = "allow-downgrade"
        preferred_mode = getattr(self, "get_preferred_dnssec_mode", None)
        if callable(preferred_mode) and preferred_mode() == "strict":
            dnssec_mode = "yes"
        content = "\n".join(
            [
                "# Managed by NetMon",
                "[Resolve]",
                f"DNS={' '.join(servers)}",
                "DNSOverTLS=no",
                f"DNSSEC={dnssec_mode}",
                "Domains=~.",
                "",
            ]
        )
        return self._write_dot_dropin_text(content)

    def _write_dot_dropin_text(self, content):
        service = self._dns_control_service()
        if service is None:
            ok, detail = self._write_root_text_file(DOT_DROPIN_PATH, content)
            return ok, content if ok else detail

        ok, detail = service.write_dropin(content)
        return ok, content if ok else detail

    def _restore_dot_dropin_backup(self, previous_text):
        previous_text = previous_text if previous_text is not None else ""
        if not previous_text.strip():
            return self._remove_manual_dns_dropin()
        return self._write_dot_dropin_text(previous_text)

    def _remove_manual_dns_dropin(self):
        service = self._dns_control_service()
        if service is None:
            return self._remove_root_text_file(DOT_DROPIN_PATH)
        return service.remove_dropin()

    def _restart_resolved_for_dns_policy(self):
        service = self._dns_control_service()
        if service is None:
            rc, out = run_cmd(
                ["sudo", "-n", "systemctl", "restart", "systemd-resolved"],
                timeout=15,
            )
            return rc == 0, (out or "").strip()
        return service.restart_resolved()

    def refresh_dns_policy_status(self):
        return dns_controller.refresh_dns_policy_status(self)

    def evaluate_dns_policy(self, resolvectl_output: str) -> dict:
        return dns_controller.evaluate_dns_policy(self, resolvectl_output)

    def _show_dns_policy_result(self, text, *, startup=False):
        dns_controller.show_dns_policy_result(self, text, startup=startup)

    def warn_no_vpn(self):
        result = self.tr(
            "dns_control_warn_no_vpn",
            "=== DNS Control ===\n"
            "DNS rule: prefer VPN DNS\n"
            "Status: no active VPN detected\n"
            "Action: no system change performed\n\n"
            "Recommendation: connect the VPN or only set DNS manually outside a VPN.",
        )
        self.refresh_dns_policy_status()
        return False, result

    def warn_manual_dns_with_vpn(self):
        result = self.tr(
            "dns_control_warn_manual_dns_with_vpn",
            "=== DNS-Steuerung ===\n"
            "DNS-Regel: VPN-DNS bevorzugen\n"
            "Status: blockiert\n"
            "Grund: VPN ist aktiv.\n\n"
            "NetMon setzt kein globales DNS-Drop-in, solange VPN-DNS aktiv ist,\n"
            "damit VPN-DNS und ein manueller Resolver nicht gleichzeitig aktiv sind.",
        )
        self.refresh_dns_policy_status()
        return False, result

    def use_vpn_dns(self):
        return dns_controller.use_vpn_dns(self)

    def _normalize_dns_profile_choice(self, choice=None):
        return dns_controller.normalize_dns_profile_choice(self, choice)

    def should_accept_vpn_dns_for_stealth(self, choice=None, vpn_active=None):
        normalized_choice = self._normalize_dns_profile_choice(choice)
        if normalized_choice != "System (DHCP/auto)":
            return False

        stealth_var = self.__dict__.get("isp_stealth_enabled")
        stealth_enabled = False
        if stealth_var is not None:
            try:
                stealth_enabled = bool(stealth_var.get())
            except Exception:
                stealth_enabled = bool(stealth_var)

        stealth_running = bool(self.__dict__.get("isp_stealth_running", False))
        if not (stealth_enabled or stealth_running):
            return False

        if vpn_active is None:
            try:
                vpn_active = self.is_vpn_active_for_dns_ui()
            except Exception:
                vpn_active = False

        return bool(vpn_active)

    def _apply_dns_profile_choice_via_control(self, choice):
        return dns_controller.apply_dns_profile_choice_via_control(self, choice)

    def _format_dns_profile_control_result(self, result, *, heading, action):
        return dns_controller.format_dns_profile_control_result(
            self,
            result,
            heading=heading,
            action=action,
        )

    def use_user_dns(self):
        return dns_controller.use_user_dns(self)

    def enforce_dns_policy(self):
        return dns_controller.enforce_dns_policy(self)

    def _run_dns_policy_action(self, *, startup=False, repair_only=False):
        try:
            if repair_only:
                success, text = self.fix_dns_conflicts(startup=startup)
            else:
                success, text = self.enforce_dns_policy()
            self.after(
                0,
                lambda t=text, s=startup: self._show_dns_policy_result(
                    t,
                    startup=s,
                ),
            )
            if not startup:
                if repair_only:
                    self.log_safe(
                        self.tr(
                            "dns_policy_log_status_evaluated", "DNS status evaluated"
                        )
                        if success
                        else self.tr(
                            "dns_policy_log_status_evaluated_with_notice",
                            "DNS-Status mit Hinweis bewertet",
                        )
                    )
                else:
                    self.log_safe(
                        self.tr("dns_policy_log_applied", "DNS-Policy angewendet")
                        if success
                        else self.tr(
                            "dns_policy_log_finished_with_notice",
                            "DNS-Policy mit Hinweis beendet",
                        )
                    )
        except Exception as exc:
            error_text = self.tr(
                "dns_control_error_output",
                "=== DNS Control ===\nFehler: {error}",
            ).format(error=exc)
            self.after(
                0,
                lambda t=error_text, s=startup: self._show_dns_policy_result(
                    t,
                    startup=s,
                ),
            )
            if not startup:
                self.log_safe(
                    self.tr(
                        "dns_policy_log_status_check_failed",
                        "DNS-Statusprüfung fehlgeschlagen",
                    )
                    if repair_only
                    else self.tr(
                        "dns_policy_log_failed",
                        "DNS-Policy fehlgeschlagen",
                    )
                )
        finally:
            self.dns_policy_running = False

    def enforce_dns_policy_async(self):
        if self.dns_policy_running:
            self.log_safe(
                self.tr("dns_policy_log_already_running", "DNS-Policy läuft bereits.")
            )
            return
        if not self.ensure_sudo_session(
            self.tr("dns_policy_action_label", "DNS-Policy anwenden")
        ):
            return
        self.dns_policy_running = True
        self.nb.select(self.tab_dns)
        self.log_safe(self.tr("dns_policy_log_applying", "DNS-Policy wird angewendet"))
        threading.Thread(
            target=self._run_dns_policy_action,
            kwargs={"startup": False, "repair_only": False},
            daemon=True,
        ).start()

    def fix_dns_conflicts(self, startup=False):
        code, out = run_cmd(["resolvectl", "status"], timeout=8)
        if code != 0:
            return (
                False,
                self.tr(
                    "dns_control_result_status_read_failed",
                    "=== DNS Control ===\nStatus: Prüfung fehlgeschlagen\nGrund: resolvectl status konnte nicht gelesen werden.\n\nDetails:\n{details}",
                ).format(details=out),
            )

        evaluation = self.evaluate_dns_policy(out)
        lines = [
            self.tr("dns_control_report_title", "=== DNS Control ==="),
            self.tr("dns_control_report_action_status", "Action: status evaluation"),
            self.tr("dns_rule_status", "DNS rule: prefer VPN DNS"),
            self.tr(
                "dns_control_report_vpn_active",
                "VPN active: {value}",
            ).format(
                value=(
                    self.tr("value_yes", "YES")
                    if evaluation.get("vpn_active")
                    else self.tr("value_no", "NO")
                )
            ),
            self.tr(
                "dns_status_active_resolver_value",
                "Active resolver: {resolver}",
            ).format(
                resolver=evaluation.get(
                    "resolver_label",
                    self.tr("dns_value_unknown", "unknown"),
                )
            ),
            self.tr(
                "dns_control_report_dot_dropin",
                "NetMon DoT Drop-in: {value}",
            ).format(
                value=(
                    self.tr("value_present", "present")
                    if evaluation.get("dot_dropin_exists")
                    else self.tr("value_not_present", "not present")
                )
            ),
            self.tr(
                "dns_control_report_global_enforcement",
                "Global DNS enforcement: {value}",
            ).format(
                value=(
                    self.tr("value_yes", "YES")
                    if evaluation.get("dot_dropin_conflict")
                    else self.tr("value_no", "NO")
                )
            ),
            self.tr("dns_control_report_risk", "Risiko: {value}").format(
                value=evaluation.get("risk", self.tr("dns_value_unknown", "unknown"))
            ),
            "",
            self.tr("dns_control_report_recommendations", "Recommendations:"),
        ]
        for recommendation in evaluation.get("recommendations") or [
            self.tr(
                "dns_control_recommendation_none",
                "No recommendation available.",
            )
        ]:
            lines.append(f"- {recommendation}")
        if evaluation.get("warnings"):
            lines.append("")
            lines.append(self.tr("dns_control_warnings_title", "Findings:"))
            for warning in evaluation["warnings"]:
                lines.append(f"- {warning}")
        if startup:
            lines.append("")
            lines.append(
                self.tr(
                    "dns_control_startup_notice",
                    "Hinweis: Beim Start wurden keine Änderungen durchgeführt.",
                )
            )
        return True, "\n".join(lines)

    def fix_dns_conflicts_async(self):
        if self.dns_policy_running:
            self.log_safe(
                self.tr(
                    "dns_policy_log_conflict_check_running",
                    "DNS-Konfliktprüfung läuft bereits.",
                )
            )
            return
        self.dns_policy_running = True
        self.nb.select(self.tab_dns)
        self.log_safe(
            self.tr("dns_policy_log_status_evaluating", "DNS-Status wird bewertet")
        )
        threading.Thread(
            target=self._run_dns_policy_action,
            kwargs={"startup": False, "repair_only": True},
            daemon=True,
        ).start()

    def startup_dns_policy_check(self):
        try:
            self.refresh_dns_policy_status()
            if self.dns_policy_running:
                return
            self.dns_policy_running = True
            threading.Thread(
                target=self._run_dns_policy_action,
                kwargs={"startup": True, "repair_only": True},
                daemon=True,
            ).start()
        except Exception as exc:
            try:
                self.log(
                    self.tr(
                        "dns_policy_log_startup_check_failed",
                        "[WARN] DNS-Policy-Startprüfung fehlgeschlagen: {error}",
                    ).format(error=exc)
                )
            except Exception:
                pass

    def apply_vpn_dns_policy(self):
        code, out = run_cmd(["resolvectl", "status"], timeout=8)
        if code != 0:
            return (
                False,
                self.tr(
                    "vpn_dns_enforce_result_status_unreadable",
                    "=== DNS Control ===\nAktion: VPN-DNS erzwingen\nStatus: abgebrochen\nGrund: resolvectl status konnte nicht gelesen werden.\n\nDetails:\n{details}",
                ).format(details=out),
            )
        evaluation = self.evaluate_dns_policy(out)
        if not evaluation.get("vpn_active"):
            return self.warn_no_vpn()
        if not evaluation.get("vpn_dns"):
            return (
                False,
                self.tr(
                    "vpn_dns_enforce_result_no_vpn_dns",
                    "=== DNS Control ===\nAktion: VPN-DNS erzwingen\nStatus: abgebrochen\nGrund: Kein VPN-DNS erkannt.",
                ),
            )
        return self.use_vpn_dns()

    def apply_vpn_dns_policy_async(self):
        if self.dns_policy_running:
            self.log_safe(
                self.tr("dns_control_log_already_running", "DNS-Control läuft bereits.")
            )
            return
        code, out = run_cmd(["resolvectl", "status"], timeout=8)
        if code != 0:
            self.nb.select(self.tab_dns)
            self.update_dns_output(
                self.tr(
                    "vpn_dns_enforce_result_check_failed",
                    "=== DNS Control ===\nAktion: VPN-DNS erzwingen\nStatus: Prüfung fehlgeschlagen\n\nDetails:\n{details}",
                ).format(details=out),
                append=True,
            )
            self.log_safe(
                self.tr(
                    "vpn_dns_enforce_log_failed",
                    "VPN-DNS-Erzwingung fehlgeschlagen",
                )
            )
            return

        evaluation = self.evaluate_dns_policy(out)
        if not evaluation.get("vpn_active"):
            success, text = self.warn_no_vpn()
            self.nb.select(self.tab_dns)
            self.update_dns_output(text, append=True)
            self.refresh_dns_policy_status()
            self.log_safe(
                self.tr(
                    "vpn_dns_enforce_log_not_possible",
                    "VPN-DNS-Erzwingung nicht möglich",
                )
            )
            return

        ok = messagebox.askyesno(
            self.tr("vpn_dns_enforce_confirm_title", "VPN-DNS erzwingen"),
            self.tr(
                "vpn_dns_enforce_confirm_message",
                "NetMon entfernt das NetMon-DoT-Drop-in, leert manuelle DNS-Werte auf "
                "echten LAN/WLAN-Verbindungen und setzt ignore-auto-dns auf diesen "
                "physischen Connections.\n\n"
                "VPN-Verbindungen, lo, docker0 und veth-Interfaces bleiben unberührt.\n\n"
                "Fortfahren?",
            ),
            parent=self,
        )
        if not ok:
            self.chad_analysis_status_var.set(
                self.tr(
                    "vpn_dns_enforce_status_cancelled",
                    "VPN-DNS-Erzwingung abgebrochen.",
                )
            )
            return
        if not self.ensure_sudo_session(
            self.tr("vpn_dns_enforce_confirm_title", "VPN-DNS erzwingen")
        ):
            result = self.tr(
                "vpn_dns_enforce_result_missing_sudo",
                "=== DNS Control ===\nAktion: VPN-DNS erzwingen\nStatus: abgebrochen\nGrund: sudo-Freigabe fehlt.",
            )
            self.nb.select(self.tab_dns)
            self.update_dns_output(result, append=True)
            return

        self.dns_policy_running = True
        self.nb.select(self.tab_dns)
        self.log_safe(
            self.tr(
                "vpn_dns_enforce_log_started",
                "VPN-DNS-Erzwingung gestartet",
            )
        )

        def worker():
            try:
                success, text = self.apply_vpn_dns_policy()
                self.after(
                    0,
                    lambda t=text: self._show_dns_policy_result(t, startup=False),
                )
                self.after(0, self.run_dns_leak_check)
                self.log_safe(
                    self.tr(
                        "vpn_dns_enforce_log_finished",
                        "VPN-DNS-Erzwingung abgeschlossen",
                    )
                    if success
                    else self.tr(
                        "vpn_dns_enforce_log_finished_with_notice",
                        "VPN-DNS-Erzwingung mit Hinweis beendet",
                    )
                )
            finally:
                self.dns_policy_running = False

        threading.Thread(target=worker, daemon=True).start()

    def load_ai_config(self):
        try:
            if self.ai_online_service is not None:
                env_key = (self.ai_online_service.api_key or "").strip()
                if env_key:
                    self.openai_api_key_var.set(env_key)
                    self.chad_online_status_var.set(
                        self.tr("chad_online_status_ready", "Online-Analyse: bereit")
                    )
                self.apply_chad_model_selection()
                self.refresh_chad_runtime_status()

            if not os.path.isfile(self.ai_config_path):
                return

            with open(self.ai_config_path, "r", encoding="utf-8") as f:
                data = json.load(f)

            use_keyring = bool(data.get("use_keyring"))
            if not use_keyring:
                return

            if not self.keyring_available:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_keyring_unavailable_not_loaded",
                        "Keyring nicht verfügbar. API-Key nicht geladen.",
                    )
                )
                return

            kr = self._get_keyring_module()
            if kr is None:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_keyring_module_unavailable_not_loaded",
                        "Keyring-Modul nicht verfügbar. API-Key nicht geladen.",
                    )
                )
                return

            key = kr.get_password(KEYRING_SERVICE, KEYRING_USERNAME)
            if key:
                self.openai_api_key_var.set(key)
                if self.ai_online_service is not None:
                    self.ai_online_service.api_key = key
                    self.ai_online_service.default_model = (
                        str(self.chad_model_var.get() or "gpt-4.1-mini").strip()
                        or "gpt-4.1-mini"
                    )
                self.openai_api_key_saved = True
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_api_key_loaded_from_keyring",
                        "API-Key aus System-Keyring geladen.",
                    )
                )
                self.chad_online_status_var.set(
                    self.tr("chad_online_status_ready", "Online-Analyse: bereit")
                )
                self.refresh_chad_runtime_status()
            else:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_no_api_key_in_keyring",
                        "Kein API-Key im System-Keyring gefunden.",
                    )
                )
                self.refresh_chad_runtime_status()

        except Exception as e:
            try:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_api_key_load_error",
                        "Fehler beim Laden des API-Keys: {error}",
                    ).format(error=e)
                )
            except Exception:
                pass

    def save_ai_config(self):
        try:
            key = (self.openai_api_key_var.get() or "").strip()

            if not key:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_no_api_key_entered", "Kein API-Key eingegeben."
                    )
                )
                return

            if not self.keyring_available:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_keyring_unavailable_cannot_save",
                        "Keyring nicht verfügbar. API-Key kann nicht sicher gespeichert werden.",
                    )
                )
                return

            kr = self._get_keyring_module()
            if kr is None:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_keyring_module_unavailable_not_saved",
                        "Keyring-Modul nicht verfügbar. API-Key wurde nicht gespeichert.",
                    )
                )
                return

            kr.set_password(KEYRING_SERVICE, KEYRING_USERNAME, key)

            ok, err = safe_write_json(self.ai_config_path, {"use_keyring": True})

            if ok:
                self.openai_api_key_saved = True
                if self.ai_online_service is not None:
                    self.ai_online_service.api_key = key
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_api_key_saved_to_keyring",
                        "API-Key sicher im System-Keyring gespeichert.",
                    )
                )
                self.chad_online_status_var.set(
                    self.tr("chad_online_status_ready", "Online-Analyse: bereit")
                )
            else:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_api_key_saved_config_error",
                        "Key gespeichert, aber Config-Fehler: {error}",
                    ).format(error=err)
                )
            self.refresh_chad_runtime_status()

        except Exception as e:
            self.chad_analysis_status_var.set(
                self.tr(
                    "chad_status_api_key_save_error",
                    "Fehler beim Speichern des API-Keys: {error}",
                ).format(error=e)
            )

    def apply_api_key(self):
        key = (self.openai_api_key_var.get() or "").strip()

        if not key:
            if self.ai_online_service is not None:
                self.ai_online_service.api_key = ""
            self.openai_api_key_saved = False
            self.chad_analysis_status_var.set(
                self.tr("chad_status_no_api_key_entered", "Kein API-Key eingegeben.")
            )
            self.chad_online_status_var.set(
                self.tr("chad_online_status_inactive", "Online analysis: inactive")
            )
            self.refresh_chad_runtime_status()
            return

        if self.ai_online_service is None:
            self.chad_analysis_status_var.set(
                self.tr(
                    "chad_status_ai_online_service_unavailable",
                    "AI-Online-Service nicht verfügbar.",
                )
            )
            self.chad_online_status_var.set(
                self.tr("chad_online_status_inactive", "Online analysis: inactive")
            )
            self.refresh_chad_runtime_status()
            return

        self.ai_online_service.api_key = key
        self.chad_analysis_status_var.set(
            self.tr("chad_status_api_key_applied", "API-Key übernommen.")
        )
        self.chad_online_status_var.set(
            self.tr("chad_online_status_ready", "Online-Analyse: bereit")
        )
        self.apply_chad_model_selection()
        self.refresh_chad_runtime_status()

    def clear_api_key(self):
        self.openai_api_key_var.set("")
        if self.ai_online_service is not None:
            self.ai_online_service.api_key = ""
        self.openai_api_key_saved = False
        self.chad_analysis_status_var.set(
            self.tr("chad_status_api_key_cleared", "API-Key im Feld gelöscht.")
        )
        self.chad_online_status_var.set(
            self.tr("chad_online_status_inactive", "Online analysis: inactive")
        )
        self.refresh_chad_runtime_status()

    # Hinweis fuer Paketierung:
    # Abhaengigkeiten:
    # - python3-keyring
    # - gnome-keyring
    def check_keyring_availability(self):
        self.keyring_available = False
        self.keyring_error = ""
        self.keyring_backend_name = ""

        try:
            kr_mod = self._get_keyring_module()
            if kr_mod is None:
                self.keyring_error = "Python-Modul 'keyring' nicht installiert."
                self.log(
                    "[WARN] Keyring nicht verfügbar – API-Key Speicherung deaktiviert."
                )
                return False

            try:
                kr = kr_mod.get_keyring()
                self.keyring_backend_name = kr.__class__.__name__
                backend_name = (self.keyring_backend_name or "").lower()
                if "fail" in backend_name:
                    self.keyring_error = (
                        f"Keyring Backend nicht nutzbar: {self.keyring_backend_name}"
                    )
                else:
                    self.keyring_available = True
            except Exception as e:
                self.keyring_error = f"Keyring nicht nutzbar: {e}"

        except ImportError:
            self.keyring_error = "Python-Modul 'keyring' nicht installiert."

        if not self.keyring_available:
            self.log(
                "[WARN] Keyring nicht verfügbar – API-Key Speicherung deaktiviert."
            )

        return self.keyring_available

    def _get_keyring_module(self):
        global keyring
        if keyring is not None:
            return keyring
        try:
            keyring = importlib.import_module("keyring")
            return keyring
        except Exception as exc:
            try:
                self.log_debug_safe(f"Keyring Import fehlgeschlagen: {exc}")
            except Exception:
                pass
            return None

    def delete_saved_api_key(self):
        try:
            kr = self._get_keyring_module()
            if kr is not None:
                try:
                    kr.delete_password(KEYRING_SERVICE, KEYRING_USERNAME)
                except Exception:
                    pass

            self.openai_api_key_var.set("")
            if self.ai_online_service is not None:
                self.ai_online_service.api_key = ""
            self.openai_api_key_saved = False

            ok, err = safe_write_json(self.ai_config_path, {"use_keyring": False})

            if ok:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_saved_api_key_deleted",
                        "Gespeicherter API-Key gelöscht.",
                    )
                )
            else:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_api_key_deleted_config_error",
                        "Key gelöscht, aber Config-Fehler: {error}",
                    ).format(error=err)
                )
            self.chad_online_status_var.set(
                self.tr("chad_online_status_inactive", "Online analysis: inactive")
            )
            self.refresh_chad_runtime_status()

        except Exception as e:
            self.chad_analysis_status_var.set(
                self.tr(
                    "chad_status_api_key_delete_error",
                    "Fehler beim Löschen des API-Keys: {error}",
                ).format(error=e)
            )

    def paste_api_key_from_clipboard(self, _event=None):
        try:
            clip = self.clipboard_get()
        except Exception:
            self.chad_analysis_status_var.set(
                self.tr(
                    "chad_status_clipboard_empty_or_unavailable",
                    "Zwischenablage leer oder nicht verfügbar.",
                )
            )
            return "break"

        key = (clip or "").strip()
        if not key:
            self.chad_analysis_status_var.set(
                self.tr(
                    "chad_status_clipboard_contains_no_api_key",
                    "Zwischenablage enthält keinen API-Key.",
                )
            )
            return "break"

        self.openai_api_key_var.set(key)
        self.chad_analysis_status_var.set(
            self.tr(
                "chad_status_api_key_pasted_from_clipboard",
                "API-Key aus Zwischenablage eingefügt.",
            )
        )
        try:
            self.openai_api_key_entry.focus_set()
            self.openai_api_key_entry.icursor("end")
        except Exception:
            pass
        return "break"

    def _log_chad_error(self, source: str, error_text: str):
        chad_controller.log_chad_error(self, source, error_text)

    def append_to_chad_output(self, title: str, text: str):
        chad_controller.append_to_chad_output(self, title, text)

    def confirm_chad_send(self, title: str, intro_text: str) -> bool:
        if tk is None or ttk is None:
            return messagebox.askyesno(title, intro_text, parent=self)

        result = {"ok": False}
        win = tk.Toplevel(self)
        win.title(title)
        win.geometry("560x220")
        win.resizable(False, False)
        win.transient(self)

        outer = ttk.Frame(win, padding=12)
        outer.pack(fill="both", expand=True)

        ttk.Label(
            outer,
            text=intro_text,
            justify="left",
            wraplength=520,
        ).pack(anchor="w")

        ttk.Label(
            outer,
            text=self.tr("chad_security_notice_title", "Sicherheitshinweis"),
            justify="left",
            font=("TkDefaultFont", 10, "bold"),
        ).pack(anchor="w", pady=(12, 4))

        ttk.Label(
            outer,
            text=self.tr(
                "chad_security_notice_body",
                "Bitte keine sensiblen Daten absenden.\n"
                "Dazu gehören z. B. Passwörter, API-Keys, Tokens, private Schlüssel, "
                "persönliche Daten oder interne Inhalte.\n\n"
                "Bitte vor dem Senden sorgfältig prüfen und nur notwendige Ausschnitte übertragen.",
            ),
            justify="left",
            wraplength=520,
        ).pack(anchor="w")

        btn_row = ttk.Frame(outer)
        btn_row.pack(fill="x", pady=(14, 0))

        def _close(ok: bool):
            result["ok"] = bool(ok)
            try:
                win.grab_release()
            except Exception:
                pass
            win.destroy()

        ttk.Button(
            btn_row,
            text=self.tr("btn_cancel", "Abbrechen"),
            command=lambda: _close(False),
        ).pack(side="right")
        ttk.Button(
            btn_row,
            text=self.tr("btn_continue", "Fortfahren"),
            command=lambda: _close(True),
        ).pack(side="right", padx=(0, 8))

        win.protocol("WM_DELETE_WINDOW", lambda: _close(False))
        try:
            win.grab_set()
            win.focus_force()
        except Exception:
            pass
        self.wait_window(win)
        return result["ok"]

