    def is_autostart_enabled(self):
        return os.path.exists(AUTOSTART_FILE)

    def _window_icon_asset_path(self) -> str:
        candidate = os.path.join(NETMON_REPO_ROOT, "tools", "netmon.png")
        if os.path.isfile(candidate):
            return candidate
        return ""

    def _apply_window_icon(self) -> None:
        if tk is None:
            return
        icon_path = self._window_icon_asset_path()
        self._window_icon_path = icon_path
        self._window_icon_applied = False
        if not icon_path:
            return
        try:
            icon = tk.PhotoImage(file=icon_path)
            self._window_icon_photo = icon
            self.iconphoto(True, icon)
            self._window_icon_applied = True
        except Exception:
            pass

    def _window_integration_context(self) -> dict[str, str]:
        return {
            "window_class": "NetMon",
            "startup_wm_class": "NetMon",
            "icon_path": str(getattr(self, "_window_icon_path", "") or "").strip(),
            "icon_applied": (
                "yes" if bool(getattr(self, "_window_icon_applied", False)) else "no"
            ),
        }

    def _log_window_integration_diagnostic(self, stage: str) -> None:
        info = self._window_integration_context()
        self.log_safe(
            "[WindowDiag] "
            f"{stage} | window_class={info['window_class']} | "
            f"startup_wm_class={info['startup_wm_class']} | "
            f"icon_applied={info['icon_applied']} | "
            f"icon_path={info['icon_path'] or '-'}"
        )

    def _autostart_exec_command(self) -> str:
        if shutil.which("netmon"):
            return "netmon"

        exec_path = os.path.abspath(sys.argv[0] or "")
        if not exec_path or not os.path.exists(exec_path):
            exec_path = os.path.join(NETMON_REPO_ROOT, "netmon", "main.py")
        return f"python3 {exec_path}"

    def is_radio_desktop_launcher_enabled(self):
        if netmon_radio_core is None:
            return False
        try:
            return os.path.exists(netmon_radio_core.radio_desktop_entry_path())
        except Exception:
            return False

    def _radio_desktop_icon_path(self) -> str:
        if netmon_radio_core is not None:
            try:
                icon_path = str(netmon_radio_core.radio_icon_path() or "").strip()
                if icon_path and os.path.isfile(icon_path):
                    return icon_path
            except Exception:
                pass
        candidate = os.path.join(NETMON_REPO_ROOT, "tools", "netmon-radio.png")
        if os.path.isfile(candidate):
            return candidate
        return ""

    def _radio_desktop_exec_command(self) -> str:
        if netmon_radio_core is None:
            return ""
        theme_name = self._current_radio_theme_name()
        try:
            return netmon_radio_core.build_radio_desktop_exec_command(
                theme_name=theme_name
            )
        except Exception:
            return ""

    def enable_radio_desktop_launcher(self):
        if netmon_radio_core is None:
            return False
        try:
            desktop_path = netmon_radio_core.ensure_radio_desktop_entry(
                theme_name=self._current_radio_theme_name(),
                started_from="desktop",
            )
            return bool(desktop_path and os.path.isfile(desktop_path))
        except Exception:
            return False

    def disable_radio_desktop_launcher(self):
        if netmon_radio_core is None:
            return False
        try:
            desktop_path = netmon_radio_core.radio_desktop_entry_path()
            if os.path.exists(desktop_path):
                os.remove(desktop_path)
            return True
        except Exception:
            return False

    def toggle_radio_desktop_launcher(self):
        launcher_var = self.__dict__.get("radio_desktop_launcher_var")
        enabled = bool(launcher_var.get()) if launcher_var is not None else False
        ok = (
            self.enable_radio_desktop_launcher()
            if enabled
            else self.disable_radio_desktop_launcher()
        )
        if launcher_var is not None:
            launcher_var.set(self.is_radio_desktop_launcher_enabled())
        if ok:
            self.log_safe(
                "Radio-Starticon aktiviert"
                if enabled
                else "Radio-Starticon deaktiviert"
            )
            return
        self.log_safe("Radio-Starticon konnte nicht aktualisiert werden.")

    def enable_autostart(self):
        try:
            os.makedirs(AUTOSTART_DIR, exist_ok=True)

            content = (
                "[Desktop Entry]\n"
                "Type=Application\n"
                "Name=NetMon\n"
                f"Exec={self._autostart_exec_command()}\n"
                "StartupWMClass=NetMon\n"
                "X-GNOME-Autostart-enabled=true\n"
            )

            with open(AUTOSTART_FILE, "w", encoding="utf-8") as handle:
                handle.write(content)
            return True
        except Exception:
            return False

    def disable_autostart(self):
        try:
            if os.path.exists(AUTOSTART_FILE):
                os.remove(AUTOSTART_FILE)
            return True
        except Exception:
            return False

    def toggle_autostart(self):
        enabled = bool(self.autostart_var.get())
        ok = self.enable_autostart() if enabled else self.disable_autostart()

        if ok:
            self.autostart_var.set(self.is_autostart_enabled())
            self.log_safe(
                self.tr(
                    "log_autostart_enabled" if enabled else "log_autostart_disabled",
                    "Autostart aktiviert" if enabled else "Autostart deaktiviert",
                )
            )
            return

        self.autostart_var.set(self.is_autostart_enabled())
        self.log_safe(
            self.tr(
                "log_autostart_failed",
                "Autostart konnte nicht aktualisiert werden.",
            )
        )

    def _normalize_start_network_mode(self, mode) -> str:
        return "system"

    def _normalize_isp_dns_fallback_profile(self, choice=None) -> str:
        value = str(choice or "").strip()
        if value in DNS_PROFILES and value != "System (DHCP/auto)":
            return value
        return "Cloudflare (1.1.1.1)"

    def _default_download_scan_temp_dir(self) -> str:
        runtime_dir = str(os.environ.get("XDG_RUNTIME_DIR") or "").strip()
        candidates = []
        if runtime_dir and os.path.isdir(runtime_dir):
            candidates.append(
                os.path.join(runtime_dir, "netmon_roots", "download_scan")
            )
        if os.path.isdir("/dev/shm"):
            candidates.append("/dev/shm/netmon_roots/download_scan")
        if os.path.isdir("/tmp"):
            candidates.append("/tmp/netmon_roots/download_scan")
        candidates.append(os.path.expanduser("~/.cache/netmon_roots/download_scan"))

        for candidate in candidates:
            if self._download_scan_mount_has_option(candidate, "noexec"):
                return candidate
        for candidate in candidates:
            if self._download_scan_path_is_ephemeral(candidate):
                return candidate
        return candidates[-1]

    def _default_download_scan_target_dir(self) -> str:
        return os.path.expanduser("~/Downloads")

    def _default_backup_data_target_dir(self) -> str:
        return os.path.abspath(os.path.expanduser("~/NetMon-Backups"))

    def _download_scan_temp_dir_candidates(
        self, preferred: str | None = None
    ) -> list[str]:
        candidates = []

        def _add(path: str):
            normalized = os.path.abspath(os.path.expanduser(path or ""))
            if normalized and normalized not in candidates:
                candidates.append(normalized)

        _add(preferred or self._normalized_download_scan_temp_dir())
        runtime_dir = str(os.environ.get("XDG_RUNTIME_DIR") or "").strip()
        if runtime_dir:
            _add(os.path.join(runtime_dir, "netmon_roots", "download_scan"))
        _add("/dev/shm/netmon_roots/download_scan")
        _add("/tmp/netmon_roots/download_scan")
        _add(os.path.expanduser("~/.cache/netmon_roots/download_scan"))
        return candidates

    def _download_scan_existing_anchor_path(self, path: str) -> str:
        current = os.path.abspath(os.path.expanduser(path or "/"))
        while current and not os.path.exists(current):
            parent = os.path.dirname(current)
            if parent == current:
                break
            current = parent
        return current if os.path.exists(current) else "/"

    def _download_scan_mount_options(self, path: str) -> set[str]:
        anchor = self._download_scan_existing_anchor_path(path)
        try:
            with open("/proc/self/mountinfo", "r", encoding="utf-8") as handle:
                lines = handle.readlines()
        except Exception:
            return set()

        best_match = ""
        best_options: set[str] = set()
        for raw_line in lines:
            line = raw_line.strip()
            if " - " not in line:
                continue
            pre, post = line.split(" - ", 1)
            pre_fields = pre.split()
            post_fields = post.split()
            if len(pre_fields) < 6 or len(post_fields) < 3:
                continue
            mount_point = (
                pre_fields[4]
                .replace("\\040", " ")
                .replace("\\011", "\t")
                .replace("\\012", "\n")
                .replace("\\134", "\\")
            )
            if not (
                anchor == mount_point
                or anchor.startswith(mount_point.rstrip("/") + "/")
            ):
                continue
            if len(mount_point) >= len(best_match):
                best_match = mount_point
                best_options = set(filter(None, pre_fields[5].split(","))) | set(
                    filter(None, post_fields[2].split(","))
                )
        return best_options

    def _download_scan_mount_info(self, path: str) -> dict[str, object]:
        anchor = self._download_scan_existing_anchor_path(path)
        info = {
            "mount_point": "",
            "options": set(),
            "fs_type": "",
            "source": "",
        }
        try:
            with open("/proc/self/mountinfo", "r", encoding="utf-8") as handle:
                lines = handle.readlines()
        except Exception:
            return info

        best_match = ""
        for raw_line in lines:
            line = raw_line.strip()
            if " - " not in line:
                continue
            pre, post = line.split(" - ", 1)
            pre_fields = pre.split()
            post_fields = post.split()
            if len(pre_fields) < 6 or len(post_fields) < 3:
                continue
            mount_point = (
                pre_fields[4]
                .replace("\\040", " ")
                .replace("\\011", "\t")
                .replace("\\012", "\n")
                .replace("\\134", "\\")
            )
            if not (
                anchor == mount_point
                or anchor.startswith(mount_point.rstrip("/") + "/")
            ):
                continue
            if len(mount_point) >= len(best_match):
                best_match = mount_point
                info = {
                    "mount_point": mount_point,
                    "options": set(filter(None, pre_fields[5].split(",")))
                    | set(filter(None, post_fields[2].split(","))),
                    "fs_type": post_fields[0],
                    "source": post_fields[1],
                }
        return info

    def _download_scan_mount_has_option(self, path: str, option: str) -> bool:
        try:
            return str(
                option or ""
            ).strip().lower() in self._download_scan_mount_options(path)
        except Exception:
            return False

    def _download_scan_path_is_ephemeral(self, path: str) -> bool:
        normalized = os.path.abspath(os.path.expanduser(path or ""))
        runtime_dir = str(os.environ.get("XDG_RUNTIME_DIR") or "").strip()
        if runtime_dir and normalized.startswith(os.path.abspath(runtime_dir) + os.sep):
            return True
        return normalized.startswith("/tmp/") or normalized.startswith("/dev/shm/")

    def _download_scan_secure_mount_ready(self, path: str) -> bool:
        info = self._download_scan_mount_info(path)
        options = set(info.get("options") or set())
        fs_type = str(info.get("fs_type") or "").strip().lower()
        return fs_type == "tmpfs" and {"noexec", "nosuid", "nodev"}.issubset(options)

    def _download_scan_path_is_accessible(self, path: str) -> bool:
        normalized = os.path.abspath(os.path.expanduser(path or ""))
        return os.path.isdir(normalized) and os.access(
            normalized, os.R_OK | os.W_OK | os.X_OK
        )

    def _download_scan_mount_option_string(self) -> str:
        return (
            "rw,noexec,nosuid,nodev,mode=700,size=256m,"
            f"uid={os.getuid()},gid={os.getgid()}"
        )

    def _describe_download_scan_temp_security(self, path: str) -> tuple[str, str]:
        mount_info = self._download_scan_mount_info(path)
        noexec_active = self._download_scan_mount_has_option(path, "noexec")
        ephemeral = self._download_scan_path_is_ephemeral(path)
        fs_type = str(mount_info.get("fs_type") or "").strip() or self.tr(
            "value_unknown", "unknown"
        )
        parts = [
            (
                self.tr(
                    "download_scan_temp_status_noexec_active",
                    "noexec active",
                )
                if noexec_active
                else self.tr(
                    "download_scan_temp_status_no_noexec",
                    "no noexec",
                )
            ),
            self.tr("download_scan_temp_status_fs", "FS: {fs_type}").format(
                fs_type=fs_type
            ),
            (
                self.tr(
                    "download_scan_temp_status_ephemeral",
                    "ephemeral path",
                )
                if ephemeral
                else self.tr(
                    "download_scan_temp_status_persistent",
                    "persistent path",
                )
            ),
        ]
        status = self.tr(
            "download_scan_temp_status_summary",
            "Temp protection: {details}",
        ).format(details=" | ".join(parts))

        hint = self.tr(
            "download_scan_temp_hint_short_storage",
            "Files are only meant for short-term staging. "
            "The pre-quarantine remains available across NetMon restarts.",
        )
        if self._download_scan_secure_mount_ready(path):
            hint += self.tr(
                "download_scan_hint_tmpfs_active",
                " Vor-Quarantäne aktiv: eigener tmpfs-Mount mit noexec/nosuid/nodev.",
            )
        else:
            hint += self.tr(
                "download_scan_hint_tmpfs_ideal",
                " Idealfall ist ein eigener tmpfs-Mount mit noexec/nosuid/nodev.",
            )
        if ephemeral:
            hint += self.tr(
                "download_scan_temp_hint_ephemeral_path",
                " The default path is also located in an ephemeral area and typically disappears after logout/restart.",
            )
        else:
            hint += self.tr(
                "download_scan_temp_hint_persistent_cleanup",
                " Contents are typically only discarded after a system or mount restart.",
            )
        if not noexec_active:
            hint += self.tr(
                "download_scan_temp_hint_noexec_warning",
                " Warning: noexec is not active here. Never start files directly from this folder.",
            )
        return status, hint

    def _stealth_startup_enabled(self) -> bool:
        config = self.__dict__.get("privacy_config", {})
        if not isinstance(config, dict):
            return False
        return bool(config.get("enabled", False) and config.get("autostart", False))

    def _donation_timestamp(self, key: str) -> int:
        try:
            return int(float(self.settings.get(key, 0) or 0))
        except (TypeError, ValueError):
            return 0

    def _ensure_donation_popup_first_seen_at(self) -> int:
        first_seen_at = self._donation_timestamp("donation_popup_first_seen_at")
        if first_seen_at > 0:
            return first_seen_at
        first_seen_at = int(time.time())
        self.settings["donation_popup_first_seen_at"] = first_seen_at
        try:
            self.save_settings(log_success=False)
        except Exception:
            pass
        return first_seen_at

    def donation_popup_disable_allowed(self, now: int | None = None) -> bool:
        first_seen_at = self._donation_timestamp("donation_popup_first_seen_at")
        if first_seen_at <= 0:
            return False
        if now is None:
            now = int(time.time())
        return (int(now) - first_seen_at) >= self.DONATION_POPUP_DISABLE_AFTER_SECONDS

    def donation_popup_settings_note(self) -> str:
        if self.donation_popup_disable_allowed():
            return self.tr(
                "settings_donation_popup_disable_available",
                "Der Spendenhinweis kann jetzt dauerhaft abgeschaltet werden.",
            )
        first_seen_at = self._donation_timestamp("donation_popup_first_seen_at")
        if first_seen_at <= 0:
            return self.tr(
                "settings_donation_popup_disable_after_week",
                "Abschalten ist nach 7 Tagen Nutzung möglich.",
            )
        remaining_seconds = max(
            0,
            self.DONATION_POPUP_DISABLE_AFTER_SECONDS
            - (int(time.time()) - first_seen_at),
        )
        remaining_days = max(1, int((remaining_seconds + 86_399) // 86_400))
        return self.tr(
            "settings_donation_popup_disable_remaining",
            "Abschalten ist in ca. {days} Tag(en) möglich.",
        ).format(days=remaining_days)

    def refresh_donation_settings_controls(self):
        note_var = self.__dict__.get("donation_popup_settings_note_var")
        if note_var is not None:
            try:
                note_var.set(self.donation_popup_settings_note())
            except Exception:
                pass
        checkbox = self.__dict__.get("cb_donation_popup_enabled")
        if checkbox is not None:
            try:
                checkbox.configure(
                    state=(
                        "normal"
                        if self.donation_popup_disable_allowed()
                        else "disabled"
                    )
                )
            except Exception:
                pass

    def schedule_donation_popup_startup(self):
        if not bool(self.settings.get("donation_popup_enabled", True)):
            return
        self._ensure_donation_popup_first_seen_at()
        self.refresh_donation_settings_controls()
        self.after(self.DONATION_POPUP_STARTUP_DELAY_MS, self.show_donation_popup)

    def _donation_popup_body_text(self) -> str:
        return self.tr(
            "donation_popup_body",
            "NetMon Roots wird mit viel Zeit, Leidenschaft und dem Ziel entwickelt, "
            "Linux-Nutzern ein leistungsstarkes und sicheres Werkzeug kostenlos zur "
            "Verfügung zu stellen.\n\n"
            "Gerade freie Software lebt von der Unterstützung ihrer Community. Hinter "
            "jedem neuen Feature, jedem Bugfix und jedem Test auf unterschiedlichen "
            "Linux-Distributionen steckt viel ehrenamtliche Entwicklungsarbeit.\n\n"
            "Wenn dir NetMon Roots gefällt und du das Projekt unterstützen möchtest, "
            "freue ich mich über eine freiwillige Spende von 5 € oder mehr.\n\n"
            "Mit deiner Unterstützung hilfst du dabei,\n\n"
            "- neue Funktionen zu entwickeln,\n"
            "- Fehler zu beheben,\n"
            "- NetMon auf weiteren Linux-Distributionen zu testen,\n"
            "- die Website und Infrastruktur zu betreiben und\n"
            "- das Projekt langfristig kostenlos für alle Linux-Nutzer\n"
            "  weiterzuentwickeln.\n\n"
            "Jeder Beitrag - egal in welcher Höhe - hilft dabei, freie Software "
            "lebendig zu halten.\n\n"
            "Vielen Dank für deine Unterstützung und dein Vertrauen in NetMon Roots!",
        )

    def show_donation_popup(self):
        if not bool(self.settings.get("donation_popup_enabled", True)):
            return
        existing = self.__dict__.get("donation_popup_window")
        if existing is not None:
            try:
                if existing.winfo_exists():
                    existing.lift()
                    existing.focus_force()
                    return
            except Exception:
                pass

        self._ensure_donation_popup_first_seen_at()
        window = tk.Toplevel(self)
        self.donation_popup_window = window
        window.title(
            self.tr(
                "donation_popup_title",
                "Unterstütze die Entwicklung von NetMon Roots",
            )
        )
        window.transient(self)
        window.geometry("620x520")
        window.minsize(520, 420)

        def _close():
            self.donation_popup_window = None
            try:
                window.destroy()
            except Exception:
                pass

        window.protocol("WM_DELETE_WINDOW", _close)

        container = ttk.Frame(window, padding=16)
        container.pack(fill="both", expand=True)
        ttk.Label(
            container,
            text=self.tr(
                "donation_popup_heading",
                "Unterstütze die Entwicklung von NetMon Roots",
            ),
            font=("TkDefaultFont", 13, "bold"),
            wraplength=560,
            justify="left",
        ).pack(anchor="w", pady=(0, 10))

        body = tk.Text(container, wrap="word", height=18, relief="flat")
        body.insert("1.0", self._donation_popup_body_text())
        body.configure(state="disabled")
        body.pack(fill="both", expand=True)

        ttk.Label(
            container,
            text=self.tr(
                "donation_popup_settings_hint",
                "Hinweis: Nach 7 Tagen kann dieser Start-Hinweis in den Einstellungen abgeschaltet werden.",
            ),
            wraplength=560,
            justify="left",
        ).pack(anchor="w", pady=(10, 0))

        actions = ttk.Frame(container)
        actions.pack(fill="x", pady=(14, 0))
        ttk.Button(
            actions,
            text=self.tr("donation_popup_paypal_placeholder", "PayPal folgt"),
            state="disabled",
        ).pack(side="left")
        ttk.Button(
            actions,
            text=self.tr("donation_popup_later", "Später erinnern"),
            command=_close,
        ).pack(side="right")

        self.settings["donation_popup_last_shown_at"] = int(time.time())
        self.save_settings(log_success=False)

