    def refresh_backup_overview(self):
        command, path = self._resolve_timeshift_launch_command()
        if command is not None:
            self.backup_timeshift_status_var.set(
                f"Timeshift: installiert ({path or command[0]})"
            )
        elif has_cmd("timeshift"):
            self.backup_timeshift_status_var.set(
                "Timeshift: CLI vorhanden, grafischer Launcher fehlt"
            )
        else:
            self.backup_timeshift_status_var.set("Timeshift: nicht installiert")

        if os.geteuid() == 0:
            self.backup_root_status_var.set("Root: aktiv")
        elif bool(getattr(self, "sudo_nopasswd", False)):
            self.backup_root_status_var.set("Root: sudo-Session aktiv")
        else:
            self.backup_root_status_var.set("Root: aktuell nicht aktiv")

        snapshot_dir = self._latest_timeshift_snapshot_directory()
        if snapshot_dir:
            try:
                stamp = datetime.fromtimestamp(os.path.getmtime(snapshot_dir)).strftime(
                    "%Y-%m-%d %H:%M:%S"
                )
            except Exception:
                stamp = "unbekannt"
            self.backup_last_snapshot_var.set(
                f"Letzter Snapshot: {stamp} ({os.path.basename(snapshot_dir)})"
            )
        else:
            self.backup_last_snapshot_var.set(
                "Letzter Snapshot: noch nicht automatisch erkannt"
            )

        backup_tool = self._resolve_data_backup_tool(restore=False)
        restore_tool = self._resolve_data_backup_tool(restore=True)
        if backup_tool is not None:
            label = str(backup_tool.get("label") or "Desktop-Backup-Tool").strip()
            self.backup_data_tool_status_var.set(f"Datensicherung: {label}")
            if restore_tool is not None and not bool(
                backup_tool.get("supports_restore_mode", False)
            ):
                self.backup_data_tool_hint_var.set(
                    f"Hinweis: {label} verwaltet Sicherung und Wiederherstellung im selben Fenster."
                )
            else:
                self.backup_data_tool_hint_var.set(
                    f"Hinweis: {label} wird direkt aus NetMon geöffnet."
                )
            self.backup_last_data_backup_var.set(
                "Letztes Datenbackup: wird vom Desktop-Tool selbst verwaltet"
            )
        else:
            self.backup_data_tool_status_var.set(
                "Datensicherung: kein unterstütztes Desktop-Tool erkannt"
            )
            self.backup_last_data_backup_var.set("Letztes Datenbackup: unbekannt")
            self.backup_data_tool_hint_var.set(
                "Hinweis: unterstützt werden aktuell Linux Mint Datensicherung und Deja Dup."
            )

        target_dir = self._security_baseline_transfer_directory()
        self.backup_target_status_var.set(f"NetMon-Transferordner: {target_dir}")
        usage_base = (
            target_dir if os.path.isdir(target_dir) else os.path.expanduser("~")
        )
        try:
            usage = shutil.disk_usage(usage_base)
            self.backup_free_space_var.set(f"Freier Speicher: {human_size(usage.free)}")
        except Exception:
            self.backup_free_space_var.set("Freier Speicher: unbekannt")

        loaded_transfer = bool(
            getattr(self, "security_baseline_transfer_package", None)
        )
        if loaded_transfer:
            source_path = str(
                getattr(self, "security_baseline_transfer_source_path", "") or ""
            ).strip()
            detail = f" ({os.path.basename(source_path)})" if source_path else ""
            self.backup_transfer_status_var.set(f"Transferpaket: geladen{detail}")
        else:
            self.backup_transfer_status_var.set("Transferpaket: keines geladen")
        self._update_netmon_backup_selection_summary()
        return True

    def check_timeshift_backup_status(self):
        self.refresh_backup_overview()
        status = self.backup_timeshift_status_var.get()
        snapshot = self.backup_last_snapshot_var.get()
        root_status = self.backup_root_status_var.get()
        message = "\n".join([status, snapshot, root_status])
        self.backup_status_var.set(f"Timeshift-Pruefung: {status}")
        self.log_safe(f"Timeshift-Pruefung im Backup-Tab: {status}")
        messagebox.showinfo(
            self.tr("backup_timeshift_check_title", "Timeshift pruefen"),
            message,
            parent=self,
        )
        return True

    def run_data_backup_async(self):
        if bool(getattr(self, "backup_data_running", False)):
            self.backup_status_var.set("Datenbackup laeuft bereits.")
            return False

        target_root = self._normalized_backup_data_target_dir()
        sources = self._selected_backup_source_entries()
        if not sources:
            messagebox.showinfo(
                self.tr("backup_run_title", "Komplettbackup starten"),
                self.tr(
                    "backup_no_sources",
                    "Es sind keine vorhandenen Quellordner fuer das Datenbackup ausgewaehlt.",
                ),
                parent=self,
            )
            self.backup_status_var.set("Datenbackup nicht gestartet: keine Quellen.")
            return False

        conflict = self._backup_target_conflict(target_root, sources)
        if conflict is not None:
            messagebox.showerror(
                self.tr("backup_run_title", "Komplettbackup starten"),
                self.tr(
                    "backup_target_conflict",
                    "Das Backup-Ziel liegt innerhalb eines zu sichernden Ordners.\n\nBitte ein anderes Ziel waehlen, damit keine Rekursion entsteht.",
                )
                + f"\n\n{conflict['label']}: {conflict['path']}\nZiel: {target_root}",
                parent=self,
            )
            self.backup_status_var.set(
                "Datenbackup blockiert: Ziel liegt innerhalb der Quellauswahl."
            )
            return False

        if not messagebox.askyesno(
            self.tr("backup_run_title", "Komplettbackup starten"),
            self.tr(
                "backup_run_confirm",
                "NetMon schreibt jetzt ein datiertes Komplettbackup der ausgewaehlten Benutzerordner.\n\nFortfahren?",
            )
            + "\n\n"
            + "\n".join(f"- {item['label']}: {item['path']}" for item in sources)
            + f"\n\nZiel: {target_root}",
            parent=self,
        ):
            self.backup_status_var.set("Datenbackup abgebrochen.")
            return False

        timestamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        backup_dir = os.path.join(target_root, f"netmon_fullbackup_{timestamp}")
        source_log = "\n".join(f"- {item['label']}: {item['path']}" for item in sources)
        self.backup_data_running = True
        self.backup_status_var.set("Datenbackup laeuft ...")
        self._append_backup_log(
            f"Backup gestartet: {runtime_log_timestamp()}\nZiel: {backup_dir}\nQuellen:\n{source_log}",
            clear=True,
        )

        def worker():
            copied = []
            errors = []
            try:
                os.makedirs(backup_dir, exist_ok=False)
                for item in sources:
                    source_path = item["path"]
                    label = item["label"]
                    target_name = os.path.basename(source_path.rstrip(os.sep)) or label
                    target_path = os.path.join(backup_dir, target_name)
                    if os.path.isdir(source_path):
                        shutil.copytree(
                            source_path,
                            target_path,
                            dirs_exist_ok=True,
                            symlinks=True,
                            copy_function=shutil.copy2,
                        )
                    else:
                        os.makedirs(os.path.dirname(target_path), exist_ok=True)
                        shutil.copy2(
                            source_path,
                            target_path,
                            follow_symlinks=False,
                        )
                    copied.append(
                        {"label": label, "source": source_path, "target": target_path}
                    )
                manifest = {
                    "created_at": datetime.now().isoformat(timespec="seconds"),
                    "target_dir": backup_dir,
                    "sources": copied,
                }
                manifest_path = os.path.join(backup_dir, "netmon_backup_manifest.json")
                ok, err = safe_write_json(
                    manifest_path,
                    manifest,
                    indent=2,
                    ensure_ascii=False,
                )
                if not ok:
                    errors.append(
                        str(err or "Manifest konnte nicht geschrieben werden.")
                    )
            except Exception as exc:
                errors.append(str(exc))

            def finish():
                self.backup_data_running = False
                if errors:
                    self.backup_status_var.set("Datenbackup fehlgeschlagen.")
                    self._append_backup_log(
                        "Backup fehlgeschlagen:\n"
                        + "\n".join(f"- {err}" for err in errors)
                    )
                    self.refresh_backup_overview()
                    return

                self.settings["backup_data_target_dir"] = target_root
                self.settings["backup_last_data_backup_path"] = backup_dir
                self.settings["backup_last_data_backup_at"] = datetime.now().isoformat(
                    timespec="seconds"
                )
                self.save_settings(log_success=False)
                self.backup_status_var.set(
                    f"Datenbackup abgeschlossen: {os.path.basename(backup_dir)}"
                )
                self._append_backup_log(
                    "Backup abgeschlossen:\n"
                    + f"- Ziel: {backup_dir}\n"
                    + f"- Bereiche: {len(copied)}\n"
                    + "\n".join(
                        f"- {item['label']} -> {item['target']}" for item in copied
                    )
                )
                self.refresh_backup_overview()

            self.after(0, finish)

        threading.Thread(target=worker, daemon=True).start()
        return True

    def verify_latest_data_backup(self):
        latest_backup = self._latest_data_backup_directory()
        if not latest_backup:
            messagebox.showinfo(
                self.tr("backup_verify_title", "Backup pruefen"),
                self.tr(
                    "backup_verify_missing",
                    "Es wurde noch kein Datenbackup gefunden.",
                ),
                parent=self,
            )
            self.backup_status_var.set("Backup-Pruefung: kein Datenbackup gefunden.")
            return False

        manifest_path = os.path.join(latest_backup, "netmon_backup_manifest.json")
        if not os.path.isfile(manifest_path):
            self.backup_status_var.set(
                "Backup-Pruefung: Manifest fehlt, Backup bitte manuell pruefen."
            )
            self._append_backup_log(
                f"Backup-Pruefung: Manifest fehlt in {latest_backup}"
            )
            messagebox.showwarning(
                self.tr("backup_verify_title", "Backup pruefen"),
                self.tr(
                    "backup_verify_manifest_missing",
                    "Das letzte Datenbackup wurde gefunden, aber die Manifest-Datei fehlt. Bitte den Ordner manuell pruefen.",
                )
                + f"\n\n{latest_backup}",
                parent=self,
            )
            self.refresh_backup_overview()
            return False

        try:
            with open(manifest_path, "r", encoding="utf-8") as handle:
                manifest = json.load(handle)
        except Exception as exc:
            self.backup_status_var.set("Backup-Pruefung fehlgeschlagen.")
            self._append_backup_log(f"Backup-Pruefung Fehler: {exc}")
            messagebox.showerror(
                self.tr("backup_verify_title", "Backup pruefen"),
                self.tr(
                    "backup_verify_failed",
                    "Das Backup konnte nicht gelesen werden.",
                )
                + f"\n\n{exc}",
                parent=self,
            )
            return False

        sources = list(manifest.get("sources") or [])
        summary_lines = [
            f"Backup geprueft: {runtime_log_timestamp()}",
            f"Ordner: {latest_backup}",
            f"Manifest: {manifest_path}",
            f"Bereiche: {len(sources)}",
        ]
        for item in sources:
            summary_lines.append(
                f"- {item.get('label', '-')}: {item.get('target', item.get('source', '-'))}"
            )
        self.backup_status_var.set(
            f"Backup geprueft: {os.path.basename(latest_backup)}"
        )
        self._append_backup_log("\n".join(summary_lines))
        self.refresh_backup_overview()
        return True

    def clear_download_scan_temp_folder(self):
        target = self._normalized_download_scan_temp_dir()
        removed = self._clear_download_scan_temp_contents(startup=False)
        self._refresh_download_scan_temp_security_status()
        self._set_download_scan_status(
            status="🟡 unchecked",
            result=self.tr(
                "download_scan_result_temp_folder_cleared",
                "Temp-Ordner geleert ({count})",
            ).format(count=removed),
            last_scan=self.tr("download_scan_last_scan_default", "Noch kein Scan"),
            log_message=self.tr(
                "download_scan_log_temp_folder_cleared",
                "Temp-Ordner geleert: {path} ({count} Einträge entfernt)",
            ).format(path=target, count=removed),
        )
        self._update_download_scan_result_text(
            self.tr(
                "download_scan_text_temp_folder_cleared",
                "Temp-Ordner geleert.\n\nZielpfad: {path}\nEntfernte Einträge: {count}\nDateien in diesem Bereich sind nur für temporäre Nutzung gedacht.",
            ).format(path=target, count=removed)
        )

    def choose_download_scan_file(self):
        self.prepare_download_scan_workspace(startup=False)
        initial_dir = self._normalized_download_scan_temp_dir()
        if not self._download_scan_path_is_accessible(initial_dir):
            self.create_download_scan_temp_folder()
            initial_dir = self._normalized_download_scan_temp_dir()
        if not self._download_scan_path_is_accessible(initial_dir):
            messagebox.showerror(
                self.tr("download_scan_dialog_title", "ClamAV download scan"),
                self.tr(
                    "download_scan_temp_path_inaccessible",
                    "The current pre-quarantine path is not accessible.\n\n"
                    "Path: {path}\n\n"
                    "Please enable pre-quarantine again or adjust the path.",
                ).format(path=initial_dir),
                parent=self,
            )
            return
        self.download_scan_selected_file = ""
        try:
            file_path = filedialog.askopenfilename(
                title=self.tr(
                    "download_scan_file_dialog_title",
                    "Choose file for download scan",
                ),
                initialdir=initial_dir,
            )
        except tk.TclError as exc:
            messagebox.showerror(
                self.tr("download_scan_dialog_title", "ClamAV download scan"),
                self.tr(
                    "download_scan_file_dialog_error",
                    "The file dialog could not open the current pre-quarantine path.\n\n"
                    "Path: {path}\n"
                    "Error: {error}",
                ).format(path=initial_dir, error=exc),
                parent=self,
            )
            return
        if not file_path:
            return
        normalized = os.path.abspath(os.path.expanduser(file_path))
        imported_from = ""
        try:
            normalized, imported_from = self._download_scan_import_file_to_temp(
                normalized
            )
        except Exception as exc:
            messagebox.showerror(
                self.tr("download_scan_dialog_title", "ClamAV Download-Scan"),
                self.tr(
                    "download_scan_import_failed",
                    "Die Datei konnte nicht in die Vor-Quarantäne kopiert werden.\n\n{error}",
                ).format(error=exc),
                parent=self,
            )
            return

        self.download_scan_selected_file = normalized
        result_lines = [
            self.tr("download_scan_file_selected", "Datei ausgewählt."),
            "",
            self.tr("download_scan_selected_file_line", "Datei: {path}").format(
                path=normalized
            ),
        ]
        log_message = f"Download scan file selected: {normalized}"
        if imported_from:
            result_lines.extend(
                [
                    self.tr(
                        "download_scan_imported_from_line",
                        "Importiert von: {path}",
                    ).format(path=imported_from),
                    "",
                    self.tr(
                        "download_scan_imported_into_prequarantine",
                        "Die Datei wurde zuerst in die Vor-Quarantäne kopiert.",
                    ),
                ]
            )
            log_message = (
                f"Download scan file copied into pre-quarantine: {imported_from} -> "
                f"{normalized}"
            )
        else:
            result_lines.append(
                self.tr(
                    "download_scan_already_in_prequarantine",
                    "Die Datei liegt bereits in der Vor-Quarantäne.",
                )
            )
        result_lines.extend(
            [
                "",
                self.tr(
                    "download_scan_result_text_default",
                    "Noch kein Scan durchgeführt.",
                ),
            ]
        )
        self._set_download_scan_status(
            status="🟡 unchecked",
            result=self.tr(
                "download_scan_result_selected_not_started",
                "Datei ausgewählt, Scan noch nicht gestartet",
            ),
            filename=os.path.basename(normalized),
            last_scan=self.tr("download_scan_last_scan_default", "Noch kein Scan"),
            log_message=log_message,
        )
        self._update_download_scan_result_text("\n".join(result_lines))

    def choose_and_scan_download_scan_file(self):
        self.choose_download_scan_file()
        selected = str(self.download_scan_selected_file or "").strip()
        if selected:
            self.scan_selected_download_scan_file()

    def _download_scan_clamav_available(self) -> bool:
        try:
            return bool(has_cmd("clamscan"))
        except Exception:
            return False

    def _download_scan_report_dir(self) -> str:
        return os.path.join(self._normalized_download_scan_temp_dir(), "reports")

    def _download_scan_report_path(self, scan_kind: str) -> str:
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        safe_kind = re.sub(r"[^a-zA-Z0-9_.-]", "_", scan_kind or "scan")
        return os.path.join(
            self._download_scan_report_dir(),
            f"netmon_download_scan_{safe_kind}_{stamp}.txt",
        )

    def _download_scan_write_report(self, scan_kind: str, report_text: str) -> str:
        if not bool(self.download_scan_save_report_var.get()):
            return ""
        try:
            report_dir = self._download_scan_report_dir()
            os.makedirs(report_dir, exist_ok=True)
            report_path = self._download_scan_report_path(scan_kind)
            with open(report_path, "w", encoding="utf-8") as handle:
                handle.write(report_text.rstrip() + "\n")
            return report_path
        except Exception as exc:
            self.log_debug_safe(f"Download scan report could not be saved: {exc}")
            return ""

    def _download_scan_confirm_move(
        self, source_path: str, destination_path: str
    ) -> bool:
        decision = {"value": False}
        done = threading.Event()

        def _ask():
            try:
                decision["value"] = bool(
                    messagebox.askyesno(
                        "Move file",
                        "ClamAV did not report a finding.\n\n"
                        f"File: {source_path}\n"
                        f"Target: {destination_path}\n\n"
                        "Move it to the target folder now?",
                        parent=self,
                    )
                )
            except Exception:
                decision["value"] = False
            finally:
                done.set()

        self.after(0, _ask)
        done.wait()
        return bool(decision["value"])

    def _download_scan_unique_destination(self, source_path: str) -> str:
        target_dir = self._normalized_download_scan_target_dir()
        os.makedirs(target_dir, exist_ok=True)
        base_name = os.path.basename(source_path.rstrip(os.sep)) or "download"
        stem, ext = os.path.splitext(base_name)
        candidate = os.path.join(target_dir, base_name)
        counter = 1
        while os.path.exists(candidate):
            candidate = os.path.join(target_dir, f"{stem}_{counter}{ext}")
            counter += 1
        return candidate

    def _download_scan_unique_temp_file_path(self, source_path: str) -> str:
        temp_dir = self._normalized_download_scan_temp_dir()
        os.makedirs(temp_dir, exist_ok=True)
        base_name = os.path.basename(source_path.rstrip(os.sep)) or "download"
        stem, ext = os.path.splitext(base_name)
        candidate = os.path.join(temp_dir, base_name)
        counter = 1
        while os.path.exists(candidate):
            candidate = os.path.join(temp_dir, f"{stem}_{counter}{ext}")
            counter += 1
        return candidate

    def _download_scan_import_file_to_temp(self, source_path: str) -> tuple[str, str]:
        normalized = os.path.abspath(os.path.expanduser(source_path or ""))
        temp_root = os.path.realpath(self._normalized_download_scan_temp_dir())
        source_real = os.path.realpath(normalized)
        if source_real == temp_root or source_real.startswith(temp_root + os.sep):
            return normalized, ""

        destination = self._download_scan_unique_temp_file_path(normalized)
        shutil.copy2(normalized, destination)
        try:
            os.chmod(destination, 0o600)
        except Exception:
            pass
        return destination, normalized

    def _download_scan_maybe_move_clean_file(self, source_path: str) -> str:
        if not source_path or not os.path.isfile(source_path):
            return ""
        temp_root = os.path.realpath(self._normalized_download_scan_temp_dir())
        source_real = os.path.realpath(source_path)
        if not source_real.startswith(temp_root + os.sep) and source_real != temp_root:
            self.log_safe(
                "Download scan: file remains in place because it is not in the temporary folder."
            )
            return ""
        auto_move = bool(self.download_scan_auto_move_var.get())
        ask_before_move = bool(self.download_scan_ask_before_move_var.get())
        if not auto_move and not ask_before_move:
            return ""

        destination = self._download_scan_unique_destination(source_path)
        should_move = auto_move
        if ask_before_move:
            should_move = self._download_scan_confirm_move(source_path, destination)
        if not should_move:
            return ""

        shutil.move(source_path, destination)
        self.log_safe(f"Download scan: file moved to {destination}")
        return destination

    def _run_download_scan(self, target_path: str, *, target_kind: str):
        normalized = os.path.abspath(os.path.expanduser(target_path or ""))
        if not normalized:
            messagebox.showinfo(
                self.tr("download_scan_dialog_title", "ClamAV Download-Scan"),
                self.tr(
                    "download_scan_select_target_first",
                    "Bitte zuerst eine Datei oder einen Ordner auswählen.",
                ),
                parent=self,
            )
            return
        if not os.path.exists(normalized):
            messagebox.showerror(
                self.tr("download_scan_dialog_title", "ClamAV Download-Scan"),
                self.tr(
                    "download_scan_path_not_found",
                    "Der Scan-Pfad wurde nicht gefunden:\n{path}",
                ).format(path=normalized),
                parent=self,
            )
            return
        if not self._download_scan_clamav_available():
            self._set_download_scan_status(
                status="🔴 finding / suspicious",
                result=self.tr(
                    "download_scan_result_clamav_unavailable",
                    "ClamAV nicht verfügbar",
                ),
                filename=os.path.basename(normalized),
                last_scan=datetime.now().strftime("%d.%m.%Y %H:%M"),
                log_message="Download scan not possible: clamscan is missing.",
            )
            self._update_download_scan_result_text(
                self.tr(
                    "download_scan_clamav_unavailable_text",
                    "ClamAV ist lokal nicht verfügbar.\n\n"
                    "Benötigt: clamscan\n"
                    "Empfehlung: sudo apt install clamav clamav-freshclam",
                )
            )
            return
        if self.security_clamav_running:
            messagebox.showinfo(
                self.tr("download_scan_dialog_title", "ClamAV Download-Scan"),
                self.tr(
                    "download_scan_already_running",
                    "Ein anderer ClamAV-Scan läuft bereits.",
                ),
                parent=self,
            )
            return

        scan_label = (
            self.tr(
                "download_scan_target_folder",
                "Ordner",
            )
            if os.path.isdir(normalized)
            else self.tr(
                "download_scan_target_file",
                "Datei",
            )
        )
        self.security_clamav_running = True
        self._set_download_scan_status(
            status="🟡 unchecked",
            result=self.tr(
                "download_scan_result_running",
                "ClamAV-Scan läuft",
            ),
            filename=os.path.basename(normalized),
            last_scan=datetime.now().strftime("%d.%m.%Y %H:%M"),
            log_message=f"Download scan started for {normalized}",
        )
        self._update_download_scan_result_text(
            self.tr(
                "download_scan_running_text",
                "ClamAV prüft gerade {target_type}...\n\nZiel: {target}",
            ).format(target_type=scan_label.lower(), target=normalized)
        )

        if os.path.isdir(normalized):
            self._clamav_progress_start()
        else:
            self._clamav_progress_start(expected_files=1)

        def job():
            moved_to = ""
            try:
                if os.path.isdir(normalized):
                    cmd = [
                        "clamscan",
                        *self._clamav_database_args(),
                        "-r",
                        "--infected",
                        normalized,
                    ]
                    rc, out, cancelled, timed_out, scanned = (
                        self._run_clamscan_with_progress(
                            cmd,
                            timeout=3600,
                            progress_cb=self._clamav_progress_update_safe,
                        )
                    )
                    if scanned:
                        self._clamav_progress_update_safe(scanned)
                else:
                    cmd = [
                        "clamscan",
                        *self._clamav_database_args(),
                        "--infected",
                        normalized,
                    ]
                    rc, out, cancelled = self._run_clamscan_with_cancel(
                        cmd,
                        timeout=900,
                    )
                    timed_out = False
                    self._clamav_progress_update_safe(1)

                timestamp = datetime.now()
                timestamp_log = timestamp.strftime("%Y-%m-%d %H:%M:%S")
                timestamp_ui = timestamp.strftime("%d.%m.%Y %H:%M")

                if cancelled:
                    self._set_download_scan_status(
                        status="🟡 unchecked",
                        result=self.tr(
                            "download_scan_result_cancelled",
                            "Scan abgebrochen",
                        ),
                        filename=os.path.basename(normalized),
                        last_scan=timestamp_ui,
                        log_message=f"Download scan cancelled: {normalized}",
                    )
                    self._update_download_scan_result_text(
                        self.tr(
                            "download_scan_cancelled_text",
                            "ClamAV-Scan wurde abgebrochen.\n\nZiel: {target}",
                        ).format(target=normalized)
                    )
                    return

                if timed_out:
                    self._set_download_scan_status(
                        status="🔴 finding / suspicious",
                        result=self.tr(
                            "download_scan_result_timeout",
                            "Scan-Zeitlimit erreicht",
                        ),
                        filename=os.path.basename(normalized),
                        last_scan=timestamp_ui,
                        log_message=f"Download scan time limit reached: {normalized}",
                    )
                    self._update_download_scan_result_text(
                        self.tr(
                            "download_scan_timeout_text",
                            "ClamAV-Scan wurde wegen Zeitlimit gestoppt.\n\nZiel: {target}",
                        ).format(target=normalized)
                    )
                    return

                infected_count = self._clamav_parse_infected_count(out)
                scanned_files = self._clamav_parse_scanned_files(out)
                if not isinstance(scanned_files, int):
                    scanned_files = scanned if os.path.isdir(normalized) else 1
                if isinstance(scanned_files, int) and scanned_files >= 0:
                    self._clamav_progress_update_safe(scanned_files)

                nonfatal_issue = rc == 2 and (
                    self._clamav_allows_nonfatal_scan_completion(out, scanned_files)
                )
                if rc not in (0, 1) and not nonfatal_issue:
                    error_line = self._clamav_extract_error_message(out)
                    self._set_download_scan_status(
                        status="🔴 finding / suspicious",
                        result=self.tr(
                            "download_scan_result_error",
                            "ClamAV-Fehler",
                        ),
                        filename=os.path.basename(normalized),
                        last_scan=timestamp_ui,
                        log_message=f"Download scan failed: {error_line or rc}",
                    )
                    self._update_download_scan_result_text(
                        self.tr(
                            "download_scan_error_text",
                            "ClamAV-Scan fehlgeschlagen.\n\n"
                            "Ziel: {target}\n"
                            "Fehler: {error}",
                        ).format(
                            target=normalized,
                            error=error_line
                            or self.tr(
                                "download_scan_error_return_code",
                                "Rückgabecode {rc}",
                            ).format(rc=rc),
                        )
                    )
                    return

                findings = self._clamav_extract_findings(
                    out,
                    scan_type=f"download_scan_{target_kind}",
                    timestamp=timestamp_log,
                )
                self._clamav_replace_open_findings(findings)

                result_text = (
                    self.tr("download_scan_result_clean", "sauber")
                    if infected_count == 0
                    else self.tr(
                        "download_scan_result_findings_count",
                        "{count} Fund(e)",
                    ).format(count=infected_count)
                )
                if nonfatal_issue and infected_count == 0:
                    result_text = self.tr(
                        "download_scan_result_clean_with_warnings",
                        "sauber (mit Zugriffswarnungen)",
                    )

                report_lines = [
                    self.tr(
                        "download_scan_report_title",
                        "NetMon Download-Scan / ClamAV",
                    ),
                    self.tr("download_scan_report_time", "Zeit: {value}").format(
                        value=timestamp_log
                    ),
                    self.tr(
                        "download_scan_report_target_type",
                        "Zieltyp: {value}",
                    ).format(value=target_kind),
                    self.tr("download_scan_report_target", "Ziel: {value}").format(
                        value=normalized
                    ),
                    self.tr(
                        "download_scan_report_scanned_files",
                        "Gesannte Dateien: {value}",
                    ).format(value=scanned_files if scanned_files is not None else "-"),
                    self.tr(
                        "download_scan_report_result",
                        "Ergebnis: {value}",
                    ).format(value=result_text),
                ]
                if findings:
                    report_lines.append(
                        self.tr("download_scan_report_findings", "Funde:")
                    )
                    report_lines.extend(
                        [
                            f"- {item.get('path', '-')}: {item.get('signature', '-')}"
                            for item in findings
                        ]
                    )
                else:
                    report_lines.append(
                        self.tr(
                            "download_scan_report_findings_none",
                            "Funde: keine",
                        )
                    )
                if out.strip():
                    report_lines.extend(
                        [
                            "",
                            self.tr(
                                "download_scan_report_clamav_output",
                                "ClamAV-Ausgabe:",
                            ),
                            out.strip(),
                        ]
                    )

                report_path = self._download_scan_write_report(
                    target_kind,
                    "\n".join(report_lines),
                )

                if infected_count == 0 and os.path.isfile(normalized):
                    try:
                        moved_to = self._download_scan_maybe_move_clean_file(normalized)
                    except Exception as exc:
                        self.log_safe(
                            f"Download scan: move after clean scan failed: {exc}"
                        )

                status_icon = (
                    "🟢 clean" if infected_count == 0 else "🔴 finding / suspicious"
                )
                summary = (
                    self.tr("download_scan_summary_clean", "Sauber")
                    if infected_count == 0
                    else self.tr(
                        "download_scan_summary_finding_count",
                        "Fund: {count}",
                    ).format(count=infected_count)
                )
                if nonfatal_issue and infected_count == 0:
                    summary = self.tr(
                        "download_scan_summary_clean_with_warnings",
                        "Sauber mit Warnungen",
                    )
                if moved_to:
                    summary += self.tr(
                        "download_scan_summary_and_moved",
                        " und verschoben",
                    )

                result_lines = [
                    self.tr(
                        "download_scan_result_scanned_with_clamav",
                        "{target_type} mit ClamAV geprüft.",
                    ).format(target_type=scan_label),
                    "",
                    self.tr("download_scan_result_target", "{label}: {value}").format(
                        label=scan_label,
                        value=normalized,
                    ),
                    self.tr(
                        "download_scan_result_scan_time",
                        "Scan-Zeit: {value}",
                    ).format(value=timestamp_log),
                    self.tr("download_scan_result_line", "Ergebnis: {value}").format(
                        value=result_text
                    ),
                ]
                if findings:
                    result_lines.append(
                        self.tr(
                            "download_scan_result_finding_name",
                            "Fundname:",
                        )
                    )
                    result_lines.extend(
                        [f"- {item.get('signature', '-')}" for item in findings]
                    )
                if moved_to:
                    result_lines.extend(
                        [
                            "",
                            self.tr(
                                "download_scan_result_moved_to",
                                "Verschoben nach: {path}",
                            ).format(path=moved_to),
                        ]
                    )
                if report_path:
                    result_lines.extend(
                        [
                            "",
                            self.tr(
                                "download_scan_result_report",
                                "Bericht: {path}",
                            ).format(path=report_path),
                        ]
                    )

                self._set_download_scan_status(
                    status=status_icon,
                    result=summary,
                    filename=os.path.basename(normalized),
                    last_scan=timestamp_ui,
                    log_message=f"Download scan completed: {normalized} | {summary}",
                )
                self._update_download_scan_result_text("\n".join(result_lines))
            finally:
                self.security_clamav_running = False
                self._clamav_progress_finish_safe()

        threading.Thread(target=job, daemon=True).start()

    def scan_download_scan_temp_folder(self):
        target = self._normalized_download_scan_temp_dir()
        if not os.path.isdir(target):
            self.create_download_scan_temp_folder()
        self._run_download_scan(target, target_kind="temp_folder")

    def scan_selected_download_scan_file(self):
        selected = str(self.download_scan_selected_file or "").strip()
        if not selected:
            messagebox.showinfo(
                "ClamAV Download-Scan",
                "Please select a file first.",
                parent=self,
            )
            return
        self._run_download_scan(selected, target_kind="file")

    def update_startup_vpn_profile_options(self):
        combo = self.__dict__.get("start_vpn_profile_combo")
        value_var = self.__dict__.get("var_start_vpn_profile")
        profiles = list(self.__dict__.get("wg_profiles", []) or [])
        current = ""
        if value_var is not None:
            try:
                current = str(value_var.get() or "").strip()
            except Exception:
                current = ""
        values = list(profiles)
        if current and current not in values:
            values.insert(0, current)
        if combo is not None:
            try:
                combo["values"] = values
            except Exception:
                pass
        self.on_start_network_mode_changed()

    def on_start_network_mode_changed(self):
        combo = self.__dict__.get("start_vpn_profile_combo")
        killswitch_cb = self.__dict__.get("cb_start_killswitch")
        dot_cb = self.__dict__.get("cb_start_dot")
        killswitch_var = self.__dict__.get("var_start_killswitch")
        dot_var = self.__dict__.get("var_start_dot")
        if killswitch_var is not None:
            try:
                killswitch_var.set(False)
            except Exception:
                pass
        if dot_var is not None:
            try:
                dot_var.set(False)
            except Exception:
                pass
        if combo is not None:
            try:
                combo.configure(state="disabled")
            except Exception:
                pass
        if killswitch_cb is not None:
            try:
                killswitch_cb.configure(state="disabled")
            except Exception:
                pass
        if dot_cb is not None:
            try:
                dot_cb.configure(state="disabled")
            except Exception:
                pass

    def apply_startup_settings(self):
        startup_theme = (
            str(
                self.settings.get("theme", self._preferred_theme_name or "dark")
                or "dark"
            )
            .strip()
            .lower()
            or "dark"
        )
        self.apply_theme(
            self._normalize_theme_name(startup_theme),
            log_change=False,
            persist=False,
        )

        if self.settings.get("auto_log_clear", False):
            self.after(10, self.clear_log)

        if self.settings.get("dns_guard_enabled", True):
            self.after(50, lambda: self.set_dns_guard_enabled(True))

        if self.settings.get("start_security_monitoring", False):
            self.after(150, self.security_start_monitoring)

        sudo_ready = check_sudo_nopasswd()

        ufw_logging_default = (
            str(self.settings.get("ufw_logging_default", "keep") or "keep")
            .strip()
            .lower()
        )
        if ufw_logging_default in {"off", "low", "high"}:
            if sudo_ready:
                self.after(
                    2000,
                    lambda level=ufw_logging_default: self.set_ufw_logging(level),
                )
            else:
                self.log_safe(
                    "Startup: UFW-Logging-Default übersprungen (sudo -n nicht verfügbar)."
                )

    def _vpn_runtime_active_for_startup_killswitch(self) -> bool:
        try:
            if self.get_wg_interfaces():
                return True
        except Exception as exc:
            self.log_debug_safe(f"Startup-Killswitch: WG-Prüfung fehlgeschlagen: {exc}")

        for provider in (
            vpn_controller.get_active_nm_wireguard_connections,
            vpn_controller.get_active_nm_vpn_connections,
        ):
            try:
                if provider(self):
                    return True
            except Exception as exc:
                self.log_debug_safe(
                    f"Startup-Killswitch: NetworkManager-Prüfung fehlgeschlagen: {exc}"
                )

        try:
            return bool(self.is_vpn_active())
        except Exception as exc:
            self.log_debug_safe(
                f"Startup-Killswitch: VPN-Prüfung fehlgeschlagen: {exc}"
            )
            return False

    def repair_orphaned_killswitch_on_startup(self) -> bool:
        if self._stealth_startup_enabled() or bool(
            self.__dict__.get("isp_stealth_running", False)
        ):
            return False
        if self._network_operation_active_elsewhere():
            self.log_debug_safe(
                "Startup-Killswitch: Bereinigung wegen laufender Netzwerkaktion übersprungen."
            )
            return False
        if not self.killswitch_is_on():
            return False
        if self._vpn_runtime_active_for_startup_killswitch():
            self.log_safe(
                "Startup: Killswitch bleibt aktiv, weil ein VPN-Tunnel erkannt wurde."
            )
            return False
        if not check_sudo_nopasswd():
            self.log_safe(
                "Startup: Verwaister Killswitch erkannt, automatische Deaktivierung "
                "ohne gültige Sudo-Sitzung nicht möglich."
            )
            return False

        self.log_safe(
            "Startup: Killswitch ohne aktives VPN erkannt - normales Routing wird wiederhergestellt."
        )
        return bool(
            self.killswitch_off(
                async_mode=False,
                ensure_sudo=False,
                refresh_ui=True,
                interactive_guard=False,
            )
        )

    def schedule_startup_killswitch_repair(self):
        if self._stealth_startup_enabled():
            return
        self.run_async(
            self.repair_orphaned_killswitch_on_startup,
            job_name="Startup-Killswitch prüfen",
        )

    def restart_netmon_with_network_reset(self):
        if not messagebox.askyesno(
            self.tr("netmon_restart_network_title", "NetMon Neustart"),
            self.tr(
                "netmon_restart_network_message",
                "NetMon wird neu gestartet.\n\n"
                "Zusätzlich werden systemd-resolved und NetworkManager neu gestartet.\n"
                "Die Netzwerkverbindung kann kurz abbrechen.\n\n"
                "Fortfahren?",
            ),
            parent=self,
        ):
            self.log_safe("NetMon Neustart + Netzwerk reset abgebrochen.")
            return False

        if not self.ensure_sudo_session("NetMon Neustart + Netzwerk reset"):
            return False

        def worker():
            if not self._try_begin_network_operation(
                "NetMon Neustart + Netzwerk reset"
            ):
                return
            try:
                self.log_safe("NetMon Neustart: Netzwerk-/Resolver-Reset gestartet...")

                commands = [
                    ["sudo", "-n", "systemctl", "restart", "systemd-resolved"],
                    ["sudo", "-n", "systemctl", "restart", "NetworkManager"],
                ]

                for cmd in commands:
                    rc, out = run_cmd(cmd, timeout=20)
                    self.log_safe(f"$ {' '.join(cmd)}")
                    if out:
                        self.log_safe(out)
                    if rc != 0:
                        self.log_safe(f"Warnung: Befehl fehlgeschlagen rc={rc}")

                self.log_safe("NetMon Neustart: DNS-Status wird neu geprüft...")
                dns_cmd = ["resolvectl", "status"]
                rc_dns, out_dns = run_cmd(dns_cmd, timeout=10)
                self.log_safe(f"$ {' '.join(dns_cmd)}")
                if out_dns:
                    self.log_safe(out_dns)
                if rc_dns != 0:
                    self.log_safe(
                        f"Warnung: DNS-Status konnte nicht gelesen werden rc={rc_dns}"
                    )

                self.log_safe("NetMon Neustart: kurzer Stabilisierungspuffer...")
                time.sleep(2)
                self.after(0, self.restart_netmon_process)
            finally:
                self._end_network_operation()

        self.run_async(worker, job_name="NetMon Neustart + Netzwerk reset")
        return True

    def reset_network_stack(self):
        if not messagebox.askyesno(
            self.tr("network_reset_title", "Network reset"),
            self.tr(
                "network_reset_message",
                "NetMon setzt jetzt WireGuard, systemd-resolved und NetworkManager zurück.\n\n"
                "Die Netzwerkverbindung kann kurz unterbrochen werden.\n\n"
                "Fortfahren?",
            ),
            parent=self,
        ):
            self.log_safe("Netzwerkreset abgebrochen.")
            return False

        if not self.ensure_sudo_session("Netzwerkreset"):
            return False

        def worker():
            if not self._try_begin_network_operation("Netzwerkreset"):
                return
            try:
                self.log_safe("Netzwerkreset gestartet...")
                cleanup_ok = self.cleanup_wireguard_interfaces()
                if not cleanup_ok:
                    self.log_safe(
                        "Netzwerkreset: WG Cleanup war nicht vollständig. Dienste werden trotzdem neu gestartet."
                    )

                commands = [
                    (
                        "Netzwerkreset: systemd-resolved restart",
                        ["sudo", "-n", "systemctl", "restart", "systemd-resolved"],
                        30,
                    ),
                    (
                        "Netzwerkreset: NetworkManager restart",
                        ["sudo", "-n", "systemctl", "restart", "NetworkManager"],
                        30,
                    ),
                ]
                for message, cmd, timeout in commands:
                    self.log_safe(message)
                    rc, out = run_cmd(cmd, timeout=timeout)
                    self.log_network_debug(f"[DEBUG] NET CMD -> {' '.join(cmd)}")
                    self.log_network_debug(f"[DEBUG] NET RC -> {rc}")
                    self.log_network_debug(
                        f"[DEBUG] NET OUT -> {(out or '').strip() or '-'}"
                    )
                    if rc != 0:
                        self.log_safe(
                            f"Warnung: {' '.join(cmd)} fehlgeschlagen (rc={rc})"
                        )
                        if out:
                            self.log_safe((out or "").strip())

                time.sleep(3)
                self.after(0, self.refresh_after_network_reset)
            finally:
                self._end_network_operation()

        self.run_async(worker, job_name="Netzwerkreset")
        return True

    def refresh_after_network_reset(self):
        self.log_safe("Netzwerkreset abgeschlossen. Aktualisiere Status...")
        try:
            self.refresh_safe()
        except Exception:
            pass

        try:
            self.resolved_status_async()
        except Exception:
            pass

        try:
            self.update_vpn_status_text()
        except Exception:
            pass

    def restart_netmon_only(self):
        if not messagebox.askyesno(
            self.tr("netmon_restart_only_title", "NetMon Neustart"),
            self.tr(
                "netmon_restart_only_message",
                "NetMon jetzt neu starten?",
            ),
            parent=self,
        ):
            self.log_safe("NetMon Neustart abgebrochen.")
            return False

        self.restart_netmon_process()
        return True

    def restart_netmon_process(self):
        try:
            self.log_safe("NetMon wird neu gestartet...")
        except Exception:
            pass

        try:
            self.stop_radio()
        except Exception:
            pass

        try:
            release_netmon_instance_lock()
        except Exception:
            pass

        python = sys.executable or shutil.which("python3") or "python3"
        current_argv = [arg for arg in sys.argv if arg is not None]
        if current_argv and current_argv[0]:
            argv = [python] + current_argv
        else:
            argv = [python, "-m", "netmon"]

        try:
            self.destroy()
        except Exception:
            pass

        os.execv(python, argv)

    def _read_text_widget_content(self, widget_name: str) -> str:
        widget = self.__dict__.get(widget_name)
        if widget is None:
            return ""
        try:
            return widget.get("1.0", "end").strip()
        except Exception:
            return ""

    def _selected_security_systemcheck_specs(self):
        specs = [
            {
                "enabled": bool(self.var_systemcheck_security_summary.get()),
                "title": "Security Monitoring Analyse",
                "runner": None,
                "collector": self._collect_security_summary_for_systemcheck,
                "wait": None,
            },
            {
                "enabled": bool(self.var_systemcheck_startup_guard.get()),
                "title": "Startup Guard Analyse",
                "runner": (
                    lambda: (
                        security_audit_controller.startup_guard_check(self)
                        if security_audit_controller is not None
                        else None
                    )
                ),
                "collector": self._collect_startup_guard_for_systemcheck,
                "wait": lambda: bool(getattr(self, "startup_guard_running", False)),
            },
            {
                "enabled": bool(self.var_systemcheck_path_guard.get()),
                "title": "PATH Guard Analyse",
                "runner": (
                    lambda: (
                        security_audit_controller.run_path_guard_check(self)
                        if security_audit_controller is not None
                        else None
                    )
                ),
                "collector": self._collect_path_guard_for_systemcheck,
                "wait": None,
            },
            {
                "enabled": bool(self.var_systemcheck_process_guard.get()),
                "title": "Process Guard Analyse",
                "runner": (
                    lambda: (
                        process_guard_controller.run_process_guard_check(self)
                        if process_guard_controller is not None
                        else None
                    )
                ),
                "collector": self._collect_process_guard_for_systemcheck,
                "wait": None,
            },
            {
                "enabled": bool(self.var_systemcheck_lynis.get()),
                "title": "Lynis Probleme Analyse",
                "runner": (
                    lambda: (
                        security_audit_controller.run_lynis_quick(self)
                        if security_audit_controller is not None
                        else None
                    )
                ),
                "collector": self._collect_lynis_for_systemcheck,
                "wait": lambda: bool(getattr(self, "lynis_running", False)),
            },
            {
                "enabled": bool(self.var_systemcheck_rkhunter.get()),
                "title": "rkhunter Analyse",
                "runner": self.rkhunter_scan_async,
                "collector": self._collect_rkhunter_for_systemcheck,
                "wait": lambda: bool(
                    getattr(self, "rkhunter_running", False)
                    or getattr(self, "rkhunter_updating", False)
                ),
                "availability": self._is_rkhunter_available_for_chad_systemcheck,
                "unavailable_text": self._missing_rkhunter_for_chad_systemcheck_message,
            },
            {
                "enabled": bool(self.var_systemcheck_clamav.get()),
                "title": "ClamAV Analyse",
                "runner": self.security_clamav_quickscan_async,
                "collector": self._collect_clamav_for_systemcheck,
                "wait": lambda: bool(getattr(self, "security_clamav_running", False)),
                "availability": self._is_clamav_available_for_chad_systemcheck,
                "unavailable_text": self._missing_clamav_for_chad_systemcheck_message,
            },
        ]
        return [spec for spec in specs if spec.get("enabled")]

    def _collect_security_summary_for_systemcheck(self) -> str:
        if security_monitoring_controller is not None:
            try:
                return security_monitoring_controller.build_security_chad_summary(self)
            except Exception:
                pass
        return "Keine Security-Zusammenfassung verfügbar."

    def _collect_startup_guard_for_systemcheck(self) -> str:
        result = getattr(self, "startup_guard_last_result", None) or {}
        if result and security_audit_controller is not None:
            try:
                count = len(getattr(self, "startup_guard_visible_entries", []) or [])
                return security_audit_controller.render_startup_guard_result(
                    self,
                    result,
                    count,
                )
            except Exception:
                pass
        text = self._read_text_widget_content("startup_guard_details_text")
        if text:
            return text
        return str(
            self.startup_guard_status_var.get()
            or "Startup Guard ohne Ergebnis beendet."
        )

    def _collect_path_guard_for_systemcheck(self) -> str:
        result = getattr(self, "path_guard_last_result", None)
        if result and security_audit_controller is not None:
            try:
                return security_audit_controller.format_path_guard_result(result)
            except Exception:
                pass
        return str(
            self.path_guard_status_var.get() or "PATH Guard ohne Ergebnis beendet."
        )

    def _collect_process_guard_for_systemcheck(self) -> str:
        result = getattr(self, "process_guard_last_result", None)
        if result and process_guard_controller is not None:
            try:
                return process_guard_controller.format_process_guard_result(result)
            except Exception:
                pass
        text = self._read_text_widget_content("process_guard_detail")
        if text:
            return text
        return str(
            self.process_guard_status_var.get()
            or "Process Guard ohne Ergebnis beendet."
        )

    def _collect_lynis_for_systemcheck(self) -> str:
        text = str(getattr(self, "lynis_last_output", "") or "").strip()
        if text and security_audit_controller is not None:
            try:
                filtered = (
                    security_audit_controller.extract_lynis_issues_and_recommendations(
                        text,
                        normalize_output_fn=normalize_lynis_output,
                    )
                )
                if filtered.strip():
                    return filtered
            except Exception:
                pass
        if text:
            return text
        widget_text = self._read_text_widget_content("lynis_text")
        if widget_text:
            return widget_text
        return str(self.lynis_summary_var.get() or "Lynis ohne Ergebnis beendet.")

    def _collect_rkhunter_for_systemcheck(self) -> str:
        text = self._read_text_widget_content("rkhunter_text")
        if text:
            return text
        return str(self.rkhunter_summary_var.get() or "rkhunter ohne Ergebnis beendet.")

    def _collect_clamav_for_systemcheck(self) -> str:
        snapshot = str(
            getattr(self, "security_clamav_last_systemcheck_text", "") or ""
        ).strip()
        if snapshot:
            return snapshot
        text = self._read_text_widget_content("clamav_output_text")
        if text:
            return text
        return "\n".join(
            [
                "=== ClamAV ===",
                f"Status: {self.clamav_status_var.get()}",
                f"Signaturen: {self.clamav_signatures_var.get()}",
                f"Letzter Scan: {self.clamav_last_scan_var.get()}",
                f"Ziel: {self.clamav_last_target_var.get()}",
                f"Funde: {self.clamav_findings_var.get()}",
                f"Ergebnis: {self.clamav_result_var.get()}",
            ]
        )

