    def run_selected_security_systemcheck(self):
        if self.security_systemcheck_running:
            self.security_systemcheck_status_var.set(
                self.tr(
                    "security_systemcheck_status_already_running",
                    "Security system check is already running.",
                )
            )
            return
        if not chad_controller.ensure_chad_enabled(
            self,
            "Enable Chad integration for the security system check.",
        ):
            self.security_systemcheck_status_var.set(
                self.tr(
                    "security_systemcheck_status_waiting_for_chad",
                    "Security system check is waiting for active Chad integration.",
                )
            )
            return
        service = self.ai_online_service
        if service is None or not service.is_available():
            self.security_systemcheck_status_var.set(
                self.tr(
                    "security_systemcheck_status_openai_not_ready",
                    "OpenAI connection is not ready. Please check the API key.",
                )
            )
            self.chad_analysis_status_var.set(
                self.tr(
                    "security_systemcheck_status_openai_not_ready",
                    "OpenAI connection is not ready. Please check the API key.",
                )
            )
            return
        self.refresh_chad_security_tools_status()
        specs = self._selected_security_systemcheck_specs()
        if not specs:
            self.security_systemcheck_status_var.set(
                self.tr(
                    "security_systemcheck_status_select_one",
                    "Please select at least one security area.",
                )
            )
            return
        self.security_systemcheck_running = True
        self.security_systemcheck_lock_chad_tab = True
        self.security_systemcheck_queue = list(specs)
        self.security_systemcheck_results = []
        self.security_systemcheck_collected_sections = []
        self.security_systemcheck_status_var.set(
            self.tr(
                "security_systemcheck_status_started",
                "Security system check started: {count} area(s).",
            ).format(count=len(specs))
        )
        try:
            self.nb.select(self.tab_chad_analysis)
        except Exception:
            pass
        self.append_to_chad_output(
            "Systemcheck",
            f"Security system check started. Selected areas: {len(specs)}",
        )
        self._run_next_security_systemcheck_step()

    def _run_next_security_systemcheck_step(self):
        if not self.security_systemcheck_queue:
            self.security_systemcheck_status_var.set(
                self.tr(
                    "security_systemcheck_status_building_summary",
                    "Security system check collected. Building Chad overall analysis...",
                )
            )
            self._send_security_systemcheck_summary_to_chad()
            return
        spec = self.security_systemcheck_queue.pop(0)
        title = str(spec.get("title") or "Security analysis")
        self.security_systemcheck_status_var.set(
            self.tr(
                "security_systemcheck_status_checking_now",
                "Checking now: {title}",
            ).format(title=title)
        )
        availability = spec.get("availability")
        try:
            available = bool(availability()) if callable(availability) else True
        except Exception:
            available = False
        if not available:
            unavailable_text = spec.get("unavailable_text")
            try:
                detail = (
                    unavailable_text()
                    if callable(unavailable_text)
                    else str(unavailable_text or "")
                )
            except Exception:
                detail = ""
            detail = (
                detail.strip()
                or f"{title} is not available locally and could not be started."
            )
            self._collect_security_systemcheck_result(title, detail, ok=False)
            self._send_security_systemcheck_result_to_chad(
                title,
                detail,
                done_callback=self._run_next_security_systemcheck_step,
            )
            return
        runner = spec.get("runner")
        try:
            if callable(runner):
                runner()
        except Exception as exc:
            self.log_safe(f"Security system check error in {title}: {exc}")
            self._collect_security_systemcheck_result(
                title,
                f"{title} could not be started. Error: {exc}",
                ok=False,
            )
            self.after(80, self._run_next_security_systemcheck_step)
            return
        wait = spec.get("wait")
        if callable(wait):
            self.after(
                700, lambda current=spec: self._poll_security_systemcheck_step(current)
            )
            return
        self.after(
            120, lambda current=spec: self._finish_security_systemcheck_step(current)
        )

    def _poll_security_systemcheck_step(self, spec):
        wait = spec.get("wait")
        try:
            still_running = bool(wait()) if callable(wait) else False
        except Exception:
            still_running = False
        if still_running:
            self.after(
                900, lambda current=spec: self._poll_security_systemcheck_step(current)
            )
            return
        self._finish_security_systemcheck_step(spec)

    def _finish_security_systemcheck_step(self, spec):
        title = str(spec.get("title") or "Security analysis")
        collector = spec.get("collector")
        try:
            raw_text = collector() if callable(collector) else ""
        except Exception as exc:
            raw_text = f"{title} could not be evaluated. Error: {exc}"
        raw_text = (
            str(raw_text or "").strip() or f"{title} did not return evaluable output."
        )
        self._collect_security_systemcheck_result(title, raw_text, ok=True)
        self.after(80, self._run_next_security_systemcheck_step)

    def _collect_security_systemcheck_result(self, title: str, raw_text: str, ok: bool):
        section = {
            "title": str(title or "Security analysis").strip() or "Security analysis",
            "text": str(raw_text or "").strip() or "No evaluable output.",
            "ok": bool(ok),
        }
        sections = self.__dict__.setdefault(
            "security_systemcheck_collected_sections", []
        )
        sections.append(section)
        results = self.__dict__.setdefault("security_systemcheck_results", [])
        results.append({"title": section["title"], "ok": bool(ok)})
        self.append_to_chad_output(
            f"Local scan: {section['title']}",
            section["text"],
        )

    def _build_security_systemcheck_summary_text(self) -> str:
        sections = list(
            self.__dict__.get("security_systemcheck_collected_sections", []) or []
        )
        if not sections:
            return "No security system check results collected."

        lines = [
            "=== Security System Check Overview ===",
            f"Total areas: {len(sections)}",
            f"Collected successfully: {sum(1 for item in sections if item.get('ok'))}",
            f"Collected with problems: {sum(1 for item in sections if not item.get('ok'))}",
        ]

        for section in sections:
            title = str(section.get("title") or "Security analysis").strip()
            text = str(section.get("text") or "").strip() or "No evaluable output."
            lines.extend(["", f"--- {title} ---", text])

        return "\n".join(lines).strip()

    def _send_security_systemcheck_summary_to_chad(self):
        sections = list(
            self.__dict__.get("security_systemcheck_collected_sections", []) or []
        )
        summary_text = self._build_security_systemcheck_summary_text()
        title = "Security system check overall analysis"
        prompt = chad_controller.build_chad_analysis_prompt(self, title, summary_text)
        self.chad_analysis_current_prompt = prompt
        self.chad_online_result = ""
        chad_analysis_source_var = self.__dict__.get("chad_analysis_source_var")
        if chad_analysis_source_var is not None:
            chad_analysis_source_var.set(
                f"{self.tr('chad_label_source_prefix', 'Source')}: {title}"
            )
        chad_analysis_status_var = self.__dict__.get("chad_analysis_status_var")
        if chad_analysis_status_var is not None:
            chad_analysis_status_var.set(
                self.tr(
                    "chad_status_analysis_prepared_for_title",
                    "{title}: analysis prepared.",
                ).format(title=title)
            )
        self.append_to_chad_output(title, prompt)
        chad_online_status_var = self.__dict__.get("chad_online_status_var")
        if chad_online_status_var is not None:
            chad_online_status_var.set(
                self.tr(
                    "chad_online_status_running_for_title",
                    "{title}: analysis running...",
                ).format(title=title)
            )
        service = self.__dict__.get("ai_online_service")

        def _finish_systemcheck(success: bool):
            completed = len(sections)
            self.security_systemcheck_lock_chad_tab = False
            self.security_systemcheck_running = False
            status_var = self.__dict__.get("security_systemcheck_status_var")
            if success:
                if status_var is not None:
                    status_var.set(
                        f"Security system check completed: collected {completed} area(s), created one Chad overall analysis."
                    )
                self.append_to_chad_output(
                    "Systemcheck",
                    f"Security system check completed. Collected areas: {completed}. Created one Chad overall analysis.",
                )
            else:
                if status_var is not None:
                    status_var.set(
                        f"Security system check completed: collected {completed} area(s), Chad overall analysis failed."
                    )

        if service is None or not service.is_available():
            if chad_online_status_var is not None:
                chad_online_status_var.set(
                    self.tr("chad_online_status_inactive", "Online analysis: inactive")
                )
            if chad_analysis_status_var is not None:
                chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_openai_connection_unavailable",
                        "OpenAI connection unavailable.",
                    )
                )
            self.after(0, lambda: _finish_systemcheck(False))
            return

        def worker():
            success, result = service.analyze(prompt, files=[])

            def update_ui():
                if success:
                    self.chad_online_result = result
                    self.append_to_chad_output(
                        chad_controller._format_chad_response_title(self, title),
                        result,
                    )
                    chad_controller.update_chad_summary_from_result(
                        self,
                        title,
                        result,
                    )
                    self.chad_online_status_var.set(
                        self.tr("chad_online_status_done", "Analysis completed.")
                    )
                else:
                    self.append_to_chad_output("Systemcheck", f"{title}: {result}")
                    chad_controller.update_chad_summary_from_result(
                        self,
                        title,
                        str(result),
                        status_override="Error",
                    )
                    self.chad_analysis_status_var.set(str(result))
                    self.chad_online_status_var.set(
                        self.tr("chad_online_status_error", "Error during analysis.")
                    )
                    chad_controller.log_chad_error(self, "Systemcheck", str(result))
                self.after(80, lambda current=success: _finish_systemcheck(current))

            self.after(0, update_ui)

        threading.Thread(target=worker, daemon=True).start()

    def _send_security_systemcheck_result_to_chad(
        self, title: str, raw_text: str, done_callback=None
    ):
        prompt = chad_controller.build_chad_analysis_prompt(self, title, raw_text)
        self.chad_analysis_current_prompt = prompt
        self.chad_online_result = ""
        self.chad_analysis_source_var.set(
            f"{self.tr('chad_label_source_prefix', 'Source')}: {title}"
        )
        self.chad_analysis_status_var.set(
            self.tr(
                "chad_status_analysis_prepared_for_title",
                "{title}: analysis prepared.",
            ).format(title=title)
        )
        self.append_to_chad_output(title, prompt)
        self.chad_online_status_var.set(
            self.tr(
                "chad_online_status_running_for_title",
                "{title}: analysis running...",
            ).format(title=title)
        )
        service = self.ai_online_service

        def _finish_next():
            if callable(done_callback):
                done_callback()

        if service is None or not service.is_available():
            self.chad_online_status_var.set(
                self.tr("chad_online_status_inactive", "Online analysis: inactive")
            )
            self.security_systemcheck_status_var.set(
                self.tr(
                    "chad_status_openai_connection_unavailable_for_title",
                    "{title}: OpenAI connection unavailable.",
                ).format(title=title)
            )
            self.after(0, _finish_next)
            return

        def worker():
            success, result = service.analyze(prompt, files=[])

            def update_ui():
                if success:
                    self.chad_online_result = result
                    self.append_to_chad_output(
                        chad_controller._format_chad_response_title(self, title),
                        result,
                    )
                    chad_controller.update_chad_summary_from_result(
                        self,
                        title,
                        result,
                    )
                    self.chad_online_status_var.set(
                        self.tr("chad_online_status_done", "Analysis completed.")
                    )
                    self.security_systemcheck_results.append(
                        {"title": title, "ok": True}
                    )
                else:
                    self.append_to_chad_output("Systemcheck", f"{title}: {result}")
                    chad_controller.update_chad_summary_from_result(
                        self,
                        title,
                        str(result),
                        status_override="Error",
                    )
                    self.chad_analysis_status_var.set(str(result))
                    self.chad_online_status_var.set(
                        self.tr("chad_online_status_error", "Error during analysis.")
                    )
                    self.security_systemcheck_results.append(
                        {"title": title, "ok": False}
                    )
                    chad_controller.log_chad_error(self, "Systemcheck", str(result))
                self.after(80, _finish_next)

            self.after(0, update_ui)

        threading.Thread(target=worker, daemon=True).start()

