    def choose_theme_studio_accent_color(self):
        chooser = colorchooser
        if chooser is None:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_colorchooser_missing",
                    "Farbauswahl nicht verfügbar. Tk colorchooser fehlt.",
                )
            )
            return
        initial = normalize_hex_color(self.var_theme_studio_accent.get()) or (
            self._get_theme(self.settings.get("theme", "light")).get("accent")
        )
        try:
            _rgb, selected = chooser.askcolor(
                color=initial,
                title=self.tr(
                    "theme_studio_accent_dialog_title",
                    "Theme Studio: Hauptfarbe wählen",
                ),
                parent=self,
            )
        except Exception as exc:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_colorchooser_error",
                    "Farbauswahl fehlgeschlagen: {error}",
                ).format(error=exc)
            )
            return
        color = normalize_hex_color(selected)
        if not color:
            return
        self.var_theme_studio_accent.set(color)
        self.refresh_theme_studio_preview()
        self.theme_studio_status_var.set(
            self.tr(
                "theme_studio_status_accent_selected",
                "Hauptfarbe ausgewählt: {color}",
            ).format(color=color)
        )

    def choose_theme_studio_panel_color(self):
        chooser = colorchooser
        if chooser is None:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_colorchooser_missing",
                    "Farbauswahl nicht verfügbar. Tk colorchooser fehlt.",
                )
            )
            return
        initial = normalize_hex_color(self.var_theme_studio_panel.get()) or (
            THEMES["pop"].get("panel_bg")
        )
        try:
            _rgb, selected = chooser.askcolor(
                color=initial,
                title=self.tr(
                    "theme_studio_panel_dialog_title",
                    "Theme Studio: Panelfarbe wählen",
                ),
                parent=self,
            )
        except Exception as exc:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_colorchooser_error",
                    "Farbauswahl fehlgeschlagen: {error}",
                ).format(error=exc)
            )
            return
        color = normalize_hex_color(selected)
        if not color:
            return
        self.var_theme_studio_panel.set(color)
        self.refresh_theme_studio_preview()
        self.theme_studio_status_var.set(
            self.tr(
                "theme_studio_status_panel_selected",
                "Panelfarbe ausgewählt: {color}",
            ).format(color=color)
        )

    def set_theme_studio_accent_preset(self, color):
        normalized = normalize_hex_color(color)
        if not normalized:
            return
        self.var_theme_studio_accent.set(normalized)
        self.refresh_theme_studio_preview()
        self.theme_studio_status_var.set(
            self.tr(
                "theme_studio_status_preset_loaded",
                "Preset geladen: {color}",
            ).format(color=normalized)
        )

    def set_theme_studio_panel_preset(self, color):
        normalized = normalize_hex_color(color)
        if not normalized:
            return
        self.var_theme_studio_panel.set(normalized)
        self.refresh_theme_studio_preview()
        self.theme_studio_status_var.set(
            self.tr(
                "theme_studio_status_panel_preset_loaded",
                "Panel-Preset geladen: {color}",
            ).format(color=normalized)
        )

    def _get_theme_studio_preview_theme(self):
        accent = normalize_hex_color(self.var_theme_studio_accent.get())
        panel = normalize_hex_color(self.var_theme_studio_panel.get())
        style = self._normalize_theme_studio_style(self.var_theme_studio_style.get())
        return self._compose_theme(
            "pop",
            accent_override=accent,
            panel_override=panel,
            style_mode=style,
        )

    def refresh_theme_studio_preview(self):
        frame = self.__dict__.get("theme_studio_preview_shell")
        if frame is None:
            return
        theme = self._get_theme_studio_preview_theme()
        accent_text = (
            normalize_hex_color(self.var_theme_studio_accent.get()) or theme["accent"]
        )
        panel_text = (
            normalize_hex_color(self.var_theme_studio_panel.get()) or theme["panel_bg"]
        )

        try:
            frame.configure(
                bg=theme["panel_bg"],
                highlightbackground=theme["border"],
                highlightcolor=theme["border"],
            )
        except Exception:
            pass

        widget_colors = {
            "theme_studio_preview_title": {
                "bg": theme["panel_bg"],
                "fg": theme["fg"],
            },
            "theme_studio_preview_subtitle": {
                "bg": theme["panel_bg"],
                "fg": theme["muted_fg"],
            },
            "theme_studio_preview_tab_active": {
                "bg": theme["tab_selected_bg"],
                "fg": theme["tab_selected_fg"],
            },
            "theme_studio_preview_tab_idle": {
                "bg": theme["tab_bg"],
                "fg": theme["tab_fg"],
            },
            "theme_studio_preview_button": {
                "bg": theme["tab_bg"],
                "fg": theme["fg"],
                "activebackground": theme["tab_selected_bg"],
                "activeforeground": theme["tab_selected_fg"],
            },
            "theme_studio_preview_entry": {
                "bg": theme["entry_bg"],
                "fg": theme["entry_fg"],
                "insertbackground": theme["entry_fg"],
            },
            "theme_studio_preview_log": {
                "bg": theme["text_bg"],
                "fg": theme["text_fg"],
            },
            "theme_studio_preview_status_ok": {
                "bg": theme["panel_bg"],
                "fg": theme["success"],
            },
            "theme_studio_preview_status_warn": {
                "bg": theme["panel_bg"],
                "fg": theme["warning"],
            },
            "theme_studio_preview_status_err": {
                "bg": theme["panel_bg"],
                "fg": theme["error"],
            },
            "theme_studio_preview_meta": {
                "bg": theme["panel_bg"],
                "fg": theme["fg"],
            },
        }
        for widget_name, colors in widget_colors.items():
            widget = self.__dict__.get(widget_name)
            if widget is None:
                continue
            try:
                widget.configure(**colors)
            except Exception:
                pass

        swatches = {
            "theme_studio_swatch_accent": accent_text,
            "theme_studio_swatch_panel": theme["panel_bg"],
            "theme_studio_swatch_border": theme["border"],
            "theme_studio_swatch_log": theme["text_bg"],
        }
        for widget_name, color in swatches.items():
            widget = self.__dict__.get(widget_name)
            if widget is None:
                continue
            try:
                widget.configure(bg=color, highlightbackground=theme["border"])
            except Exception:
                pass

        status = self.__dict__.get("theme_studio_preview_status_line")
        if status is not None:
            try:
                status.configure(
                    text=(
                        f"Basis: {self._get_theme_display_name(theme['name'])} | "
                        f"Akzent: {accent_text} | Panel: {panel_text} | Stil: {self.var_theme_studio_style.get()}"
                    )
                )
            except Exception:
                pass
        meta = self.__dict__.get("theme_studio_preview_meta")
        if meta is not None:
            try:
                meta.configure(
                    text=self.tr(
                        "theme_studio_preview_profile_value",
                        "Profile: {profile}",
                    ).format(
                        profile=(
                            str(self.var_theme_studio_profile_name.get() or "").strip()
                            or self.tr(
                                "theme_studio_default_profile_name",
                                "My Theme",
                            )
                        )
                    )
                )
            except Exception:
                pass

    def _theme_studio_profiles_dir(self):
        return os.path.join(get_netmon_documents_dir(), "ThemeStudio")

    def _ensure_theme_studio_profiles_dir(self):
        folder = self._theme_studio_profiles_dir()
        os.makedirs(folder, exist_ok=True)
        return folder

    def _theme_studio_profile_filename(self, profile_name):
        text = str(profile_name or "").strip() or "mein-theme"
        slug = re.sub(r"[^a-zA-Z0-9._-]+", "-", text).strip("-_.").lower()
        if not slug:
            slug = "mein-theme"
        if not slug.endswith(".json"):
            slug = f"{slug}.json"
        return slug

    def _theme_studio_form_payload(self):
        accent_text = str(self.var_theme_studio_accent.get() or "").strip()
        accent = normalize_hex_color(accent_text)
        if accent_text and not accent:
            return None, "Bitte eine gültige Hex-Farbe wie #58a6ff eintragen."
        panel_text = str(self.var_theme_studio_panel.get() or "").strip()
        panel = normalize_hex_color(panel_text)
        if panel_text and not panel:
            return (
                None,
                "Bitte für die Panelfarbe eine gültige Hex-Farbe wie #fff4ef eintragen.",
            )
        style = self._normalize_theme_studio_style(self.var_theme_studio_style.get())
        profile_name = str(self.var_theme_studio_profile_name.get() or "").strip()
        if not profile_name:
            profile_name = self.tr("theme_studio_default_profile_name", "My Theme")
            self.var_theme_studio_profile_name.set(profile_name)
        return {
            "kind": "netmon_theme_studio_profile",
            "version": 1,
            "theme": "pop",
            "profile_name": profile_name,
            "accent": accent or "",
            "panel": panel or "",
            "style": style,
            "saved_at": datetime.now().isoformat(timespec="seconds"),
        }, ""

    def apply_theme_studio_settings(self):
        payload, error = self._theme_studio_form_payload()
        if payload is None:
            self.theme_studio_status_var.set(error)
            return
        base_name = "pop"
        accent = str(payload.get("accent", "") or "")
        panel = str(payload.get("panel", "") or "")
        style = str(payload.get("style", "dezent") or "dezent")
        profile_name = str(
            payload.get(
                "profile_name",
                self.tr("theme_studio_default_profile_name", "My Theme"),
            )
            or self.tr("theme_studio_default_profile_name", "My Theme")
        )

        self.settings["theme"] = base_name
        self.settings["theme_custom_accent"] = accent
        self.settings["theme_custom_panel_bg"] = panel
        self.settings["theme_custom_style"] = style
        self.settings["theme_custom_profile_name"] = profile_name
        self.var_theme_choice.set(self._get_theme_display_name(base_name))
        self.var_theme_studio_base_theme.set(self._get_theme_display_name(base_name))
        self._preferred_theme_name = base_name

        self.apply_theme(base_name, log_change=True, persist=False)
        self.save_settings(log_success=False)
        if "privacy_config" in self.__dict__:
            self.save_privacy_config()

        accent_info = accent or "Theme-Standard"
        panel_info = panel or "Pop-Standard"
        self.theme_studio_status_var.set(
            f"Pop-Profil angewendet: {profile_name} | Button: {accent_info} | Panel: {panel_info} | {style}"
        )
        self.log(
            f"Theme Studio angewendet: Basis=pop, Akzent={accent_info}, Panel={panel_info}, Stil={style}"
        )

    def save_theme_studio_profile(self):
        if filedialog is None:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_save_unavailable",
                    "Speichern nicht verfügbar. Tk filedialog fehlt.",
                )
            )
            return False
        payload, error = self._theme_studio_form_payload()
        if payload is None:
            self.theme_studio_status_var.set(error)
            return False
        try:
            folder = self._ensure_theme_studio_profiles_dir()
        except Exception as exc:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_folder_error",
                    "Theme-Ordner fehlgeschlagen: {error}",
                ).format(error=exc)
            )
            return False
        try:
            file_path = filedialog.asksaveasfilename(
                parent=self,
                title=self.tr(
                    "theme_studio_save_dialog_title",
                    "Theme Studio: Theme speichern",
                ),
                initialdir=folder,
                initialfile=self._theme_studio_profile_filename(
                    payload.get("profile_name", "mein-theme")
                ),
                defaultextension=".json",
                filetypes=[("NetMon Theme", "*.json"), ("JSON", "*.json")],
            )
        except Exception as exc:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_save_dialog_error",
                    "Speicherdialog fehlgeschlagen: {error}",
                ).format(error=exc)
            )
            return False
        if not file_path:
            return False
        try:
            os.makedirs(os.path.dirname(file_path), exist_ok=True)
            with open(file_path, "w", encoding="utf-8") as handle:
                json.dump(payload, handle, ensure_ascii=False, indent=2)
        except Exception as exc:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_save_error",
                    "Theme speichern fehlgeschlagen: {error}",
                ).format(error=exc)
            )
            return False
        profile_name = str(
            payload.get(
                "profile_name",
                self.tr("theme_studio_default_profile_name", "My Theme"),
            )
            or self.tr("theme_studio_default_profile_name", "My Theme")
        )
        self.theme_studio_status_var.set(
            self.tr(
                "theme_studio_status_saved",
                "Theme gespeichert: {profile} | {filename}",
            ).format(profile=profile_name, filename=os.path.basename(file_path))
        )
        self.log(f"Theme Studio gespeichert: {file_path}")
        return True

    def load_theme_studio_profile(self):
        if filedialog is None:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_load_unavailable",
                    "Laden nicht verfügbar. Tk filedialog fehlt.",
                )
            )
            return False
        try:
            folder = self._ensure_theme_studio_profiles_dir()
        except Exception as exc:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_folder_error",
                    "Theme-Ordner fehlgeschlagen: {error}",
                ).format(error=exc)
            )
            return False
        try:
            file_path = filedialog.askopenfilename(
                parent=self,
                title=self.tr(
                    "theme_studio_load_dialog_title",
                    "Theme Studio: Theme laden",
                ),
                initialdir=folder,
                filetypes=[("NetMon Theme", "*.json"), ("JSON", "*.json")],
            )
        except Exception as exc:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_load_dialog_error",
                    "Ladedialog fehlgeschlagen: {error}",
                ).format(error=exc)
            )
            return False
        if not file_path:
            return False
        try:
            with open(file_path, "r", encoding="utf-8") as handle:
                payload = json.load(handle)
        except Exception as exc:
            self.theme_studio_status_var.set(
                self.tr(
                    "theme_studio_status_load_error",
                    "Theme laden fehlgeschlagen: {error}",
                ).format(error=exc)
            )
            return False
        if not isinstance(payload, dict):
            self.theme_studio_status_var.set(
                self.tr("theme_studio_status_invalid_file", "Theme file is invalid.")
            )
            return False
        profile_name = str(
            payload.get(
                "profile_name",
                self.tr("theme_studio_default_profile_name", "My Theme"),
            )
            or ""
        ).strip()
        accent = normalize_hex_color(payload.get("accent", "")) or ""
        panel = normalize_hex_color(payload.get("panel", "")) or ""
        style = self._normalize_theme_studio_style(payload.get("style", "dezent"))
        self.var_theme_studio_base_theme.set(self._get_theme_display_name("pop"))
        self.var_theme_studio_profile_name.set(
            profile_name or self.tr("theme_studio_default_profile_name", "My Theme")
        )
        self.var_theme_studio_accent.set(accent)
        self.var_theme_studio_panel.set(panel)
        self.var_theme_studio_style.set(style)
        self.refresh_theme_studio_preview()
        self.apply_theme_studio_settings()
        self.theme_studio_status_var.set(
            self.tr(
                "theme_studio_status_loaded_into_pop",
                "Theme geladen und in Pop eingespielt: {profile}",
            ).format(profile=self.var_theme_studio_profile_name.get())
        )
        self.log(f"Theme Studio geladen: {file_path}")
        return True

    def load_theme_studio_from_current_theme(self):
        self.var_theme_studio_base_theme.set(self._get_theme_display_name("pop"))
        self.var_theme_studio_accent.set(
            str(self.settings.get("theme_custom_accent", "") or "").strip()
        )
        self.var_theme_studio_panel.set(
            str(self.settings.get("theme_custom_panel_bg", "") or "").strip()
        )
        self.var_theme_studio_style.set(
            self._normalize_theme_studio_style(
                self.settings.get("theme_custom_style", "dezent")
            )
        )
        self.var_theme_studio_profile_name.set(
            str(
                self.settings.get(
                    "theme_custom_profile_name",
                    self.tr("theme_studio_default_profile_name", "My Theme"),
                )
                or ""
            ).strip()
            or self.tr("theme_studio_default_profile_name", "My Theme")
        )
        self.refresh_theme_studio_preview()
        self.theme_studio_status_var.set(
            self.tr(
                "theme_studio_status_pop_loaded",
                "Pop-Profil in Theme Studio geladen.",
            )
        )

    def reset_theme_studio_settings(self):
        defaults = self._default_settings_payload()
        self.var_theme_studio_base_theme.set(self._get_theme_display_name("pop"))
        self.var_theme_studio_accent.set(
            str(defaults.get("theme_custom_accent", "") or "")
        )
        self.var_theme_studio_panel.set(
            str(defaults.get("theme_custom_panel_bg", "") or "")
        )
        self.var_theme_studio_style.set(
            self._normalize_theme_studio_style(
                defaults.get("theme_custom_style", "dezent")
            )
        )
        self.var_theme_studio_profile_name.set(
            str(
                defaults.get(
                    "theme_custom_profile_name",
                    self.tr("theme_studio_default_profile_name", "My Theme"),
                )
                or self.tr("theme_studio_default_profile_name", "My Theme")
            )
        )
        self.apply_theme_studio_settings()
        self.theme_studio_status_var.set(
            self.tr(
                "theme_studio_status_pop_reset",
                "Pop-Profil auf Standard zurückgesetzt.",
            )
        )

