    def _update_packet_capture_disabled_notice(self, wireshark_available: bool):
        text_widget = self.__dict__.get("packet_capture_text")
        if text_widget is None:
            return
        if wireshark_available:
            message = self.tr(
                "packet_capture_output_default",
                "Packet capture status and file information will appear here.\n",
            )
        else:
            message = self._packet_capture_install_required_message()
        try:
            text_widget.configure(state="normal")
            text_widget.delete("1.0", "end")
            text_widget.insert("1.0", message)
            text_widget.configure(state="disabled")
        except Exception:
            pass

    def refresh_wireshark_launch_controls(self):
        dep_status = self.__dict__.get("dep_status", {}) or {}
        wireshark_available = bool(dep_status.get("wireshark", False))
        packet_capture_ready = bool(
            dep_status.get("tshark", False) or dep_status.get("dumpcap", False)
        )
        packet_capture_ui_ready = bool(dep_status.get("ip", False))
        blocked = bool(self.settings.get("wireshark_launch_blocked", False))
        all_buttons = (
            "btn_packet_capture_refresh",
            "btn_packet_capture_choose",
            "btn_packet_capture_start",
            "btn_packet_capture_stop",
            "btn_packet_capture_open_wireshark",
            "btn_packet_capture_open_file",
            "btn_packet_capture_info",
        )
        action_buttons = (
            "btn_packet_capture_start",
            "btn_packet_capture_stop",
            "btn_packet_capture_open_wireshark",
            "btn_packet_capture_open_file",
            "btn_packet_capture_info",
        )
        interface_combo = self.__dict__.get("packet_capture_interface_combo")
        if not wireshark_available:
            for name in all_buttons:
                button = self.__dict__.get(name)
                if button is None:
                    continue
                try:
                    button.configure(state="disabled")
                except Exception:
                    pass
            if interface_combo is not None:
                try:
                    interface_combo.configure(state="disabled")
                except Exception:
                    pass
            self._update_packet_capture_disabled_notice(False)
            try:
                self.packet_capture_status_var.set(
                    self.tr(
                        "packet_capture_status_install_required", "Wireshark missing"
                    )
                )
                self.packet_capture_runtime_var.set("-")
                self.packet_capture_packets_var.set("-")
                self.packet_capture_size_var.set("-")
            except Exception:
                pass
            return
        if blocked:
            for name in action_buttons:
                button = self.__dict__.get(name)
                if button is None:
                    continue
                try:
                    button.configure(state="disabled")
                except Exception:
                    pass
            if interface_combo is not None:
                try:
                    interface_combo.configure(state="readonly")
                except Exception:
                    pass
            self._update_packet_capture_disabled_notice(True)
            return

        if packet_capture_controller is not None:
            try:
                packet_capture_controller.packet_capture_set_running_state(
                    self,
                    bool(getattr(self, "packet_capture_running", False)),
                )
            except Exception:
                pass

        refresh_button = self.__dict__.get("btn_packet_capture_refresh")
        if refresh_button is not None:
            try:
                refresh_button.configure(
                    state="normal" if packet_capture_ui_ready else "disabled"
                )
            except Exception:
                pass

        choose_button = self.__dict__.get("btn_packet_capture_choose")
        if choose_button is not None:
            try:
                choose_button.configure(
                    state="normal" if packet_capture_ui_ready else "disabled"
                )
            except Exception:
                pass

        if interface_combo is not None:
            try:
                interface_combo.configure(
                    state="readonly" if packet_capture_ui_ready else "disabled"
                )
            except Exception:
                pass

        open_wireshark_button = self.__dict__.get("btn_packet_capture_open_wireshark")
        if open_wireshark_button is not None:
            try:
                open_wireshark_button.configure(
                    state="normal" if wireshark_available else "disabled"
                )
            except Exception:
                pass

        open_file_button = self.__dict__.get("btn_packet_capture_open_file")
        if open_file_button is not None:
            try:
                open_file_button.configure(
                    state="normal" if packet_capture_ready else "disabled"
                )
            except Exception:
                pass

        info_button = self.__dict__.get("btn_packet_capture_info")
        if info_button is not None:
            try:
                info_button.configure(
                    state="normal" if packet_capture_ui_ready else "disabled"
                )
            except Exception:
                pass
        self._update_packet_capture_disabled_notice(True)

    def on_wireshark_launch_block_toggle(self):
        blocked = bool(self.var_wireshark_launch_blocked.get())
        self.settings["wireshark_launch_blocked"] = blocked
        self.refresh_wireshark_launch_controls()
        self.save_settings(log_success=False)
        try:
            self.log(
                "Wireshark launch in NetMon blocked."
                if blocked
                else "Wireshark launch in NetMon enabled again."
            )
        except Exception:
            pass

