    def copy_treeview_selection_to_clipboard(self, table):
        if table is None:
            return
        try:
            selection = list(table.selection())
        except Exception:
            selection = []
        if not selection:
            return
        lines = []
        for item_id in selection:
            try:
                values = list(table.item(item_id, "values") or [])
            except Exception:
                values = []
            row = " | ".join(str(value or "").strip() for value in values).strip()
            if row:
                lines.append(row)
        if not lines:
            return
        self.clipboard_clear()
        self.clipboard_append("\n".join(lines))

    def select_all_treeview_rows(self, table):
        if table is None:
            return
        try:
            rows = list(table.get_children())
        except Exception:
            rows = []
        if not rows:
            return
        try:
            table.selection_set(rows)
            table.focus(rows[0])
        except Exception:
            pass

    def _prepare_context_menu_tree_selection(self, table, row_id: str) -> bool:
        if table is None:
            return False
        normalized_row_id = str(row_id or "").strip()
        try:
            current_selection = tuple(table.selection())
        except Exception:
            current_selection = ()
        if not normalized_row_id:
            try:
                if current_selection:
                    table.selection_remove(current_selection)
            except Exception:
                pass
            try:
                table.focus("")
            except Exception:
                pass
            return False
        if normalized_row_id in current_selection:
            try:
                table.focus(normalized_row_id)
            except Exception:
                pass
            return True
        try:
            table.selection_set(normalized_row_id)
            table.focus(normalized_row_id)
            return True
        except Exception:
            return False

    def attach_simple_tree_context_menu(self, table):
        if table is None:
            return

        attached = self.__dict__.setdefault("_simple_tree_context_menu_attached", set())
        widget_id = str(table)
        if widget_id in attached:
            return
        attached.add(widget_id)

        self.attach_selection_copy_shortcuts(table, "treeview")
        menu = tk.Menu(table, tearoff=0)
        menu.add_command(
            label=self.tr("menu_copy", "Kopieren"),
            command=lambda: self.copy_treeview_selection_to_clipboard(table),
        )
        menu.add_command(
            label=self.tr("menu_select_all", "Alles auswählen"),
            command=lambda: self.select_all_treeview_rows(table),
        )
        remove_rule_entry_index = None
        delete_vpn_profile_entry_index = None
        if table is self.__dict__.get("firewall_rules_table"):
            menu.add_separator()
            menu.add_command(
                label=self.tr("menu_remove_rule", "Regel entfernen"),
                command=self.remove_selected_firewall_rule,
            )
            try:
                remove_rule_entry_index = menu.index("end")
            except Exception:
                remove_rule_entry_index = None
        elif table is self.__dict__.get("vpn_table"):
            menu.add_separator()

            def delete_selected_vpn_profile_from_table():
                try:
                    self.on_vpn_table_select()
                except Exception:
                    pass
                self.delete_selected_vpn_profile()

            menu.add_command(
                label=self.tr("menu_delete_profile", "Profil löschen"),
                command=delete_selected_vpn_profile_from_table,
            )
            try:
                delete_vpn_profile_entry_index = menu.index("end")
            except Exception:
                delete_vpn_profile_entry_index = None

        def show_menu(event):
            row_id = ""
            try:
                row_id = str(table.identify_row(event.y) or "")
            except Exception:
                row_id = ""
            self._prepare_context_menu_tree_selection(table, row_id)
            if remove_rule_entry_index is not None:
                try:
                    has_selection = bool(table.selection())
                    menu.entryconfigure(
                        remove_rule_entry_index,
                        state=("normal" if has_selection else "disabled"),
                    )
                except Exception:
                    pass
            if delete_vpn_profile_entry_index is not None:
                try:
                    has_selection = bool(table.selection())
                    menu.entryconfigure(
                        delete_vpn_profile_entry_index,
                        state=("normal" if has_selection else "disabled"),
                    )
                except Exception:
                    pass
            return self._show_context_menu(menu, event)

        table.bind("<Button-3>", show_menu, add="+")
        table._simple_context_menu = menu

    def get_security_events_analysis_text(self) -> str:
        table = self.__dict__.get("security_table")
        if table is None:
            return ""

        selection = list(table.selection())
        target_items = selection or list(table.get_children())
        if not target_items:
            return ""

        visible_events = list(getattr(self, "security_visible_events", []) or [])
        row_meta = getattr(self, "security_table_row_meta", {}) or {}
        lines = ["=== Security Event Auswahl ===", ""]
        appended = 0

        for item in target_items:
            meta = row_meta.get(item, {})
            if meta.get("kind") == "aggregate":
                raw = str(meta.get("raw", "") or "").strip()
                if not raw:
                    continue
                if appended:
                    lines.append("")
                lines.extend([f"[{appended + 1}] Aggregiert", raw])
                appended += 1
                continue

            try:
                index = int(meta.get("index"))
            except Exception:
                continue
            if index < 0 or index >= len(visible_events):
                continue
            event = visible_events[index]
            if appended:
                lines.append("")
            lines.extend(
                [
                    f"[{appended + 1}] {event.get('type', '-')}",
                    f"Zeit: {event.get('time', '-')}",
                    f"Quelle-IP: {event.get('src', '-')}",
                    f"Ziel-Port: {event.get('port', '-')}",
                    f"Protokoll: {event.get('proto', '-')}",
                    f"Level: {event.get('level', '-')}",
                    f"Aktion: {event.get('action', '-')}",
                    f"Extern: {'ja' if event.get('external') else 'nein'}",
                    f"Raw: {event.get('raw', '-')}",
                ]
            )
            appended += 1

        return "\n".join(lines).strip()

