    def get_repository_guard_sources_analysis_text(self) -> str:
        table = self.__dict__.get("repository_guard_sources_tree")
        if table is None or repository_guard_controller is None:
            return ""

        selection = list(table.selection())
        target_items = selection or list(table.get_children())
        if not target_items:
            return ""

        visible_sources = list(
            getattr(self, "repository_guard_visible_sources", []) or []
        )
        lines = ["=== Repository Guard Quellen Auswahl ===", ""]
        appended = 0
        for item in target_items:
            try:
                index = int(table.index(item))
            except Exception:
                continue
            if index < 0 or index >= len(visible_sources):
                continue
            if appended:
                lines.append("")
            lines.append(
                repository_guard_controller.format_repository_guard_source_details(
                    visible_sources[index]
                )
            )
            appended += 1
        return "\n".join(lines).strip()

    def copy_repository_guard_sources_to_clipboard(self):
        text = self.get_repository_guard_sources_analysis_text()
        if not text:
            try:
                self.chad_analysis_status_var.set(
                    self.tr(
                        "chad_status_no_repository_guard_sources_to_copy",
                        "Keine Repository Guard Quellen zum Kopieren vorhanden.",
                    )
                )
            except Exception:
                pass
            return
        self.clipboard_clear()
        self.clipboard_append(text)
        try:
            self.chad_analysis_status_var.set(
                self.tr(
                    "chad_status_repository_guard_sources_copied",
                    "Repository Guard Quellen in Zwischenablage kopiert.",
                )
            )
        except Exception:
            pass

