    def scroll_main_page_to_widget(self, widget, *, top_margin: int = 16) -> None:
        page_canvas = self.__dict__.get("page_canvas")
        page = self.__dict__.get("page")
        if page_canvas is None or page is None or widget is None:
            return
        try:
            self.update_idletasks()
            page_canvas.update_idletasks()
            widget_top = widget.winfo_rooty()
            page_top = page.winfo_rooty()
            target_y = max(0, int(widget_top - page_top - max(0, int(top_margin))))
            bbox = page_canvas.bbox("all")
            if not bbox:
                return
            total_height = max(1, int(bbox[3] - bbox[1]))
            viewport_height = max(1, int(page_canvas.winfo_height() or 1))
            max_scroll = max(0, total_height - viewport_height)
            if max_scroll <= 0:
                page_canvas.yview_moveto(0.0)
                return
            clamped_y = min(target_y, max_scroll)
            page_canvas.yview_moveto(clamped_y / total_height)
        except Exception:
            pass

    def scroll_main_page_to_widget_later(
        self,
        widget,
        *,
        top_margin: int = 16,
        delay_ms: int = 80,
        repeat: int = 2,
    ) -> None:
        if widget is None:
            return

        def _scroll(remaining: int):
            self.scroll_main_page_to_widget(widget, top_margin=top_margin)
            if remaining <= 0:
                return
            try:
                self.after(delay_ms, lambda: _scroll(remaining - 1))
            except Exception:
                pass

        _scroll(max(0, int(repeat)))

    def show_firewall_security_scan_feedback(self, title: str, message: str) -> None:
        self._open_security_menu_target_tab("firewall")
        snapshot = self.refresh_firewall_transparency_view()
        summary_widget = self.__dict__.get("firewall_tab_summary_text")
        if summary_widget is None:
            return
        summary_lines = list((snapshot or {}).get("summary_lines") or [])
        prefix_lines = [str(title or "").strip(), str(message or "").strip()]
        prefix_lines = [line for line in prefix_lines if line]
        if summary_lines:
            prefix_lines.extend(["", *summary_lines])
        try:
            summary_widget.configure(state="normal")
            summary_widget.delete("1.0", "end")
            summary_widget.insert("1.0", "\n".join(prefix_lines).strip())
            summary_widget.see("1.0")
            summary_widget.configure(state="disabled")
        except Exception:
            pass
        self.scroll_main_page_to_widget(summary_widget)

    def show_security_guards_scan_feedback(
        self,
        title: str,
        message: str,
        events=None,
    ) -> None:
        self._open_security_menu_target_tab("guard_events")
        detail_widget = self.__dict__.get("security_detail")
        if detail_widget is None:
            return
        lines = [str(title or "").strip(), str(message or "").strip()]
        lines = [line for line in lines if line]
        normalized_events = list(events or [])
        if normalized_events:
            lines.append("")
            lines.append("Details:")
            for event in normalized_events:
                event_type = str(event.get("type") or "-").strip() or "-"
                raw = str(event.get("raw") or "").strip()
                if raw:
                    lines.append(f"- {event_type}: {raw}")
                else:
                    lines.append(f"- {event_type}")
        try:
            detail_widget.configure(state="normal")
            detail_widget.delete("1.0", "end")
            detail_widget.insert("1.0", "\n".join(lines).strip())
            detail_widget.see("1.0")
        except Exception:
            pass
        scroll_target = self.__dict__.get("security_detail_frame", detail_widget)
        self.scroll_main_page_to_widget_later(
            scroll_target,
            top_margin=12,
            delay_ms=90,
            repeat=3,
        )

