    def _parse_firewall_listener_address(self, value):
        text = str(value or "").strip()
        if not text:
            return "", ""
        if text.startswith("[") and "]:" in text:
            host, port = text[1:].rsplit("]:", 1)
            return host.strip(), port.strip()
        if text.count(":") >= 2:
            try:
                host, port = text.rsplit(":", 1)
                return host.strip("[]"), port.strip()
            except ValueError:
                return text, ""
        if ":" in text:
            host, port = text.rsplit(":", 1)
            return host.strip(), port.strip()
        return text, ""

    def _parse_firewall_listener_cgroup(self, process_info):
        match = re.search(r"\bcgroup:([^\s]+)", str(process_info or ""))
        if not match:
            return ""
        return match.group(1).strip()

    def _is_netmon_app_scope(self, cgroup_value):
        scope_name = str(cgroup_value or "").strip().rsplit("/", 1)[-1]
        return scope_name.startswith("app-gnome-netmon-") and scope_name.endswith(
            ".scope"
        )

    def _is_netmon_listener(self, listener):
        process_name = str(listener.get("process") or "").strip().lower()
        cgroup_value = str(listener.get("cgroup") or "").strip()
        pid_value = str(listener.get("pid") or "").strip()
        if process_name in {"netmon", "python", "python3"} and pid_value == str(
            os.getpid()
        ):
            return True
        if "netmon" in process_name:
            return True
        return self._is_netmon_app_scope(cgroup_value)

    def _describe_firewall_listener_owner(self, listener):
        cgroup_value = str(listener.get("cgroup") or "").strip()
        pid_value = str(listener.get("pid") or "").strip() or "-"
        if self._is_netmon_app_scope(cgroup_value):
            scope_name = cgroup_value.rsplit("/", 1)[-1]
            return f"NetMon app scope ({scope_name}, PID {pid_value})"
        if self._is_netmon_listener(listener):
            return f"NetMon process (PID {pid_value})"
        if cgroup_value:
            scope_name = cgroup_value.rsplit("/", 1)[-1]
            return f"cgroup {scope_name}"
        return ""

    def _classify_firewall_listener_scope(self, host):
        text = str(host or "").strip().lower()
        if not text:
            return "unknown"
        if text in {"224.0.0.251", "ff02::fb"}:
            return "multicast"
        if text in {"127.0.0.1", "::1", "localhost"}:
            return "local only"
        if text.startswith("127.") or text == "::1":
            return "local only"
        if text in {"0.0.0.0", "*", "::", "[::]"}:
            return "external"
        try:
            addr = ipaddress.ip_address(text)
        except ValueError:
            return "external"
        if addr.is_loopback:
            return "local only"
        if addr.is_private or addr.is_link_local:
            return "lan/local"
        return "external"

    def _parse_firewall_listener_line(self, line):
        text = str(line or "").strip()
        if not text:
            return None
        match = re.match(
            r"^(?P<proto>\S+)\s+(?P<state>\S+)\s+\S+\s+\S+\s+"
            r"(?P<local>\S+)\s+(?P<remote>\S+)(?:\s+(?P<extra>.*))?$",
            text,
        )
        if not match:
            return None
        proto = match.group("proto").lower()
        local = match.group("local") or ""
        process_info = match.group("extra") or ""
        host, port = self._parse_firewall_listener_address(local)
        if not port.isdigit():
            return None
        process_name = "-"
        process_pid = "-"
        proc_match = re.search(r'"([^"]+)"', process_info)
        if proc_match:
            process_name = proc_match.group(1)
        elif process_info:
            process_name = process_info.strip()
        pid_match = re.search(r"\bpid=(\d+)\b", process_info)
        if pid_match:
            process_pid = pid_match.group(1)
        cgroup_value = self._parse_firewall_listener_cgroup(process_info)
        if self._is_netmon_app_scope(cgroup_value):
            process_name = "NetMon"
        return {
            "proto": proto,
            "host": host or "-",
            "port": int(port),
            "process": process_name or "-",
            "pid": process_pid,
            "cgroup": cgroup_value,
            "scope": self._classify_firewall_listener_scope(host),
        }

    def _listener_matches_firewall_rule(self, listener, rules):
        listener_port = str(listener.get("port") or "")
        listener_proto = str(listener.get("proto") or "").lower()
        for rule in list(rules or []):
            if str(rule.get("policy") or "").upper() != "ALLOW":
                continue
            if str(rule.get("direction") or "").upper() not in {"", "IN"}:
                continue
            rule_port = str(rule.get("port") or "").strip()
            rule_proto = str(rule.get("proto") or "").lower().strip()
            if rule_port and rule_port != listener_port:
                continue
            if rule_proto and rule_proto != listener_proto:
                continue
            return True
        return False

    def _build_firewall_rule_assessment(self, rule):
        category = str(rule.get("category") or "")
        policy = str(rule.get("policy") or "").upper()
        direction = str(rule.get("direction") or "").upper() or "-"
        source = str(rule.get("from") or "-").strip() or "-"
        target = str(rule.get("display") or rule.get("to") or "-").strip() or "-"
        family = "IPv6" if bool(rule.get("is_ipv6")) else "IPv4"

        source_label = source
        if source_label in {"Anywhere", "Anywhere (v6)", "-"}:
            source_label = family
        else:
            source_label = f"{source_label} ({family})"

        if policy == "DENY":
            return {
                "target_label": f"{target} ({family})",
                "source_label": source_label,
                "direction_label": direction,
                "note": "blocked",
                "priority": "ok",
            }
        if category == "interface":
            iface = str(rule.get("interface") or "-").strip() or "-"
            return {
                "target_label": f"{target} ({family})",
                "source_label": source_label,
                "direction_label": f"{direction} via {iface}",
                "note": "interface rule",
                "priority": "check",
            }
        if category == "vpn_endpoint":
            return {
                "target_label": f"{target} ({family})",
                "source_label": source_label,
                "direction_label": direction,
                "note": "VPN/peer rule",
                "priority": "check",
            }
        if category == "standard_port":
            if source in {"Anywhere", "Anywhere (v6)", "-"}:
                return {
                    "target_label": f"{target} ({family})",
                    "source_label": source_label,
                    "direction_label": direction,
                    "note": "global allow",
                    "priority": "warn",
                }
            return {
                "target_label": f"{target} ({family})",
                "source_label": source_label,
                "direction_label": direction,
                "note": "targeted allow",
                "priority": "check",
            }
        return {
            "target_label": f"{target} ({family})",
            "source_label": source_label,
            "direction_label": direction,
            "note": "special rule",
            "priority": "check",
        }

    def _translate_firewall_listener_rating(self, text):
        raw = str(text or "").strip()
        mapping = {
            "bound locally only": (
                "firewall_listener_rating_local_only",
                "nur lokal gebunden",
                "bound locally only",
            ),
            "reachable in the LAN": (
                "firewall_listener_rating_lan_reachable",
                "im LAN erreichbar",
                "reachable in the LAN",
            ),
            "externally reachable, often intentional": (
                "firewall_listener_rating_external_often_intentional",
                "extern erreichbar, oft beabsichtigt",
                "externally reachable, often intentional",
            ),
            "externally reachable, review recommended": (
                "firewall_listener_rating_external_review",
                "extern erreichbar, Prüfung empfohlen",
                "externally reachable, review recommended",
            ),
            "allowed, verify scope": (
                "firewall_listener_rating_allowed_verify_scope",
                "erlaubt, Scope prüfen",
                "allowed, verify scope",
            ),
            "mDNS/multicast in the local network": (
                "firewall_listener_rating_multicast_local",
                "mDNS/Multicast im lokalen Netz",
                "mDNS/multicast in the local network",
            ),
            "active locally, probably filtered externally": (
                "firewall_listener_rating_local_probably_filtered",
                "lokal aktiv, extern vermutlich gefiltert",
                "active locally, probably filtered externally",
            ),
            "system service, check context": (
                "firewall_listener_rating_system_service",
                "Systemdienst, Kontext prüfen",
                "system service, check context",
            ),
            "listening locally, allow state unclear": (
                "firewall_listener_rating_unclear",
                "lokal lauschend, Freigabestatus unklar",
                "listening locally, allow state unclear",
            ),
            "gehoert zu NetMon selbst": (
                "firewall_listener_rating_netmon_self",
                "gehoert zu NetMon selbst",
                "belongs to NetMon itself",
            ),
        }
        if raw.startswith("UDP-Port gehoert zu NetMon selbst"):
            return self.tr(
                "firewall_listener_rating_netmon_udp_external",
                "UDP-Port gehoert zu NetMon selbst, pruefen ob Bindung auf alle Interfaces noetig ist",
            )
        if raw.startswith("Port gehoert zu NetMon selbst"):
            return self.tr(
                "firewall_listener_rating_netmon_port_external",
                "Port gehoert zu NetMon selbst, pruefen ob Bindung auf alle Interfaces noetig ist",
            )
        if raw in mapping:
            key, default_de, _default_en = mapping[raw]
            return self.tr(key, default_de)
        return raw

    def _translate_firewall_rule_note(self, text):
        raw = str(text or "").strip()
        mapping = {
            "blocked": (
                "firewall_rule_note_blocked",
                "blockiert",
                "blocked",
            ),
            "interface rule": (
                "firewall_rule_note_interface",
                "Interface-Regel",
                "interface rule",
            ),
            "VPN/peer rule": (
                "firewall_rule_note_vpn_peer",
                "VPN/Peer-Regel",
                "VPN/peer rule",
            ),
            "global allow": (
                "firewall_rule_note_global_allow",
                "globale Erlaubnis",
                "global allow",
            ),
            "targeted allow": (
                "firewall_rule_note_targeted_allow",
                "gezielte Erlaubnis",
                "targeted allow",
            ),
            "special rule": (
                "firewall_rule_note_special",
                "Sonderregel",
                "special rule",
            ),
        }
        if raw in mapping:
            key, default_de, _default_en = mapping[raw]
            return self.tr(key, default_de)
        return raw

    def _build_firewall_listener_assessment(self, listener, rules):
        scope = str(listener.get("scope") or "unknown")
        allowed = self._listener_matches_firewall_rule(listener, rules)
        process_name = str(listener.get("process") or "-").strip() or "-"
        port_value = int(listener.get("port") or 0)
        proto_value = str(listener.get("proto") or "").strip().lower()

        if self._is_netmon_listener(listener):
            kind_label = "UDP-Port" if proto_value == "udp" else "Port"
            if scope == "external":
                return {
                    "firewall": "self",
                    "rating": f"{kind_label} gehoert zu NetMon selbst, pruefen ob Bindung auf alle Interfaces noetig ist",
                    "priority": "check",
                }
            return {
                "firewall": "self",
                "rating": "gehoert zu NetMon selbst",
                "priority": "ok",
            }

        if scope == "local only":
            return {
                "firewall": "local",
                "rating": "bound locally only",
                "priority": "ok",
            }
        if scope == "lan/local" and allowed:
            return {
                "firewall": "allowed",
                "rating": "reachable in the LAN",
                "priority": "check",
            }
        if allowed and scope == "external":
            if process_name in {"sshd", "ssh", "openvpn", "wg-quick", "wireguard"}:
                return {
                    "firewall": "allowed",
                    "rating": "externally reachable, often intentional",
                    "priority": "check",
                }
            return {
                "firewall": "allowed",
                "rating": "externally reachable, review recommended",
                "priority": "warn",
            }
        if allowed:
            return {
                "firewall": "allowed",
                "rating": "allowed, verify scope",
                "priority": "check",
            }
        if scope == "multicast":
            return {
                "firewall": "multicast",
                "rating": "mDNS/multicast in the local network",
                "priority": "ok",
            }
        if scope == "lan/local":
            return {
                "firewall": "local/lan",
                "rating": "active locally, probably filtered externally",
                "priority": "ok",
            }
        if port_value in {53, 67, 68, 123, 5353}:
            return {
                "firewall": "unclear",
                "rating": "system service, check context",
                "priority": "check",
            }
        return {
            "firewall": "filtered/unclear",
            "rating": "listening locally, allow state unclear",
            "priority": "check",
        }

    def _collect_firewall_transparency_snapshot(self):
        snapshot = {
            "status_label": "unknown",
            "default_in": "-",
            "default_out": "-",
            "logging": "–",
            "rule_count": 0,
            "external_open_count": 0,
            "listener_count": 0,
            "last_check": self.tr(
                "firewall_listener_last_check_none",
                "Noch kein Check",
            ),
            "rules": [],
            "listeners": [],
            "summary_lines": [],
        }
        try:
            rc, out = self._read_ufw_status(verbose=True)
        except Exception:
            rc, out = 1, ""

        if rc != 0 and not check_sudo_nopasswd():
            snapshot["status_label"] = self.tr(
                "firewall_status_auth_pending_short",
                "Autorisierung ausstehend",
            )

        metadata_lines = []
        structured_rules = []
        if rc == 0 and out:
            for raw_line in str(out or "").splitlines():
                line = raw_line.strip()
                if not line:
                    continue
                lower = line.lower()
                if lower.startswith("status:"):
                    snapshot["status_label"] = (
                        line.split(":", 1)[1].strip() or "unknown"
                    )
                    continue
                if lower.startswith("default:") or lower.startswith("voreinstellung:"):
                    default_text = (
                        line.split(":", 1)[1].strip() if ":" in line else line
                    )
                    match_in = re.search(
                        r"(allow|deny|reject)\s*\((incoming|eingehend)\)",
                        default_text,
                        re.IGNORECASE,
                    )
                    match_out = re.search(
                        r"(allow|deny|reject)\s*\((outgoing|abgehend|ausgehend)\)",
                        default_text,
                        re.IGNORECASE,
                    )
                    if match_in:
                        snapshot["default_in"] = match_in.group(1).upper()
                    if match_out:
                        snapshot["default_out"] = match_out.group(1).upper()
                    metadata_lines.append(line)
                    continue
                if lower.startswith("logging:") or lower.startswith("protokollierung:"):
                    metadata_lines.append(line)
                    parsed_logging = self._parse_ufw_logging_level(line)
                    if parsed_logging != "–":
                        snapshot["logging"] = parsed_logging
                    continue
                if lower.startswith("new profiles:"):
                    metadata_lines.append(line)
                    continue
                if self._is_ufw_non_rule_line(line):
                    continue
                parsed = self._parse_ufw_structured_rule(line)
                if parsed is not None:
                    structured_rules.append(parsed)

        snapshot["rules"] = list(structured_rules)
        snapshot["rule_count"] = len(structured_rules)
        if snapshot["logging"] == "–":
            try:
                snapshot["logging"] = self._security_query_log_level()
            except Exception:
                pass

        listener_rows = []
        listener_cmds = [
            ["ss", "-lntupeH"],
            ["ss", "-lntupH"],
            ["ss", "-lntuH"],
        ]
        for cmd in listener_cmds:
            try:
                rc_listen, out_listen = run_cmd(cmd, timeout=8)
            except Exception:
                continue
            if rc_listen != 0 or not out_listen:
                continue
            for raw_line in str(out_listen or "").splitlines():
                parsed_listener = self._parse_firewall_listener_line(raw_line)
                if parsed_listener is None:
                    continue
                if parsed_listener["proto"] not in {"tcp", "udp"}:
                    continue
                if parsed_listener["port"] <= 0:
                    continue
                assessment = self._build_firewall_listener_assessment(
                    parsed_listener, structured_rules
                )
                parsed_listener["firewall"] = str(assessment.get("firewall") or "-")
                parsed_listener["rating"] = self._translate_firewall_listener_rating(
                    assessment.get("rating") or "-"
                )
                parsed_listener["priority"] = str(assessment.get("priority") or "check")
                parsed_listener["owner_note"] = self._describe_firewall_listener_owner(
                    parsed_listener
                )
                listener_rows.append(parsed_listener)
            break

        listener_rows.sort(
            key=lambda item: (int(item.get("port") or 0), item.get("proto") or "")
        )
        snapshot["listeners"] = listener_rows
        snapshot["listener_count"] = len(listener_rows)
        snapshot["external_open_count"] = sum(
            1
            for item in listener_rows
            if str(item.get("scope") or "") != "local only"
            and str(item.get("firewall") or "") == "allowed"
        )

        scan = dict(self.__dict__.get("port_reality_last_scan", {}) or {})
        results = list(scan.get("results") or [])
        host = (scan.get("host") or "-").strip() or "-"
        ts = float(scan.get("ts") or 0.0)
        if results:
            stamp = (
                datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S") if ts else "-"
            )
            snapshot["last_check"] = self.tr(
                "firewall_listener_last_check_value",
                "{stamp} | {host} | {count} Port(s)",
            ).format(stamp=stamp, host=host, count=len(results))

        local_only_count = sum(
            1 for item in listener_rows if str(item.get("scope") or "") == "local only"
        )
        check_count = sum(
            1 for item in listener_rows if str(item.get("priority") or "") == "check"
        )
        warn_count = sum(
            1 for item in listener_rows if str(item.get("priority") or "") == "warn"
        )
        self_listener_count = sum(
            1 for item in listener_rows if self._is_netmon_listener(item)
        )

        summary_lines = [
            self.tr("firewall_transparency_ufw", "UFW: {value}").format(
                value=snapshot["status_label"]
            ),
            self.tr("firewall_transparency_default_in", "Default IN: {value}").format(
                value=snapshot["default_in"]
            ),
            self.tr(
                "firewall_transparency_default_out",
                "Default OUT: {value}",
            ).format(value=snapshot["default_out"]),
            self.tr("firewall_transparency_logging", "Logging: {value}").format(
                value=snapshot["logging"]
            ),
            self.tr(
                "firewall_transparency_active_rules", "Active rules: {count}"
            ).format(count=snapshot["rule_count"]),
            self.tr(
                "firewall_transparency_local_listeners",
                "Local listeners: {count}",
            ).format(count=snapshot["listener_count"]),
            self.tr(
                "firewall_transparency_external_allowed",
                "Externally allowed: {count}",
            ).format(count=snapshot["external_open_count"]),
            self.tr(
                "firewall_transparency_last_reality_check",
                "Last reality check: {value}",
            ).format(value=snapshot["last_check"]),
        ]
        global_allow_count = 0
        deny_count = 0
        special_count = 0
        for rule in structured_rules:
            assessment = self._build_firewall_rule_assessment(rule)
            rule["note"] = str(assessment.get("note") or "-")
            rule["note"] = self._translate_firewall_rule_note(rule["note"])
            rule["direction_label"] = str(assessment.get("direction_label") or "-")
            rule["source_label"] = str(assessment.get("source_label") or "-")
            rule["target_label"] = str(assessment.get("target_label") or "-")
            rule["priority"] = str(assessment.get("priority") or "check")
            if rule["note"] == "global allow":
                global_allow_count += 1
            elif rule["note"] == "blocked":
                deny_count += 1
            else:
                special_count += 1
        summary_lines.extend(
            [
                "",
                self.tr(
                    "firewall_transparency_global_allows",
                    "Global allows: {count}",
                ).format(count=global_allow_count),
                self.tr(
                    "firewall_transparency_block_rules",
                    "Block rules: {count}",
                ).format(count=deny_count),
                self.tr(
                    "firewall_transparency_special_rules",
                    "Special/targeted rules: {count}",
                ).format(count=special_count),
                self.tr(
                    "firewall_transparency_local_bindings",
                    "Local only bindings: {count}",
                ).format(count=local_only_count),
                self.tr(
                    "firewall_transparency_needs_review",
                    "Needs review: {count}",
                ).format(count=check_count),
                self.tr("firewall_transparency_notable", "Notable: {count}").format(
                    count=warn_count
                ),
                self.tr(
                    "firewall_transparency_self_listeners",
                    "NetMon own listeners: {count}",
                ).format(count=self_listener_count),
            ]
        )
        notable = [
            item
            for item in listener_rows
            if str(item.get("priority") or "") in {"warn", "check"}
        ][:4]
        if notable:
            summary_lines.extend(
                [
                    "",
                    self.tr(
                        "firewall_transparency_notable_services",
                        "Notable services / ports:",
                    ),
                ]
            )
            for item in notable:
                summary_lines.append(
                    f"- {item.get('port', '-')}/{item.get('proto', '-')}: "
                    f"{item.get('process', '-')} | {item.get('rating', '-')}"
                )
        if results:
            summary_lines.extend(
                [
                    "",
                    self.tr(
                        "firewall_transparency_last_port_reality_check",
                        "Last port reality check:",
                    ),
                ]
            )
            for item in results[:6]:
                try:
                    port = int(item.get("port", 0) or 0)
                except (TypeError, ValueError):
                    port = 0
                state = str(item.get("state") or "unknown").strip() or "unknown"
                shown = PORT_REALITY_DISPLAY_MAP.get(state, state)
                summary_lines.append(f"- Port {port} -> {shown}")
        if not structured_rules:
            summary_lines.append(
                self.tr(
                    "firewall_transparency_no_rules_note",
                    "Note: no UFW rules detected or status not readable.",
                )
            )
        snapshot["summary_lines"] = summary_lines
        return snapshot

    def refresh_firewall_transparency_view(self):
        snapshot = self._collect_firewall_transparency_snapshot()
        for var_name, value in [
            (
                "firewall_tab_status_var",
                self.tr("firewall_tab_status_value", "UFW: {value}").format(
                    value=snapshot["status_label"]
                ),
            ),
            (
                "firewall_tab_default_in_var",
                self.tr("firewall_tab_incoming_value", "Incoming: {value}").format(
                    value=snapshot["default_in"]
                ),
            ),
            (
                "firewall_tab_default_out_var",
                self.tr("firewall_tab_outgoing_value", "Outgoing: {value}").format(
                    value=snapshot["default_out"]
                ),
            ),
            (
                "firewall_tab_logging_var",
                self.tr("firewall_tab_logging_value", "Logging: {value}").format(
                    value=snapshot["logging"]
                ),
            ),
            (
                "firewall_tab_rule_count_var",
                self.tr("firewall_tab_rules_value", "Rules: {count}").format(
                    count=snapshot["rule_count"]
                ),
            ),
            (
                "firewall_tab_external_open_var",
                self.tr(
                    "firewall_tab_external_ports_value",
                    "External ports: {count}",
                ).format(count=snapshot["external_open_count"]),
            ),
            (
                "firewall_tab_listener_count_var",
                self.tr(
                    "firewall_tab_local_listeners_value",
                    "Local listeners: {count}",
                ).format(count=snapshot["listener_count"]),
            ),
            (
                "firewall_tab_last_check_var",
                self.tr("firewall_tab_last_check_value", "Last check: {value}").format(
                    value=snapshot["last_check"]
                ),
            ),
        ]:
            var = self.__dict__.get(var_name)
            if var is not None:
                try:
                    var.set(value)
                except Exception:
                    pass
        logging_menu_var = self.__dict__.get("firewall_tab_logging_menu_var")
        if logging_menu_var is not None:
            try:
                logging_menu_var.set(
                    self.tr(
                        "firewall_tab_logging_menu_value", "UFW Logging: {value}"
                    ).format(value=snapshot["logging"])
                )
            except Exception:
                pass

        rules_table = self.__dict__.get("firewall_rules_table")
        if rules_table is not None:
            try:
                self.firewall_rule_row_meta = {}
                rules_table.delete(*rules_table.get_children())
                for idx, rule in enumerate(snapshot["rules"]):
                    proto_label = str(rule.get("proto") or "").lower().strip() or "all"
                    row_id = rules_table.insert(
                        "",
                        "end",
                        values=(
                            str(rule.get("policy") or "-"),
                            str(
                                rule.get("target_label")
                                or rule.get("display")
                                or rule.get("to")
                                or "-"
                            ),
                            proto_label,
                            str(rule.get("source_label") or rule.get("from") or "-"),
                            str(rule.get("note") or rule.get("direction_label") or "-"),
                        ),
                    )
                    self.firewall_rule_row_meta[row_id] = dict(rule)
                self.on_firewall_rule_select()
            except Exception:
                pass

        listeners_table = self.__dict__.get("firewall_listeners_table")
        if listeners_table is not None:
            try:
                listeners_table.delete(*listeners_table.get_children())
                for item in snapshot["listeners"]:
                    bind_label = str(item.get("host") or "-")
                    scope = str(item.get("scope") or "").strip()
                    if scope:
                        bind_label = f"{bind_label} ({scope})"
                    owner_note = str(item.get("owner_note") or "").strip()
                    if owner_note:
                        bind_label = f"{bind_label} | {owner_note}"
                    listeners_table.insert(
                        "",
                        "end",
                        values=(
                            str(item.get("port") or "-"),
                            str(item.get("proto") or "-"),
                            str(item.get("process") or "-"),
                            str(item.get("pid") or "-"),
                            bind_label,
                            str(item.get("firewall") or "-"),
                            str(item.get("rating") or "-"),
                        ),
                    )
            except Exception:
                pass

        summary_widget = self.__dict__.get("firewall_tab_summary_text")
        if summary_widget is not None:
            try:
                has_selection = bool(summary_widget.tag_ranges("sel"))
            except Exception:
                has_selection = False
            if has_selection:
                return snapshot
            try:
                summary_widget.configure(state="normal")
                summary_widget.delete("1.0", "end")
                summary_widget.insert("1.0", "\n".join(snapshot["summary_lines"]))
                summary_widget.configure(state="disabled")
            except Exception:
                pass
        return snapshot

    def build_firewall_transparency_report(self) -> str:
        snapshot = self._collect_firewall_transparency_snapshot()
        lines = ["=== Firewall Transparency ===", ""]
        lines.extend(list(snapshot.get("summary_lines") or []))

        rules = list(snapshot.get("rules") or [])
        lines.extend(["", "Active firewall rules:"])
        if rules:
            for rule in rules:
                lines.append(
                    " | ".join(
                        [
                            str(rule.get("policy") or "-"),
                            str(rule.get("direction") or "-") or "-",
                            str(rule.get("display") or rule.get("to") or "-"),
                            str(rule.get("from") or "-"),
                        ]
                    )
                )
        else:
            lines.append("(no rules detected)")

        listeners = list(snapshot.get("listeners") or [])
        lines.extend(["", "Open ports / services:"])
        if listeners:
            for item in listeners:
                lines.append(
                    " | ".join(
                        [
                            f"{item.get('port', '-')}/{item.get('proto', '-')}",
                            str(item.get("process") or "-"),
                            str(item.get("host") or "-"),
                            str(item.get("firewall") or "-"),
                            str(item.get("rating") or "-"),
                            str(item.get("owner_note") or "-"),
                        ]
                    )
                )
        else:
            lines.append("(no listeners detected)")
        return "\n".join(lines).strip()

    def analyze_firewall_with_chad(self):
        if not self.is_chad_enabled():
            self._show_chad_activation_required_popup()
            return
        report = self.build_firewall_transparency_report()
        if not report:
            try:
                self.chad_analysis_status_var.set(
                    "No firewall transparency data available for Chad analysis."
                )
            except Exception:
                pass
            return
        self.prepare_chad_analysis("Firewall transparency analysis", report)

