    def vpn_switch(
        self,
        target,
        ensure_sudo=True,
        refresh_ui=True,
        force_reconnect=False,
        skip_cleanup=False,
    ):
        self._record_diagnostic_action(
            "VPN wechseln",
            "vpn",
            details={
                "target": str(target or ""),
                "ensure_sudo": bool(ensure_sudo),
                "refresh_ui": bool(refresh_ui),
                "force_reconnect": bool(force_reconnect),
                "skip_cleanup": bool(skip_cleanup),
            },
        )
        if "ufw_lock" not in self.__dict__:
            self.ufw_lock = threading.Lock()
        result = vpn_controller.vpn_switch(
            self,
            target,
            ensure_sudo=ensure_sudo,
            refresh_ui=refresh_ui,
            force_reconnect=force_reconnect,
            skip_cleanup=skip_cleanup,
        )
        if result:
            schedule_ip_refresh = getattr(
                self, "_schedule_vpn_ip_country_refresh", None
            )
            if callable(schedule_ip_refresh):
                try:
                    schedule_ip_refresh()
                except Exception:
                    pass
        try:
            self.after(0, self.update_vpn_status_text)
        except Exception:
            pass
        return result

