    def _set_connection_detail_fields(self, row=None):
        defaults = {
            "conn_detail_proto_var": self.tr("detail_no_selection", "No selection"),
            "conn_detail_state_var": self.tr("detail_no_selection", "No selection"),
            "conn_detail_pid_var": self.tr("detail_no_selection", "No selection"),
            "conn_detail_local_var": self.tr(
                "connections_detail_local_default",
                "No connection selected yet.",
            ),
            "conn_detail_remote_var": self.tr("detail_no_selection", "No selection"),
            "conn_detail_proc_var": self.tr("detail_no_selection", "No selection"),
        }
        if not row:
            for attr_name, value in defaults.items():
                getattr(self, attr_name).set(value)
            return
        self.conn_detail_proto_var.set(str(row.get("proto") or "-"))
        self.conn_detail_state_var.set(str(row.get("state") or "-"))
        self.conn_detail_pid_var.set(str(row.get("pid") or "-"))
        self.conn_detail_local_var.set(str(row.get("local") or "-"))
        self.conn_detail_remote_var.set(str(row.get("remote") or "-"))
        self.conn_detail_proc_var.set(str(row.get("proc") or "-"))

    def on_connection_select(self, _event=None):
        table = self.__dict__.get("conn_table")
        if table is None:
            return
        try:
            selection = list(table.selection())
        except Exception:
            selection = []
        if not selection:
            self._set_connection_detail_fields(None)
            return
        item_id = selection[0]
        try:
            values = list(table.item(item_id, "values") or [])
        except Exception:
            values = []
        if len(values) < 6:
            self._set_connection_detail_fields(None)
            return
        row = {
            "proto": values[0],
            "state": values[1],
            "local": values[2],
            "remote": values[3],
            "pid": values[4],
            "proc": values[5],
        }
        self._set_connection_detail_fields(row)

    def clear_conn_filters(self):
        self.conn_filter.set("")
        self.conn_process_filter_var.set("")
        self.conn_pid_filter_var.set("")
        self.conn_state_filter_var.set("")
        self.conn_only_external_var.set(False)
        self.conn_only_established_var.set(False)
        self.apply_conn_filter()

    def _connection_matches_filters(
        self,
        row,
        *,
        text_filter,
        process_filter,
        pid_filter,
        state_filter,
        only_external,
        only_established,
    ):
        proto = str(row.get("proto") or "")
        state = str(row.get("state") or "")
        local = str(row.get("local") or "")
        remote = str(row.get("remote") or "")
        pid = str(row.get("pid") or "")
        proc = str(row.get("proc") or "")

        blob = f"{proto} {state} {local} {remote} {pid} {proc}".lower()
        if text_filter and text_filter not in blob:
            return False
        if process_filter and process_filter not in proc.lower():
            return False
        if pid_filter and pid_filter not in pid:
            return False
        if state_filter and state_filter not in state.lower():
            return False
        if only_established and state.upper() not in {"ESTAB", "ESTABLISHED"}:
            return False
        if only_external:
            remote_host = remote
            if remote_host.startswith("[") and "]:" in remote_host:
                remote_host = remote_host[1:].split("]:", 1)[0]
            elif ":" in remote_host:
                remote_host = remote_host.rsplit(":", 1)[0]
            remote_host = remote_host.strip()
            if not remote_host or remote_host == "*" or is_local_or_lan_ip(remote_host):
                return False
        return True

    def apply_conn_filter(self):
        q = (self.conn_filter.get() or "").strip().lower()
        process_filter = (self.conn_process_filter_var.get() or "").strip().lower()
        pid_filter = (self.conn_pid_filter_var.get() or "").strip()
        state_filter = (self.conn_state_filter_var.get() or "").strip().lower()
        only_external = bool(self.conn_only_external_var.get())
        only_established = bool(self.conn_only_established_var.get())
        rows = self._conn_rows_cache

        for item in self.conn_table.get_children():
            self.conn_table.delete(item)

        if not any(
            (
                q,
                process_filter,
                pid_filter,
                state_filter,
                only_external,
                only_established,
            )
        ):
            for c in rows:
                self.conn_table.insert(
                    "",
                    "end",
                    values=(
                        c["proto"],
                        c["state"],
                        c["local"],
                        c["remote"],
                        c["pid"],
                        c["proc"],
                    ),
                )
            self._set_connection_detail_fields(rows[0] if rows else None)
            return

        visible_rows = []
        for c in rows:
            if not self._connection_matches_filters(
                c,
                text_filter=q,
                process_filter=process_filter,
                pid_filter=pid_filter,
                state_filter=state_filter,
                only_external=only_external,
                only_established=only_established,
            ):
                continue
            visible_rows.append(c)
            self.conn_table.insert(
                "",
                "end",
                values=(
                    c["proto"],
                    c["state"],
                    c["local"],
                    c["remote"],
                    c["pid"],
                    c["proc"],
                ),
            )
        self._set_connection_detail_fields(visible_rows[0] if visible_rows else None)

    def _format_connection_values(self, values) -> str:
        cols = [str(value or "").strip() for value in values]
        while len(cols) < 6:
            cols.append("")
        return (
            f"Proto: {cols[0]} | State: {cols[1]} | Local: {cols[2]} | "
            f"Remote: {cols[3]} | PID: {cols[4]} | Process: {cols[5]}"
        )

    def _selected_connection_row(self):
        table = self.__dict__.get("conn_table")
        if table is None:
            return None
        try:
            selection = list(table.selection())
        except Exception:
            selection = []
        if not selection:
            return None
        try:
            values = list(table.item(selection[0], "values") or [])
        except Exception:
            values = []
        if len(values) < 6:
            return None
        return {
            "proto": values[0],
            "state": values[1],
            "local": values[2],
            "remote": values[3],
            "pid": values[4],
            "proc": values[5],
        }

    def _extract_connection_remote_host(self, remote: str) -> str:
        value = str(remote or "").strip()
        if not value or value == "*":
            return ""
        if value.startswith("[") and "]:" in value:
            return value[1:].split("]:", 1)[0].strip()
        if value.count(":") >= 2 and not value.startswith("["):
            return value.strip()
        if ":" in value:
            return value.rsplit(":", 1)[0].strip()
        return value

    def send_selected_connection_to_trace(self):
        row = self._selected_connection_row()
        if not row:
            self.log(
                self.tr(
                    "connections_log_no_selection_for_trace",
                    "Connections: no selection available to send to Trace.",
                )
            )
            return
        remote_host = self._extract_connection_remote_host(row.get("remote", ""))
        if not remote_host or not is_safe_trace_target(remote_host):
            self.log(
                self.tr(
                    "connections_log_remote_target_invalid_for_trace",
                    "Connections: remote target could not be sent cleanly to Trace.",
                )
            )
            return
        self.trace_manual_target_var.set(remote_host)
        trace_entry = self.__dict__.get("trace_manual_target_entry")
        if trace_entry is not None:
            try:
                trace_entry.delete(0, "end")
                trace_entry.insert(0, remote_host)
            except Exception:
                pass
        nb = self.__dict__.get("nb")
        if nb is not None:
            try:
                nb.select(self.tab_trace)
            except Exception:
                pass
        self.log(
            self.tr(
                "connections_log_remote_target_sent_to_trace",
                "Connections: remote target sent to Trace: {target}",
            ).format(target=remote_host)
        )

    def send_selected_connection_to_nmap(self):
        row = self._selected_connection_row()
        if not row:
            self.log(
                self.tr(
                    "connections_log_no_selection_for_nmap",
                    "Connections: no selection available to send to Nmap.",
                )
            )
            return
        remote_host = self._extract_connection_remote_host(row.get("remote", ""))
        if not remote_host or not is_safe_trace_target(remote_host):
            self.log(
                self.tr(
                    "connections_log_remote_target_invalid_for_nmap",
                    "Connections: remote target could not be sent cleanly to Nmap.",
                )
            )
            return
        self.nmap_manual_target_var.set(remote_host)
        self._select_tools_tab(self.tab_nmap)
        self.log(
            self.tr(
                "connections_log_remote_target_sent_to_nmap",
                "Connections: remote target sent to Nmap: {target}",
            ).format(target=remote_host)
        )

    def get_connections_analysis_text(self) -> str:
        table = self.__dict__.get("conn_table")
        if table is None:
            return ""

        selection = list(table.selection())
        target_items = selection or list(table.get_children())
        if not target_items:
            return ""

        lines = ["=== Verbindungen ===", ""]
        for item in target_items:
            try:
                values = table.item(item, "values")
            except Exception:
                values = ()
            lines.append(self._format_connection_values(values))
        return "\n".join(lines).strip()

