    def get_process_guard_analysis_text(self) -> str:
        table = self.__dict__.get("process_guard_tree")
        if table is None:
            return ""

        selection = list(table.selection())
        target_items = selection or list(table.get_children())
        if not target_items:
            return ""

        visible_findings = list(
            getattr(self, "process_guard_visible_findings", []) or []
        )
        lines = ["=== Process Guard selection ===", ""]
        appended = 0
        for item in target_items:
            try:
                index = int(table.index(item))
            except Exception:
                continue
            if index < 0 or index >= len(visible_findings):
                continue
            if appended:
                lines.append("")
            lines.append(
                process_guard_controller.format_process_guard_details(
                    visible_findings[index], self
                )
            )
            appended += 1
        return "\n".join(lines).strip()

