    def _update_dns_consistency_light(self):
        if "l_dnscons" not in self.__dict__:
            return
        self.update_dns_guard_indicator()

    def _update_dns_consistency_light_safe(self):
        if threading.current_thread() is threading.main_thread():
            self.update_dns_guard_indicator()
            return
        self.after(0, self.update_dns_guard_indicator)

    def refresh(self):
        inet = self.check_internet()
        inet_state = self._internet_suspend_indicator_override()
        if inet_state is None:
            inet_state = self._update_internet_indicator_state(bool(inet))
        vpn_profile = self.active_wg_profile()

        fw = False
        fw_readable = True
        if "check_ufw_active" in self.__dict__:
            fw = self.check_ufw_active()
        else:
            try:
                rc_fw, out_fw = self._read_ufw_status()
            except Exception:
                rc_fw, out_fw = 1, ""
            fw_readable = rc_fw == 0
            if fw_readable:
                fw = self._ufw_status_is_active(out_fw)
        ssh_rule = self.check_ssh_rule_active() if fw_readable and fw else None
        ks = self.killswitch_is_on() if fw_readable else None

        self.update_ipv6_controls_state()
        if hasattr(self, "vpn_profile_combo"):
            self.vpn_profile_combo["values"] = self.wg_profiles
        self.update_primary_vpn_form_controls()
        self.sync_primary_vpn_form_selection()
        self.sync_vpn_profile_form_selection()
        self.update_dns_header()
        self.update_wg_rates()

        if inet_state == "ok":
            self.set_light(self.l_inet, "green")
        elif inet_state == "suspended":
            self.set_light(self.l_inet, "gray")
        elif inet_state == "warning":
            self.set_light(self.l_inet, "yellow")
        elif inet_state == "transition":
            self.set_light(self.l_inet, "yellow")
        else:
            self.set_light(self.l_inet, "red")
        self.set_light(self.l_vpn, "green" if vpn_profile else "gray")
        self.update_vpn_status_text()
        if fw_readable:
            self.set_light(self.l_fw, "green" if fw else "red")
        else:
            self.set_light(self.l_fw, "gray")
        if ssh_rule is True:
            self.set_light(self.l_ssh, "green")
        elif ssh_rule is False:
            self.set_light(self.l_ssh, "red")
        else:
            self.set_light(self.l_ssh, "gray")
        self.update_ufw_logging_light()
        if ks is True:
            self.set_light(self.l_ks, "green")
        elif ks is False:
            self.set_light(self.l_ks, "red")
        else:
            self.set_light(self.l_ks, "gray")
        self.update_game_mode_light()
        active_profile_for_ipv6 = (vpn_profile or "").strip()
        active_iface_for_ipv6 = (self.get_wg_iface() or "").strip()
        if not active_profile_for_ipv6:
            ipv6_light = "gray"
        else:
            ipv6_light = (
                "green"
                if self.ipv6_runtime_available_on_iface(active_iface_for_ipv6)
                else "red"
            )
        self.set_light(self.l_ipv6, ipv6_light)

        self._update_dns_consistency_light()
        self._update_dot_light()

        self.update_vpn_slot_buttons()
        self.refresh_vpn_slots_table()

        self.ip_country_async(force=False)
        self.whoami_async(force=False)

        wg_if = self.get_wg_iface()
        default_if = self.get_default_iface() or "–"
        route_txt = (
            self.tr("header_traffic_via", "via {iface}").format(iface=wg_if)
            if wg_if
            else self.tr("header_traffic_via", "via {iface}").format(iface=default_if)
        )
        if not vpn_profile:
            v6txt = self.tr("header_ipv6_na", "IPv6: n/a")
        else:
            wg_v6_runtime = self.ipv6_runtime_available_on_iface(wg_if)
            if wg_v6_runtime:
                v6txt = self.tr("header_ipv6_ok", "IPv6: OK")
            elif self.profile_supports_ipv6(vpn_profile) and self.ipv6_is_disabled():
                v6txt = self.tr(
                    "header_ipv6_profile_expected_off",
                    "IPv6: profile expects IPv6 (OFF)",
                )
            else:
                v6txt = self.tr(
                    "header_ipv6_profile_ipv4_only", "IPv6: profile IPv4 only"
                )

        parts = [
            (
                self.tr("header_internet_ok", "Internet OK")
                if inet_state == "ok"
                else (
                    self.tr("header_internet_transition", "Internet TRANSITION")
                    if inet_state == "transition"
                    else (
                        self.tr("header_internet_off", "Internet AUS")
                        if inet_state == "suspended"
                        else (
                            self.tr("header_internet_warn", "Internet WARN")
                            if inet_state == "warning"
                            else self.tr("header_internet_down", "Internet DOWN")
                        )
                    )
                )
            ),
            (
                self.tr("header_vpn_value", "VPN: {value}").format(value=vpn_profile)
                if vpn_profile
                else self.tr("header_vpn_off", "VPN: off")
            ),
            (
                self.tr("header_ufw_on", "UFW: active")
                if fw
                else self.tr("header_ufw_off", "UFW: off")
            ),
            (
                self.tr("header_killswitch_on", "Killswitch: ON")
                if ks
                else self.tr("header_killswitch_off", "Killswitch: OFF")
            ),
            v6txt,
            self.tr("header_traffic_value", "Traffic: {value}").format(value=route_txt),
            f"RX {human_rate(self.wg_rx_rate)} / TX {human_rate(self.wg_tx_rate)}",
            f"IP {self.public_ip} ({self.country})",
            (
                self.tr("header_stealth_on", "Stealth: ON")
                if self.isp_stealth_enabled.get()
                else self.tr("header_stealth_off", "Stealth: OFF")
            ),
        ]
        self.status_text.config(text=" | ".join(parts))

